def parse_timeline_spec(spec: str) -> list[tuple[int, str]]:
    if spec.strip() == "":
        return []

    result = []
    segments = spec.strip().split(';')
    for raw_segment in segments:
        segment = raw_segment.strip()
        if segment == "":
            raise ValueError("empty segment")
        if ':' not in segment:
            raise ValueError("missing colon")
        left, label = segment.split(':', 1)
        label = label.strip()
        if label == "":
            raise ValueError("empty label")
        if '-' not in left:
            raise ValueError("missing hyphen")
        start_str, end_str = left.split('-', 1)
        start_str = start_str.strip()
        end_str = end_str.strip()
        if start_str == "" or end_str == "":
            raise ValueError("missing bound")
        if not start_str.isdigit() or not end_str.isdigit():
            raise ValueError("non-integer bound")
        start = int(start_str)
        end = int(end_str)
        if start > end:
            raise ValueError("start greater than end")
        for t in range(start, end + 1):
            result.append((t, label))
    return result

def normalize_course_registrations(records):
    normalized = []
    seen = set()
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 4:
            raise TypeError("each record must be a 4-tuple")
        student_id, course_code, credits, grade = rec
        if not isinstance(student_id, str) or not isinstance(course_code, str):
            raise TypeError("student_id and course_code must be strings")
        if not isinstance(credits, int):
            raise TypeError("credits must be an integer")
        if not (isinstance(grade, (int, float)) or grade is None):
            raise TypeError("grade must be numeric or None")

        sid = student_id.strip().upper()
        ccode = course_code.strip().lower()
        if not sid or not ccode:
            raise ValueError("student_id and course_code must be non-empty")
        if credits < 1 or credits > 6:
            raise ValueError("credits out of range")
        if grade is not None:
            if grade < 0 or grade > 100:
                raise ValueError("grade out of range")
            grade_norm = float(grade)
        else:
            grade_norm = None

        item = (sid, ccode, credits, grade_norm)
        if item not in seen:
            seen.add(item)
            normalized.append(item)

    def sort_key(x):
        return (x[0], x[1], x[2], 0 if x[3] is None else 1, -1 if x[3] is None else x[3])

    return sorted(normalized, key=sort_key)

def normalize_csv_row(row, headers):
    if not isinstance(headers, (list, tuple)):
        headers = list(headers)
    if any((not isinstance(h, str)) or h == '' for h in headers):
        raise ValueError('headers must be unique non-empty strings')
    if len(set(headers)) != len(headers):
        raise ValueError('headers must be unique non-empty strings')
    if len(headers) == 0:
        if row == {} or row == [] or row == ():
            return {}
        raise ValueError('row must be empty when headers are empty')

    result = {h: None for h in headers}

    if isinstance(row, dict):
        for k in row:
            if k not in result:
                raise KeyError(k)
        for h in headers:
            if h in row:
                result[h] = row[h]
        return result

    if isinstance(row, (str, bytes, bytearray)):
        raise TypeError('row must be a dictionary or a non-string sequence')

    try:
        seq = list(row)
    except TypeError:
        raise TypeError('row must be a dictionary or a non-string sequence')

    if len(seq) > len(headers):
        raise ValueError('row has more values than headers')

    for i, value in enumerate(seq):
        result[headers[i]] = value
    return result

