def encode_rle_blocks(text: str) -> str:
    if text == "":
        return ""

    parts = []
    current = text[0]
    count = 1

    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            if count == 1:
                parts.append(current)
            else:
                parts.append(str(count) + current)
            current = ch
            count = 1

    if count == 1:
        parts.append(current)
    else:
        parts.append(str(count) + current)

    return "".join(parts)

def normalize_document_titles(titles):
    if not hasattr(titles, '__iter__'):
        raise TypeError('titles must be an iterable of strings')
    result = []
    for title in titles:
        if not isinstance(title, str):
            raise TypeError('all titles must be strings')
        stripped = title.strip()
        if stripped == '':
            result.append('')
            continue
        words = stripped.split()
        normalized_words = []
        for word in words:
            parts = word.split('-')
            normalized_parts = []
            for part in parts:
                if part == '':
                    normalized_parts.append('')
                else:
                    normalized_parts.append(part[:1].upper() + part[1:].lower())
            normalized_words.append('-'.join(normalized_parts))
        result.append(' '.join(normalized_words))
    return result

def parse_repeating_blocks(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    blocks = []
    total_int_sum = 0
    tags = set()

    for raw_block in text.split(';'):
        block = raw_block.strip()
        if block == '':
            continue
        if block.count(':') != 1:
            raise ValueError("each block must contain exactly one colon")
        name_part, payload_part = block.split(':', 1)
        name = name_part.strip()
        if name == '':
            raise ValueError("block name cannot be empty")

        payload = payload_part.strip()
        if payload == '':
            items = ()
        else:
            raw_items = payload.split(',')
            parsed_items = []
            for raw_item in raw_items:
                item = raw_item.strip()
                if item == '':
                    raise ValueError("empty item is not allowed")
                try:
                    value = int(item)
                except ValueError:
                    if item.isidentifier() and not (item[0] in '+-' or item.isdigit() and item.isdecimal()):
                        parsed_items.append(item.upper())
                        tags.add(item.upper())
                    elif item.isidentifier() and not item.isdecimal():
                        parsed_items.append(item.upper())
                        tags.add(item.upper())
                    else:
                        raise ValueError("invalid item")
                else:
                    parsed_items.append(value)
                    total_int_sum += value
            items = tuple(parsed_items)

        blocks.append({"name": name, "items": items})

    return {
        "blocks": blocks,
        "block_count": len(blocks),
        "total_int_sum": total_int_sum,
        "tags": tags,
    }

