def normalize_betting_round(actions):
    if not isinstance(actions, (list, tuple)):
        raise TypeError('actions must be a list or tuple')

    normalized = []
    allowed = {'fold', 'check', 'call', 'bet', 'raise'}
    zero_actions = {'fold', 'check', 'call'}
    for record in actions:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError('each action record must be a 3-item tuple')
        player, action, amount = record
        if not isinstance(player, str) or player.strip() == '':
            raise ValueError('player must be a non-empty string')
        if action not in allowed:
            raise ValueError('invalid action')
        if not isinstance(amount, int):
            raise ValueError('amount must be an integer')
        if amount < 0:
            raise ValueError('amount must be non-negative')
        if action in zero_actions:
            if amount != 0:
                raise ValueError('zero-amount actions must have amount 0')
        else:
            if amount <= 0:
                raise ValueError('bet/raise must have positive amount')
        normalized.append(f"{player.strip().upper()}:{action.upper()}:{amount}")
    return ' | '.join(normalized)

def summarize_deltas(nums):
    if not isinstance(nums, (list, tuple)):
        raise TypeError('nums must be a list or tuple of integers')
    count = len(nums)
    total = 0
    prefix_max = []
    current_max = None
    prev_sign = None
    sign_changes = 0
    for x in nums:
        if not isinstance(x, int):
            raise TypeError('all elements must be integers')
        total += x
        current_max = x if current_max is None or x > current_max else current_max
        prefix_max.append(current_max)
        if x != 0:
            sign = 1 if x > 0 else -1
            if prev_sign is not None and sign != prev_sign:
                sign_changes += 1
            prev_sign = sign
    return {
        'count': count,
        'total': total,
        'sign_changes': sign_changes,
        'prefix_max': prefix_max,
    }

from functools import lru_cache


def minimum_sticker_cost(target, stickers):
    if not target:
        return 0
    if not stickers:
        return -1

    # Count target characters in a compact tuple over sorted unique chars.
    chars = sorted(set(target))
    index = {ch: i for i, ch in enumerate(chars)}
    target_need = [0] * len(chars)
    for ch in target:
        target_need[index[ch]] += 1
    target_need = tuple(target_need)

    sticker_counts = []
    for label, cost in stickers:
        counts = [0] * len(chars)
        for ch in label:
            if ch in index:
                counts[index[ch]] += 1
        sticker_counts.append((tuple(counts), cost))

    @lru_cache(maxsize=None)
    def dp(need):
        if all(v == 0 for v in need):
            return 0

        best = None
        # Pick a required character to ensure progress.
        first_idx = next(i for i, v in enumerate(need) if v > 0)
        for counts, cost in sticker_counts:
            if counts[first_idx] == 0:
                continue
            new_need = list(need)
            progressed = False
            for i in range(len(new_need)):
                if new_need[i] > 0 and counts[i] > 0:
                    take = min(new_need[i], counts[i])
                    if take:
                        new_need[i] -= take
                        progressed = True
            if not progressed:
                continue
            sub = dp(tuple(new_need))
            if sub != -1:
                total = sub + cost
                if best is None or total < best:
                    best = total

        return -1 if best is None else best

    return dp(target_need)

def select_stable_prefix(words, max_total_length):
    if not isinstance(words, list):
        raise TypeError("words must be a list")
    if not isinstance(max_total_length, int):
        raise TypeError("max_total_length must be an integer")
    if max_total_length < 0:
        raise ValueError("max_total_length must be non-negative")
    total = 0
    result = []
    for w in words:
        if not isinstance(w, str):
            raise TypeError("all words must be strings")
        wlen = len(w)
        if total + wlen > max_total_length:
            break
        result.append(w)
        total += wlen
    return result

def normalize_packet_headers(headers):
    def normalize_value(value):
        if isinstance(value, (list, tuple)):
            items = []
            for part in value:
                if isinstance(part, (list, tuple)):
                    for sub in part:
                        items.append(sub)
                else:
                    items.append(part)
            cleaned = []
            seen = set()
            for item in items:
                if isinstance(item, str):
                    item = item.strip()
                else:
                    item = str(item)
                if item == '':
                    continue
                if item not in seen:
                    seen.add(item)
                    cleaned.append(item)
            cleaned.sort()
            return ','.join(cleaned)
        if isinstance(value, str):
            value = value.strip()
            if ',' in value:
                parts = [p.strip() for p in value.split(',')]
                cleaned = []
                seen = set()
                for part in parts:
                    if part == '':
                        continue
                    if part not in seen:
                        seen.add(part)
                        cleaned.append(part)
                cleaned.sort()
                return ','.join(cleaned)
            return value
        return str(value)

    result = []
    for item in headers:
        if isinstance(item, str):
            s = item.strip()
            sep_count = s.count('=') + s.count(':')
            if sep_count != 1:
                raise ValueError('string header must contain exactly one separator')
            if '=' in s:
                name, value = s.split('=', 1)
            else:
                name, value = s.split(':', 1)
            name = name.strip().lower()
            value = normalize_value(value.strip())
            result.append(f'{name}={value}')
        elif isinstance(item, (list, tuple)):
            if len(item) != 2:
                raise ValueError('tuple/list header must have length 2')
            name, value = item
            if not isinstance(name, str):
                name = str(name)
            name = name.strip().lower()
            value = normalize_value(value)
            result.append(f'{name}={value}')
        else:
            raise TypeError('unsupported header descriptor')
    return result

def normalize_inventory_changes(changes):
    if not isinstance(changes, list):
        raise TypeError('changes must be a list')
    totals = {}
    order = []
    for entry in changes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise TypeError('each change must be a 2-tuple')
        item, delta = entry
        if not isinstance(item, str) or not isinstance(delta, int):
            raise TypeError('item must be str and delta must be int')
        if item not in totals:
            totals[item] = 0
            order.append(item)
        totals[item] += delta
    parts = []
    for item in order:
        total = totals[item]
        if total != 0:
            parts.append(f'{item}:{total}')
    return ' | '.join(parts)

def normalize_menu_orders(orders):
    try:
        iterator = iter(orders)
    except TypeError:
        raise TypeError("orders must be iterable")

    customer_items = {}
    customer_order = []

    for record in iterator:
        try:
            pair = tuple(record)
        except TypeError:
            raise TypeError("each order record must be a 2-item iterable")
        if len(pair) != 2:
            raise TypeError("each order record must be a 2-item iterable")

        customer_id, items = pair
        if not isinstance(customer_id, str) or customer_id == "":
            raise ValueError("customer_id must be a non-empty string")

        try:
            items_iter = iter(items)
        except TypeError:
            raise TypeError("items must be iterable")

        if customer_id not in customer_items:
            customer_items[customer_id] = []
            customer_order.append(customer_id)

        seen = set(customer_items[customer_id])
        for item in items_iter:
            if not isinstance(item, str) or item == "":
                raise ValueError("item names must be non-empty strings")
            if item not in seen:
                customer_items[customer_id].append(item)
                seen.add(item)

    return [(cid, tuple(customer_items[cid])) for cid in sorted(customer_order)]

