def best_signal_window(signals, window):
    if not isinstance(window, int):
        raise ValueError("window must be an integer")
    if window < 0:
        raise ValueError("window must not be negative")

    vals = list(signals)
    for x in vals:
        if not isinstance(x, int):
            raise TypeError("all signal values must be integers")

    n = len(vals)
    if window == 0:
        return (0, 0, -1)
    if window > n:
        return None

    current = sum(vals[:window])
    best_sum = current
    best_start = 0

    for start in range(1, n - window + 1):
        current += vals[start + window - 1] - vals[start - 1]
        if current > best_sum:
            best_sum = current
            best_start = start

    return (best_sum, best_start, best_start + window - 1)

def encode_runlength_grid(grid):
    if not isinstance(grid, list):
        raise TypeError("grid must be a list")
    if grid == []:
        return []
    if any(not isinstance(row, list) for row in grid):
        raise TypeError("each row must be a list")
    row_len = len(grid[0])
    for row in grid:
        if len(row) != row_len:
            raise ValueError("all rows must have the same length")
        for x in row:
            if not isinstance(x, int):
                raise TypeError("all grid elements must be integers")
    flat = [x for row in grid for x in row]
    if not flat:
        return []
    out = []
    current = flat[0]
    count = 1
    for x in flat[1:]:
        if x == current:
            count += 1
        else:
            out.append((current, count))
            current = x
            count = 1
    out.append((current, count))
    return out

def normalize_event_schedule(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    if not events:
        return ''

    normalized = []
    for item in events:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError('each event must be a tuple of length 3')
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('start and end must be integers')
        if not isinstance(label, str):
            raise TypeError('label must be a string')
        if start > end:
            raise ValueError('start must be less than or equal to end')
        start_h, start_m = divmod(start, 60)
        end_h, end_m = divmod(end, 60)
        start_str = f'{start_h:02d}:{start_m:02d}'
        end_str = f'{end_h:02d}:{end_m:02d}'
        normalized.append((start, end, label, f'{start_str}-{end_str}|{label}'))

    normalized.sort(key=lambda x: (x[0], x[1], x[2]))
    return ';'.join(item[3] for item in normalized)

def parse_ledger(lines):
    result = {}
    for raw in lines:
        line = raw.strip()
        if not line:
            raise ValueError('Invalid line')
        parts = line.split(' ')
        if len(parts) != 3 or any(p == '' for p in parts):
            raise ValueError('Invalid line')
        op, category, amount_text = parts
        if op not in ('ADD', 'SUB'):
            raise ValueError('Invalid operation')
        if any(ch.isspace() for ch in category) or category == '':
            raise ValueError('Invalid category')
        try:
            amount = int(amount_text, 10)
        except Exception:
            raise ValueError('Invalid amount')
        if category not in result:
            result[category] = {'total_in': 0, 'total_out': 0, 'balance': 0}
        entry = result[category]
        contribution = amount if op == 'ADD' else -amount
        if contribution >= 0:
            entry['total_in'] += contribution
        else:
            entry['total_out'] += -contribution
        entry['balance'] += contribution
    return result

