def parse_inventory_updates(records):
    inventory = {}
    for record in records:
        if not isinstance(record, str):
            raise ValueError('Each record must be a string')
        parts = record.split(':')
        if len(parts) != 3:
            raise ValueError('Malformed record')
        action, sku, qty_str = parts
        if action not in {'ADD', 'REMOVE', 'SET'}:
            raise ValueError('Unknown action')
        if not sku or ':' in sku:
            raise ValueError('Invalid SKU')
        if qty_str == '' or qty_str.startswith('-'):
            raise ValueError('Invalid quantity')
        if not qty_str.isdigit():
            raise ValueError('Invalid quantity')
        qty = int(qty_str)
        current = inventory.get(sku, 0)
        if action == 'ADD':
            inventory[sku] = current + qty
        elif action == 'REMOVE':
            new_value = current - qty
            if new_value < 0:
                raise ValueError('Inventory cannot go below zero')
            inventory[sku] = new_value
        else:  # SET
            inventory[sku] = qty
    return inventory

