            'symbol_lengths': {},
            'first_symbol': None,
            'last_symbol': None,
            'num_segments': 0,
        }

    segments = text.split(',')
    if any(seg == '' for seg in segments):
        raise ValueError('malformed run list')

    symbol_lengths = {}
    total_length = 0
    first_symbol = None
    last_symbol = None

    for seg in segments:
