def decode_run_metadata(text):
    if text is None:
        return {}
    s = text.strip()
    if not s:
        return {}

    result = {}
    allowed_statuses = {"ok", "fail", "skip"}

    def valid_run_id(run_id):
        if not run_id:
            return False
        for ch in run_id:
            if ch.isspace() or ch in ",;":
                return False
            if not (ch.isalnum() or ch in "_-"):
                return False
        return True

    for record in s.split(";"):
        rec = record.strip()
        if not rec:
            continue
        parts = [p.strip() for p in rec.split(",")]
        if len(parts) != 3:
            continue
        run_id, status, score_text = parts
        if not valid_run_id(run_id):
            continue
        if status not in allowed_statuses:
            continue
        try:
            score = int(score_text)
        except Exception:
            continue
        if str(score) != score_text and str(score) != score_text.lstrip("+"):
            # Reject formats like "01" or "+3" or embedded whitespace.
            # int() may accept them, but the task requires decimal integer notation.
            if score_text not in ("0", "-0"):
                if score_text != str(score):
                    continue
        result[run_id] = (status, score)
    return result

