def canonicalize_signal_pattern(pattern: str) -> str:
    s = pattern.strip()
    if not s:
        return ""

    def parse_int(token: str) -> int:
        token = token.strip()
        if not token:
            raise ValueError("empty integer token")
        if token[0] in "+-":
            sign = token[0]
            digits = token[1:]
        else:
            sign = ""
            digits = token
        if not digits or not digits.isdigit():
            raise ValueError(f"invalid integer token: {token!r}")
        return int(sign + digits)

    values = []
    for raw_token in s.split(","):
        token = raw_token.strip()
        if not token:
            raise ValueError("empty token")
        if ".." in token:
            parts = token.split("..")
            if len(parts) != 2:
                raise ValueError(f"invalid range token: {token!r}")
            left = parts[0].strip()
            right = parts[1].strip()
            if not left or not right:
                raise ValueError(f"invalid range token: {token!r}")
            start = parse_int(left)
            end = parse_int(right)
            step = 1 if start <= end else -1
            values.extend(range(start, end + step, step))
        else:
            values.append(parse_int(token))

    seen = set()
    unique = []
    for v in values:
        if v not in seen:
            seen.add(v)
            unique.append(v)

    unique.sort()
    return ",".join(str(v) for v in unique)

def merge_change_logs(logs):
    if not isinstance(logs, list):
        raise ValueError('logs must be a list')

    grouped = {}
    order = {}
    stream_index = 0

    for stream_item in logs:
        if not (isinstance(stream_item, tuple) and len(stream_item) == 2):
            raise ValueError('each stream item must be a (str, list) tuple')
        stream_name, entries = stream_item
        if not isinstance(stream_name, str) or not isinstance(entries, list):
            raise ValueError('each stream item must be a (str, list) tuple')

        entry_index = 0
        for entry in entries:
            if not isinstance(entry, dict):
                raise ValueError('each event must be a dict')
            for key in ('day', 'version', 'changes'):
                if key not in entry:
                    raise ValueError('missing required key')
            day = entry['day']
            version = entry['version']
            changes = entry['changes']
            if not isinstance(day, int):
                raise ValueError('day must be an integer')
            if not isinstance(version, str):
                raise ValueError('version must be a string')
            if not isinstance(changes, list) or any(not isinstance(c, str) for c in changes):
                raise ValueError('changes must be a list of strings')

            key = (day, version)
            if key not in grouped:
                grouped[key] = {'day': day, 'version': version, 'changes': set(changes), 'sources': {stream_name}}
                order[key] = (day, version, stream_index, entry_index)
            else:
                grouped[key]['changes'].update(changes)
                grouped[key]['sources'].add(stream_name)
            entry_index += 1
        stream_index += 1

    items = sorted(grouped.items(), key=lambda kv: order[kv[0]])
    result = []
    for (_, _), payload in items:
        result.append({
            'day': payload['day'],
            'version': payload['version'],
            'changes': sorted(payload['changes']),
            'sources': sorted(payload['sources']),
        })
    return result

def decode_repeating_blocks(s: str) -> str:
    stack = []  # each item: (previous_string, repeat_count)
    current = []
    num = None

    for ch in s:
        if ch.isdigit():
            if num is None:
                num = ch
            else:
                num += ch
        elif ch == '[':
            if num is None:
                raise ValueError('missing repeat count before [')
            k = int(num)
            if k <= 0:
                raise ValueError('repeat count must be positive')
            stack.append((''.join(current), k))
            current = []
            num = None
        elif ch == ']':
            if num is not None:
                raise ValueError('digits must be followed by [')
            if not stack:
                raise ValueError('unmatched closing bracket')
            prev, k = stack.pop()
            segment = ''.join(current) * k
            current = [prev + segment]
        else:
            if num is not None:
                raise ValueError('digits must be followed by [')
            current.append(ch)

    if num is not None:
        raise ValueError('trailing repeat count')
    if stack:
        raise ValueError('unbalanced opening bracket')
    return ''.join(current)

