    for x in points:
        if type(x) is not int:
            raise TypeError("all points must be integers")
        items.append(x)
    if not items:
        return []
    uniq = sorted(set(items))
    result = []
    start = prev = uniq[0]
    for x in uniq[1:]:
        if x == prev + 1:
            prev = x
        else:
            result.append((start, prev))
            start = prev = x
    result.append((start, prev))
    return result

