    for item in stream:
        if not is_valid_int(item):
            raise TypeError("stream must contain only integers")
        if not has_any:
            current_value = item
            current_len = 1
            has_any = True
        elif item == current_value:
            current_len += 1
        else:
            runs.append((current_value, current_len))
            parity_chars.append('E' if current_value % 2 == 0 else 'O')
            current_value = item
            current_len = 1
    if not has_any:
        return {'runs': [], 'max_run_value': None, 'parity_signature': ''}

    runs.append((current_value, current_len))
    parity_chars.append('E' if current_value % 2 == 0 else 'O')

    max_run_value = runs[0][0]
    max_len = runs[0][1]
    for value, length in runs[1:]:
        if length > max_len:
            max_len = length
            max_run_value = value

    return {
        'runs': runs,
        'max_run_value': max_run_value,
        'parity_signature': ''.join(parity_chars),
    }

