def normalize_bet_records(records):
    def is_int_like(x):
        if isinstance(x, bool):
            return False
        if isinstance(x, int):
            return True
        if isinstance(x, str):
            s = x.strip()
            if s in ('', '+', '-'):
                return False
            if s[0] in '+-':
                s = s[1:]
            return s.isdigit()
        return False

    def to_int(x):
        if isinstance(x, int) and not isinstance(x, bool):
            return x
        return int(str(x).strip())

    def to_float(x):
        if isinstance(x, bool) or x is None:
            raise ValueError
        if isinstance(x, int):
            return float(x)
        if isinstance(x, float):
            if x != x or x in (float('inf'), float('-inf')):
                raise ValueError
            return float(x)
        if isinstance(x, str):
            s = x.strip()
            if s == '':
                raise ValueError
            val = float(s)
            if val != val or val in (float('inf'), float('-inf')):
                raise ValueError
            return val
        raise ValueError

    out = []
    for rec in records:
        try:
            if not isinstance(rec, dict):
                continue
            if 'amount' not in rec or 'odds' not in rec or 'status' not in rec or 'tags' not in rec:
                continue
            if rec['status'] not in ('win', 'loss', 'push'):
                continue
            if not isinstance(rec['tags'], list) or any(not isinstance(t, str) for t in rec['tags']):
                continue
            if isinstance(rec['amount'], bool) or not is_int_like(rec['amount']):
                continue
            amount = to_int(rec['amount'])
            odds = to_float(rec['odds'])
            tags = tuple(sorted(set(rec['tags'])))
            status = rec['status']
            if status == 'win':
                payout = amount * odds
            elif status == 'loss':
                payout = -amount
            else:
                payout = 0.0
            normalized = {'amount': amount, 'odds': float(odds), 'status': status, 'tags': tags, 'payout': payout}
            if 'memo' in rec:
                normalized['memo'] = rec['memo']
            out.append(normalized)
        except Exception:
            continue
    return out

def normalize_event_schedule(events):
