def normalize_log_records(records):
    allowed = {"INFO", "WARN", "ERROR", "DEBUG"}
    normalized = []
    summary = {}

    for record in records:
        if not isinstance(record, str):
            continue
        raw = record.strip()
        parts = raw.split("|")
        if len(parts) not in (2, 3):
            continue
        parts = [p.strip() for p in parts]
        level = parts[0]
        if level not in allowed:
            continue
        if len(parts) == 2:
            timestamp = "UNKNOWN"
            message = parts[1]
        else:
            timestamp = parts[1]
            message = parts[2]
            if timestamp == "":
                continue
        normalized.append(f"{level}|{timestamp}|{message}")
        summary[level] = summary.get(level, 0) + 1

    return normalized, summary

def normalize_tally(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')

    totals = {}
    for item in events:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError('each event must be a 2-element sequence')
        label, delta = item
        if not isinstance(label, str):
            raise TypeError('label must be a string')
        if not isinstance(delta, int):
            raise TypeError('delta must be an integer')
        totals[label] = totals.get(label, 0) + delta

    kept = [(label, total) for label, total in totals.items() if total != 0]
    kept.sort(key=lambda x: x[0])
    return ';'.join(f'{label}={total}' for label, total in kept)

def normalize_record_paths(records):
    if not isinstance(records, list):
        raise TypeError('records must be a list')

    def normalize(s):
        if not isinstance(s, str):
            raise TypeError('path values must be strings')
        parts = []
        for segment in s.split('/'):
            if segment == '' or segment == '.':
                continue
            if segment == '..':
                if parts and parts[-1] != '..':
                    parts.pop()
                else:
                    parts.append('..')
            else:
                parts.append(segment)
        return '/'.join(parts) if parts else '.'

    out = []
    for record in records:
        if 'name' not in record:
            raise KeyError('name')
        if 'path' not in record:
            raise KeyError('path')
        new_record = {}
        for key in record:
            if key == 'path':
                new_record[key] = normalize(record[key])
            elif key == 'alias':
                value = record[key]
                new_record[key] = None if value is None else normalize(value)
            elif key == 'metadata':
                value = record[key]
                new_record[key] = value.copy() if isinstance(value, dict) else value
            else:
                new_record[key] = record[key]
        out.append(new_record)
    return out

def merge_schedules(ranges):
    for item in ranges:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each interval must be a pair of two integers')
        a, b = item
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError('each interval must be a pair of two integers')
        if a > b:
            raise ValueError('interval start must not exceed end')

    intervals = [item for item in ranges if item[0] < item[1]]
    if not intervals:
        return []

    intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [intervals[0]]
    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

