def summarize_plateau_runs(values):
    iterator = iter(values)
    try:
        first = next(iterator)
    except StopIteration:
        return {
            'run_count': 0,
            'longest_run_length': 0,
            'run_lengths_by_value': {},
            'plateau_starts': []
        }

    run_count = 1
    longest_run_length = 1
    run_lengths_by_value = {first: 1}
    plateau_starts = []

    current_value = first
    current_run_length = 1
    index = 0
    current_run_start = 0

    for index, item in enumerate(iterator, start=1):
        run_lengths_by_value[item] = run_lengths_by_value.get(item, 0) + 1
        if item == current_value:
            current_run_length += 1
        else:
            if current_run_length >= 2:
                plateau_starts.append(current_run_start)
            longest_run_length = max(longest_run_length, current_run_length)
            run_count += 1
            current_value = item
            current_run_length = 1
            current_run_start = index

    if current_run_length >= 2:
        plateau_starts.append(current_run_start)
    longest_run_length = max(longest_run_length, current_run_length)

    return {
        'run_count': run_count,
        'longest_run_length': longest_run_length,
        'run_lengths_by_value': run_lengths_by_value,
        'plateau_starts': plateau_starts,
    }

def render_number_grid(numbers: list[int], width: int) -> str:
    if width < 1:
        raise ValueError("width must be at least 1")
    if not numbers:
        return ""

    def fmt(n: int) -> str:
        if n < 0:
            return f"({abs(n)})"
        return str(n)

    rows = []
    for i in range(0, len(numbers), width):
        row_items = [fmt(n) for n in numbers[i:i + width]]
        rows.append(" ".join(row_items))
    return "\n".join(rows)

def normalize_event_schedule(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    seen = set()
    grouped = {}

    for record in events:
        if not isinstance(record, tuple) or len(record) != 4:
            raise ValueError("each event must be a 4-tuple")
        day, start, end, label = record
        if not isinstance(day, int) or day < 0:
            raise ValueError("day must be a non-negative integer")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("start and end must be integers")
        if start < 0:
            raise ValueError("start must be non-negative")
        if end < start:
            raise ValueError("end must be >= start")
        if not isinstance(label, str):
            raise ValueError("label must be a string")

        key = (day, start, end, label)
        if key in seen:
            continue
        seen.add(key)
        grouped.setdefault(day, []).append((start, end, label))

    result = []
    for day in sorted(grouped):
        day_events = sorted(grouped[day], key=lambda x: (x[0], x[1], x[2]))
        result.append((day, day_events))
    return result

def canonicalize_tag_list(tags):
    result = []
    seen = set()
    for tag in tags:
        cleaned = tag.strip().lower()
        if not cleaned:
            continue
        if any(ch.isspace() for ch in cleaned):
            continue
        if cleaned not in seen:
            seen.add(cleaned)
            result.append(cleaned)
    return result

def normalize_grid_path(grid, path):
    def invalid(reason):
        return {"valid": False, "normalized": [], "reason": reason}

    # Validate grid
    if not isinstance(grid, list) or len(grid) == 0:
        return invalid("invalid grid")
    first_row_len = None
    for row in grid:
        if not isinstance(row, list) or len(row) == 0:
            return invalid("invalid grid")
        if first_row_len is None:
            first_row_len = len(row)
        elif len(row) != first_row_len:
            return invalid("invalid grid")
        for cell in row:
            if not isinstance(cell, int):
                return invalid("invalid grid")

    # Validate path container
    if not isinstance(path, list):
        return invalid("invalid path")

    rows = len(grid)
    cols = first_row_len
    normalized = []
    seen = set()

    for item in path:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            return invalid("invalid coordinate")
        r, c = item
        if not isinstance(r, int) or not isinstance(c, int):
            return invalid("invalid coordinate")
        if not (0 <= r < rows and 0 <= c < cols):
            return invalid("out of bounds")
        coord = (r, c)
        if coord in seen:
            return invalid("repeated coordinate")
        if normalized:
            pr, pc = normalized[-1]
            if abs(pr - r) + abs(pc - c) != 1:
                return invalid("non-adjacent step")
        seen.add(coord)
        normalized.append(coord)

    return {"valid": True, "normalized": normalized, "reason": "ok"}

