def parse_ledger_balance(lines):
    balance = None
    saw_instruction = False
    for raw in lines:
        if raw is None:
            raise ValueError("invalid instruction")
        line = raw.strip()
        if not line:
            continue
        saw_instruction = True
        parts = line.split()
        if len(parts) != 2:
            raise ValueError("invalid instruction")
        cmd, arg_text = parts
        try:
            value = int(arg_text)
        except Exception:
            raise ValueError("invalid integer")
        if cmd == "SET":
            balance = value
        elif cmd == "ADD":
            if balance is None:
                raise ValueError("missing initial SET")
            balance += value
        elif cmd == "SUB":
            if balance is None:
                raise ValueError("missing initial SET")
            balance -= value
        elif cmd == "MUL":
            if balance is None:
                raise ValueError("missing initial SET")
            balance *= value
        elif cmd == "DIV":
            if balance is None:
                raise ValueError("missing initial SET")
            if value == 0:
                raise ZeroDivisionError("division by zero")
            balance //= value
        else:
            raise ValueError("unknown command")
    if not saw_instruction:
        raise ValueError("no instructions")
    if balance is None:
        raise ValueError("missing initial SET")
    return balance

