    out = []
    in_sep = False
    for ch in s:
        if ch.isspace() or ch == '_' or ch == '-':
            if not in_sep:
                out.append('-')
                in_sep = True
        else:
            in_sep = False
            if 'a' <= ch <= 'z' or '0' <= ch <= '9':
                out.append(ch)
            # other characters are discarded

    result = ''.join(out)

    # Collapse any accidental repeated hyphens from adjacent separator groups.
    collapsed = []
