    statements = []
    current = []
    in_string = False
    i = 0
    n = len(script)

    while i < n:
        ch = script[i]
        if in_string:
            current.append(ch)
            if ch == "'":
                if i + 1 < n and script[i + 1] == "'":
                    current.append("'")
                    i += 1
                else:
                    in_string = False
        else:
            if ch == "'":
