    if stmt:
        statements.append(stmt)
    return statements

def normalize_route(routes):
    def validate_segment(seg):
        if not isinstance(seg, str):
            raise TypeError("segment must be a string")
        if seg == "":
            raise ValueError("empty segment")
        if "/" in seg:
            raise ValueError("segment cannot contain '/'")

    def walk(items, prefix, depth, out):
        if not isinstance(items, list):
            raise TypeError("children must be a list")
        for item in items:
            if isinstance(item, str):
                validate_segment(item)
                path = item if not prefix else prefix + "/" + item
                out.append((path, depth))
            elif isinstance(item, tuple):
                if len(item) != 2:
                    raise TypeError("tuple must have exactly two items")
                name, children = item
                validate_segment(name)
                if not isinstance(children, list):
                    raise TypeError("children must be a list")
                new_prefix = name if not prefix else prefix + "/" + name
                walk(children, new_prefix, depth + 1, out)
            else:
                raise TypeError("invalid route item")

    result = []
    walk(routes, "", 0, result)
    return result

def normalize_channels(data, axis):
    if axis not in (0, 1):
        raise ValueError("axis must be 0 or 1")
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("data must be a non-empty 2D list")
    if not all(isinstance(row, list) for row in data):
        raise ValueError("data must be a 2D list")
    row_len = len(data[0])
    if row_len == 0:
        raise ValueError("data must not contain empty rows")
    for row in data:
        if len(row) != row_len:
            raise ValueError("data must be rectangular")
        for x in row:
            if not isinstance(x, (int, float)) or isinstance(x, bool):
                raise ValueError("data must contain only numbers")
    rows = len(data)
    cols = row_len
    out = [[0.0 for _ in range(cols)] for _ in range(rows)]
    if axis == 1:
        for i, row in enumerate(data):
            denom = sum(abs(float(x)) for x in row)
            if denom == 0:
                continue
            for j, x in enumerate(row):
                out[i][j] = float(x) / denom
    else:
        col_sums = [0.0] * cols
        for j in range(cols):
            col_sums[j] = sum(abs(float(data[i][j])) for i in range(rows))
        for i in range(rows):
            for j in range(cols):
                denom = col_sums[j]
                if denom != 0:
                    out[i][j] = float(data[i][j]) / denom
    return out

