        return 0

    total = 0
    segments = spec.split("|")
    for segment in segments:
        parts = segment.split("-")
        if len(parts) != 2:
            raise ValueError("malformed segment")
        start_s, end_s = parts
        if start_s == "" or end_s == "":
            raise ValueError("malformed segment")
        if not start_s.isdigit() or not end_s.isdigit():
            raise ValueError("malformed segment")
        start = int(start_s)
        end = int(end_s)
        if start > end:
            raise ValueError("start greater than end")
        total += end - start
    return total

