            raise ValueError('row has wrong number of fields')
        result.append(dict(zip(header_parts, parts)))
    return result

def normalize_prerequisite_plan(plan):
    valid = {}
    order = []
    for item in plan:
        if not isinstance(item, tuple) or len(item) != 2:
            continue
        course, prereqs = item
        if not isinstance(course, str):
            continue
        if course not in valid:
            valid[course] = []
            order.append(course)
        seen = set(valid[course])
        try:
            iterator = iter(prereqs)
        except TypeError:
            continue
        for p in iterator:
            if isinstance(p, str) and p not in seen:
                valid[course].append(p)
                seen.add(p)
    if not order:
        return ((), ())
    sorted_courses = tuple(sorted(order))
    adjacency = tuple(tuple(valid[c]) for c in sorted_courses)
    return (sorted_courses, adjacency)

def normalize_event_schedule(events):
    valid = []
    for item in events:
        if not isinstance(item, tuple) or len(item) != 4:
            continue
        start, end, label, priority = item
        if not isinstance(start, int) or not isinstance(end, int):
            continue
        if not isinstance(label, str) or not isinstance(priority, int):
            continue
        if start >= end:
            continue
        valid.append((start, end, label, priority))

    by_label = {}
    for start, end, label, priority in valid:
        by_label.setdefault(label, []).append((start, end, priority))

    merged = []
    for label, intervals in by_label.items():
        intervals.sort(key=lambda x: (x[0], x[1], -x[2]))
        cur_s, cur_e, cur_p = intervals[0]
        for s, e, p in intervals[1:]:
            if s <= cur_e:
                if e > cur_e:
                    cur_e = e
                if p > cur_p:
                    cur_p = p
                if s < cur_s:
                    cur_s = s
            else:
                merged.append((cur_s, cur_e, label, cur_p))
                cur_s, cur_e, cur_p = s, e, p
        merged.append((cur_s, cur_e, label, cur_p))

    merged.sort(key=lambda x: (x[0], x[1], x[2]))
    return merged

def compress_runs(sequence):
    if not isinstance(sequence, (list, tuple)):
        raise TypeError("sequence must be a list or tuple of integers")

    result = []
    if len(sequence) == 0:
        return result

    first = sequence[0]
    if type(first) is not int:
        raise TypeError("all elements must be integers")

    current = first
    count = 1

    for item in sequence[1:]:
        if type(item) is not int:
            raise TypeError("all elements must be integers")
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1

    result.append((current, count))
    return result

def normalize_sensor_stream(data):
    result = []
    for item in data:
        if item == 'gap':
            result.append('gap')
