def normalize_sensor_events(events):
    latest = {}
    for item in events:
        if not isinstance(item, tuple) or len(item) != 3:
            continue
        timestamp, sensor_id, reading = item
        if not isinstance(timestamp, int) or not isinstance(sensor_id, str):
