        latest[sensor_id] = (timestamp, sensor_id, reading)
    return sorted(latest.values(), key=lambda x: (x[0], x[1]))

def normalize_interval(interval):
    def to_int(x):
        if isinstance(x, bool):
            raise ValueError('invalid integer')
        if not isinstance(x, int):
            raise ValueError('invalid integer')
        return x

    def normalize_pair(a, b):
        a = to_int(a)
        b = to_int(b)
        if a <= b:
            return (a, b + 1)
        return (b, a + 1)

    if isinstance(interval, (list, tuple)):
        if len(interval) != 2:
            raise TypeError('interval must have exactly two items')
        return normalize_pair(interval[0], interval[1])

    if isinstance(interval, str):
        s = interval.strip()
        sep = None
        if '..' in s:
            parts = s.split('..')
            sep = '..'
        elif ':' in s:
            parts = s.split(':')
            sep = ':'
        else:
            # dash parsing with support for negative numbers
            if s.count('-') < 1:
                raise ValueError('invalid interval string')
            # find separator dash: last dash that is not part of first number's sign
            idx = None
            for i in range(1, len(s)):
                if s[i] == '-':
                    idx = i
                    break
            if idx is None:
                raise ValueError('invalid interval string')
            parts = [s[:idx], s[idx+1:]]
            sep = '-'
        if len(parts) != 2:
            raise ValueError('invalid interval string')
        left = parts[0].strip()
        right = parts[1].strip()
        if left == '' or right == '':
            raise ValueError('invalid interval string')
        try:
            a = int(left)
            b = int(right)
        except Exception:
            raise ValueError('invalid interval string')
        return normalize_pair(a, b)

    raise TypeError('unsupported interval type')

def plan_ledger(payments, cap):
    if not isinstance(payments, (list, tuple)):
        raise TypeError("payments must be a list or tuple")
    if not isinstance(cap, int):
        raise TypeError("cap must be an integer")
    if cap < 0:
        raise ValueError("cap must be non-negative")

    total = 0
    clipped = []
    net_positive = 0
    first_over_cap = -1

    for i, p in enumerate(payments):
        total += p
        if p > cap:
            cp = cap
        elif p < -cap:
            cp = -cap
        else:
            cp = p
        clipped.append(cp)
        if cp > 0:
            net_positive += cp
        if first_over_cap == -1 and abs(p) > cap:
            first_over_cap = i

    return {
        "count": len(payments),
        "sum": total,
        "clipped": clipped,
        "net_positive": net_positive,
        "first_over_cap": first_over_cap,
    }

def normalize_channel_labels(labels):
