def parse_duration(expr):
    if not isinstance(expr, str) or expr == "":
        raise ValueError("invalid duration expression")

    multipliers = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    seen = set()
    total = 0
    i = 0
    n = len(expr)

    while i < n:
        if not expr[i].isdigit():
            raise ValueError("invalid duration expression")
        start = i
        while i < n and expr[i].isdigit():
            i += 1
        if i >= n:
            raise ValueError("invalid duration expression")
        unit = expr[i]
        if unit not in multipliers:
            raise ValueError("invalid duration expression")
        if unit in seen:
            raise ValueError("invalid duration expression")
        seen.add(unit)
        amount = int(expr[start:i])
        total += amount * multipliers[unit]
        i += 1

    return total

def sanitize_column_names(headers):
