def summarize_digit_runs(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    lengths = []
    values = []
    current = []

    def flush_run():
        if current:
            run = ''.join(current)
            lengths.append(len(run))
            values.append(int(run))
            current.clear()

    for ch in text:
        if '0' <= ch <= '9':
            current.append(ch)
        else:
            flush_run()
    flush_run()

    return {
        'count': len(lengths),
        'lengths': lengths,
        'values': values,
        'longest': max(lengths) if lengths else 0,
    }

