def normalize_schedule(entries):
    if entries == []:
        return []

    expanded = []
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 3:
            raise ValueError('invalid entry')
        start, end, label = entry
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('invalid entry')
        if not (0 <= start <= 1439) or not (0 <= end <= 1439):
            raise ValueError('invalid entry')
        if not isinstance(label, str) or label == '':
            raise ValueError('invalid entry')

        if start <= end:
            expanded.append((start, end, label))
        else:
            expanded.append((start, 1439, label))
            expanded.append((0, end, label))

    by_label = {}
    for start, end, label in expanded:
        by_label.setdefault(label, []).append((start, end))

    result = []
    for label in sorted(by_label):
        intervals = sorted(by_label[label])
        merged = []
        for s, e in intervals:
            if not merged:
                merged.append([s, e])
            else:
                ps, pe = merged[-1]
                if s <= pe + 1:
                    merged[-1][1] = max(pe, e)
                else:
                    merged.append([s, e])
        for s, e in merged:
            result.append((s, e, label))

    result.sort(key=lambda x: (x[2], x[0]))
    return result

def normalize_inventory(records):
    summary = {}
    if not isinstance(records, list):
        return summary
    for rec in records:
        if not isinstance(rec, dict):
            continue
        required = ('product', 'quantity', 'unit', 'location')
        if any(k not in rec for k in required):
            continue
        product = rec['product']
        quantity = rec['quantity']
        unit = rec['unit']
        location = rec['location']
        if not isinstance(product, str) or not isinstance(unit, str) or not isinstance(location, str) or not isinstance(quantity, int):
            continue
        p = product.strip().lower()
        u = unit.strip()
        loc = location.strip().lower()
        if p not in summary:
            summary[p] = {'quantity': 0, 'locations': set(), 'units': set()}
        summary[p]['quantity'] += quantity
        summary[p]['locations'].add(loc)
        summary[p]['units'].add(u)
    result = {}
    for p in sorted(summary):
        result[p] = {
            'quantity': summary[p]['quantity'],
            'locations': sorted(summary[p]['locations']),
            'units': sorted(summary[p]['units'])
        }
    return result

