def apply_piecewise_pricing(prices, discount_rules):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    if not isinstance(discount_rules, list):
        raise TypeError("discount_rules must be a list")

    for p in prices:
        if not isinstance(p, int):
            raise TypeError("each price must be an int")
        if p < 0:
            raise ValueError("prices must be non-negative")

    validated_rules = []
    for rule in discount_rules:
        if not isinstance(rule, tuple) or len(rule) != 2:
            raise TypeError("each rule must be a 2-tuple")
        min_price, discount_percent = rule
        if not isinstance(min_price, int) or not isinstance(discount_percent, int):
            raise TypeError("rule elements must be ints")
        if min_price < 0:
            raise ValueError("min_price must be non-negative")
        if discount_percent < 0 or discount_percent > 100:
            raise ValueError("discount_percent must be between 0 and 100")
        validated_rules.append((min_price, discount_percent))

    if not validated_rules:
        return prices.copy()

    result = []
    for price in prices:
        best_min = None
        best_discount = 0
        for min_price, discount_percent in validated_rules:
            if price >= min_price:
                if best_min is None or min_price > best_min or min_price == best_min:
                    best_min = min_price
                    best_discount = discount_percent
        final_price = price - (price * best_discount // 100)
        result.append(final_price)
    return result

def render_numeric_spiral(n: int) -> list[str]:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return []

    grid = [[0] * n for _ in range(n)]
    top, bottom, left, right = 0, n - 1, 0, n - 1
    value = 1

    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            grid[top][c] = value
            value += 1
        top += 1

        for r in range(top, bottom + 1):
            grid[r][right] = value
            value += 1
        right -= 1

        if top <= bottom:
            for c in range(right, left - 1, -1):
                grid[bottom][c] = value
                value += 1
            bottom -= 1

        if left <= right:
            for r in range(bottom, top - 1, -1):
                grid[r][left] = value
                value += 1
            left += 1

    width = len(str(n * n))
    return [" ".join(str(cell).rjust(width) for cell in row) for row in grid]

