def parse_measurement(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    s = text.strip()
    if not s:
        raise ValueError('empty input')

    i = 0
    n = len(s)
    if s[i] in '+-':
        i += 1
        if i >= n:
            raise ValueError('missing number')

    start_num = i
    has_digit = False
    has_dot = False
    while i < n:
        ch = s[i]
        if ch.isdigit():
            has_digit = True
            i += 1
        elif ch == '.':
            if has_dot:
                raise ValueError('multiple dots')
            has_dot = True
            i += 1
        else:
            break

    if not has_digit:
        raise ValueError('missing digits')
    if i == n:
        raise ValueError('missing unit')

    unit = s[i:]
    if not unit.isalpha() or any(c.isspace() for c in unit):
        raise ValueError('invalid unit')

    num_str = s[:i]
    if num_str in ('+', '-', '.', '+.', '-.'):
        raise ValueError('invalid number')

    value = float(num_str)
    if value.is_integer():
        value = int(value)
    return (value, unit)

