def best_signal_window(values, window_size):
    if not isinstance(window_size, int) or window_size < 0:
        raise ValueError("window_size must be a non-negative integer")
    if window_size == 0:
        return ()
    try:
        seq = tuple(values)
    except TypeError:
        raise TypeError("values must be iterable")
    n = len(seq)
    if window_size > n:
        return None
    current_sum = sum(seq[:window_size])
    best_sum = current_sum
    best_start = 0
    for start in range(1, n - window_size + 1):
        current_sum += seq[start + window_size - 1] - seq[start - 1]
        if current_sum > best_sum:
            best_sum = current_sum
            best_start = start
    return (best_start, best_sum, tuple(seq[best_start:best_start + window_size]))

