def summarize_runs(readings):
    if not isinstance(readings, list):
        raise TypeError("readings must be a list")
    for x in readings:
        if not isinstance(x, int):
            raise TypeError("all readings must be integers")

    if not readings:
        return {
            'total_runs': 0,
            'longest_run_value': None,
            'longest_run_length': 0,
            'run_lengths': [],
            'value_changes': 0,
        }

    run_lengths = []
    run_values = []
    current_value = readings[0]
    current_length = 1
    value_changes = 0

    for x in readings[1:]:
        if x == current_value:
            current_length += 1
        else:
            run_lengths.append(current_length)
            run_values.append(current_value)
            value_changes += 1
            current_value = x
            current_length = 1

    run_lengths.append(current_length)
    run_values.append(current_value)

    longest_run_length = max(run_lengths)
    tied_values = [v for v, l in zip(run_values, run_lengths) if l == longest_run_length]
    longest_run_value = min(tied_values)

    return {
        'total_runs': len(run_lengths),
        'longest_run_value': longest_run_value,
        'longest_run_length': longest_run_length,
        'run_lengths': run_lengths,
        'value_changes': value_changes,
    }

