        for item, data in inv.items():
            if not isinstance(item, str) or not isinstance(data, dict):
                raise ValueError("invalid inventory entry")
            if "qty" not in data or "price" not in data:
                raise ValueError("missing required keys")
            if not isinstance(data["qty"], int) or not isinstance(data["price"], int):
                raise ValueError("qty and price must be integers")

    validate_inventory(left)
    validate_inventory(right)

    result = {}
    all_items = sorted(set(left) | set(right))
    for item in all_items:
        if item in left and item in right:
            left_data = left[item]
            right_data = right[item]
            result[item] = {
                "qty": left_data["qty"] + right_data["qty"],
                "price": left_data["price"] if left_data["price"] >= right_data["price"] else right_data["price"],
            }
        elif item in left:
            result[item] = {"qty": left[item]["qty"], "price": left[item]["price"]}
        else:
            result[item] = {"qty": right[item]["qty"], "price": right[item]["price"]}
    return result

