        if sku not in result:
            result[sku] = {"net": 0, "adds": 0, "removes": 0, "notes": []}
            order.append(sku)
        entry = result[sku]
        entry["net"] += delta
        if delta > 0:
            entry["adds"] += 1
        elif delta < 0:
