def select_evenly_spaced_items(seq, k):
    if k < 0:
        raise ValueError("k must be non-negative")
    n = len(seq)
    if k == 0:
        return []
    if k >= n:
        return list(seq)
    result = []
    denom = k - 1
    for i in range(k):
