def parse_mixed_ranges(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text.strip() == "":
        return []

    def parse_int(s):
        s = s.strip()
        if s == "":
            raise ValueError("empty integer")
        try:
            return int(s)
        except Exception:
            raise ValueError("invalid integer")

    result = set()
    parts = text.split(',')
    for part in parts:
        if part.strip() == "":
            raise ValueError("empty item")
        # Detect range with exactly one top-level hyphen separating two integers.
        # Allow whitespace around the hyphen.
        s = part.strip()
        hyphen_positions = []
        for i, ch in enumerate(s):
            if ch == '-':
                hyphen_positions.append(i)
        if len(hyphen_positions) == 0:
            result.add(parse_int(s))
            continue

        # For a valid range, there must be exactly one hyphen that acts as separator.
        # Since negative numbers are allowed, the separator is the last hyphen not
        # part of the first integer's sign, but the only supported syntax is:
        # integer, optional spaces, '-', optional spaces, integer.
        # We parse by matching the first integer prefix and last integer suffix.
        # Any internal extra hyphen means invalid.
        first = None
        last = None
        # Find a split point where left and right both parse as ints.
        for idx, ch in enumerate(s):
            if ch == '-':
                left = s[:idx].strip()
                right = s[idx+1:].strip()
                if left == "" or right == "":
                    continue
                try:
                    a = int(left)
                    b = int(right)
                except Exception:
                    continue
                first = a
                last = b
                # Ensure there is exactly one separator hyphen between the two parts.
                # Any additional hyphen in either side is allowed only as a sign.
                # If either side contains an internal hyphen after stripping sign, invalid.
                break
        if first is None:
            raise ValueError("invalid range")
        if first > last:
            raise ValueError("range start greater than end")
        for n in range(first, last + 1):
            result.add(n)

    return sorted(result)

def compress_intervals(points):
