def normalize_schedule(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    day_order = {
        "Monday": 0,
        "Tuesday": 1,
        "Wednesday": 2,
        "Thursday": 3,
        "Friday": 4,
        "Saturday": 5,
        "Sunday": 6,
    }

    normalized = []
    for record in events:
        if not isinstance(record, tuple) or len(record) != 4:
            raise ValueError("invalid record")
        day, start, end, title = record
        if not isinstance(day, str) or day == "":
            raise ValueError("invalid day")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("invalid times")
        if start < 0 or end < start:
            raise ValueError("invalid interval")
        if not isinstance(title, str):
            raise ValueError("invalid title")

        norm_day = day[:1].upper() + day[1:].lower()
        if norm_day not in day_order:
            raise ValueError("unknown day")
        normalized.append((day_order[norm_day], norm_day, start, end, title))

    if not normalized:
        return ""

    normalized.sort(key=lambda x: (x[0], x[2], x[3], x[4]))

    lines = []
    current_day = None
    current_events = []

    def fmt_minutes(m):
        return f"{m // 60:02d}:{m % 60:02d}"

    for _, day_name, start, end, title in normalized:
        item = f"{fmt_minutes(start)}-{fmt_minutes(end)} {title}"
        if current_day is None:
            current_day = day_name
            current_events = [item]
        elif day_name == current_day:
            current_events.append(item)
        else:
            lines.append(f"{current_day}: " + " | ".join(current_events))
            current_day = day_name
            current_events = [item]
    lines.append(f"{current_day}: " + " | ".join(current_events))
    return "\n".join(lines)

def normalize_menu_orders(menu):
    if not isinstance(menu, dict):
        raise TypeError('menu must be a dict')

    result = {}
    for raw_category, items in menu.items():
        if not isinstance(raw_category, str):
            raise TypeError('category name must be a string')
        category = raw_category.strip()
        if not category:
            raise ValueError('category name cannot be empty')
        if not isinstance(items, list):
            raise TypeError('category value must be a list')

        normalized_items = []
        for item in items:
            if not isinstance(item, dict):
                raise TypeError('item must be a dict')
            if set(item.keys()) != {'name', 'price', 'tags'}:
                raise ValueError('item must contain exactly name, price, and tags')

            name = item['name']
            price = item['price']
            tags = item['tags']

            if not isinstance(name, str):
                raise TypeError('name must be a string')
            name = name.strip()
            if not name:
                raise ValueError('name cannot be empty')

            if not isinstance(price, (int, float)):
                raise TypeError('price must be numeric')
            if price < 0:
                raise ValueError('price cannot be negative')

            if not isinstance(tags, list):
                raise TypeError('tags must be a list')
            normalized_tags = []
            seen = set()
            for tag in tags:
                if not isinstance(tag, str):
                    raise TypeError('each tag must be a string')
                tag = tag.strip()
                if not tag:
                    continue
                if tag not in seen:
                    seen.add(tag)
                    normalized_tags.append(tag)
            normalized_tags.sort()

            normalized_items.append({'name': name, 'price': float(price), 'tags': normalized_tags})

        if category in result:
            result[category].extend(normalized_items)
        else:
            result[category] = normalized_items

    return result

