def spiral_path_to_target(grid, target):
    if not isinstance(target, int):
        raise ValueError("target must be an integer")
    if not isinstance(grid, list) or not grid or not all(isinstance(row, list) and row for row in grid):
        raise ValueError("grid must be a non-empty list of non-empty lists")
    row_len = len(grid[0])
    if any(len(row) != row_len for row in grid):
        raise ValueError("all rows must have the same length")
    for row in grid:
        for value in row:
            if not isinstance(value, int):
                raise ValueError("all grid elements must be integers")

    top, bottom = 0, len(grid) - 1
    left, right = 0, row_len - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            if grid[top][c] == target:
                return (top, c)
        top += 1

        for r in range(top, bottom + 1):
            if grid[r][right] == target:
                return (r, right)
        right -= 1

        if top <= bottom:
            for c in range(right, left - 1, -1):
                if grid[bottom][c] == target:
                    return (bottom, c)
            bottom -= 1

        if left <= right:
            for r in range(bottom, top - 1, -1):
                if grid[r][left] == target:
                    return (r, left)
            left += 1

    return None

def balance_log_session(events):
