def normalize_sensor_events(events):
    result = []
    for raw in events:
        s = raw.strip()
        if not s:
            continue
        parts = s.split('|')
        if len(parts) == 2 and parts[1].startswith('note:'):
            sensor_id = parts[0]
            text = parts[1][5:].strip()
            result.append(f'{sensor_id}|NOTE|{text}')
            continue
        if len(parts) != 3:
            raise ValueError('invalid event')
        sensor_id, value_text, unit = parts
        value_text = value_text.strip()
        unit = unit.strip()
        try:
            value = float(value_text)
        except Exception:
            raise ValueError('invalid value')
        if unit == 'C':
            conv = value
            result.append(f'{sensor_id}|{conv:.1f}|C')
        elif unit == 'F':
            conv = (value - 32) * 5 / 9
            result.append(f'{sensor_id}|{conv:.1f}|C')
        elif unit == 'K':
            conv = value - 273.15
            result.append(f'{sensor_id}|{conv:.1f}|C')
        elif unit == 'PCT':
            result.append(f'{sensor_id}|{value:.1f}|PCT')
        else:
            raise ValueError('invalid unit')
    return result

def compress_segments(values):
    if not isinstance(values, (list, tuple)):
        raise TypeError("values must be a list or tuple of integers")
    if len(values) == 0:
        return []
    for x in values:
        if not isinstance(x, int):
            raise TypeError("all elements must be integers")
    result = []
    current = values[0]
    length = 1
    for x in values[1:]:
        if x == current:
            length += 1
        else:
            result.append((current, length, 'even' if length % 2 == 0 else 'odd'))
            current = x
            length = 1
    result.append((current, length, 'even' if length % 2 == 0 else 'odd'))
    return result

def compact_intervals(values):
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be iterable")

    result = []
    sentinel = object()
    prev = sentinel
    start = end = sentinel

    for x in iterator:
        if not isinstance(x, int):
            raise TypeError("all elements must be integers")
        if prev is sentinel:
            start = end = x
        else:
            if x < prev:
                raise ValueError("values must be non-decreasing")
            if x == prev:
                prev = x
                continue
            if x == end + 1:
                end = x
            else:
                result.append((start, end))
                start = end = x
        prev = x
    if prev is sentinel:
        return []
    result.append((start, end))
    return result

def ranked_unique_tokens(text: str, k: int) -> list[str]:
    if k < 0:
        raise ValueError("k must be non-negative")
    if k == 0:
        return []

    counts = {}
    current = []

    def flush():
        if current:
            token = ''.join(current).lower()
            counts[token] = counts.get(token, 0) + 1
            current.clear()

    for ch in text:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'):
            current.append(ch)
        else:
            flush()
    flush()

    if not counts:
        return []

    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [token for token, _ in ordered[:k]]

def normalize_schedule(events):
    if not isinstance(events, list):
        raise ValueError('events must be a list')

    grouped = {}
    for item in events:
        if not (isinstance(item, tuple) and len(item) == 4):
            raise ValueError('each event must be a 4-tuple')
        day, start, end, label = item
        if not (isinstance(day, int) and isinstance(start, int) and isinstance(end, int) and isinstance(label, str)):
            raise ValueError('invalid field types')
        if day < 0 or start < 0 or end > 1440 or start >= end:
            raise ValueError('invalid time bounds')
        grouped.setdefault(day, []).append((start, end, label))

    result = {}
    for day in sorted(grouped):
        items = sorted(grouped[day], key=lambda x: (x[0], x[1], x[2]))
        merged = []
        for start, end, label in items:
            if not merged:
                merged.append([start, end, label])
                continue
            cs, ce, cl = merged[-1]
            if label == cl and start <= ce:
                merged[-1][1] = max(ce, end)
            else:
                merged.append([start, end, label])
        result[day] = [tuple(x) for x in merged]
    return result

