def merge_run_lengths(a, b):
    def rle(seq):
        out = []
        for x in seq:
            if out and out[-1][0] == x:
                out[-1] = (x, out[-1][1] + 1)
            else:
                out.append((x, 1))
        return out

    ra = rle(a)
    rb = rle(b)
    if not ra:
        return rb
    if not rb:
        return ra
    if ra[-1][0] == rb[0][0]:
        merged = ra[:-1] + [(ra[-1][0], ra[-1][1] + rb[0][1])] + rb[1:]
        return merged
    return ra + rb

def reorder_by_blocks(s, block_size):
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if not isinstance(block_size, int):
        raise TypeError("block_size must be an integer")
    if block_size <= 0:
        raise ValueError("block_size must be greater than 0")
    if s == "":
        return ""
    blocks = [s[i:i + block_size] for i in range(0, len(s), block_size)]
    blocks.reverse()
    return "".join(blocks)

def decode_segment_runlength(s):
