        if part == "":
            raise ValueError("empty segment")
        if part.count("*") != 1:
            raise ValueError("segment must contain exactly one *")
        text, count_str = part.split("*")
        if text == "":
            raise ValueError("empty text")
        if count_str == "" or not count_str.isdigit():
            raise ValueError("invalid count")
        count = int(count_str)
