    try:
        iterator = iter(nums)
    except TypeError:
        raise TypeError("nums must be iterable")

    runs = []
    longest_run_length = 0
    longest_values = set()

    sentinel = object()
    current_value = sentinel
    current_length = 0

    for item in iterator:
        if type(item) is not int:
            raise TypeError("all items must be integers")

        if current_value is sentinel:
            current_value = item
            current_length = 1
        elif item == current_value:
            current_length += 1
        else:
            runs.append((current_value, current_length))
            if current_length > longest_run_length:
