def parse_unit_readings(lines):
    valid_units = ["C", "F", "K", "m", "cm", "mm", "s", "ms"]
    unit_order = {u: i for i, u in enumerate(valid_units)}
    latest = {}

    for line in lines:
        if not isinstance(line, str):
            continue
        s = line.strip()
        if not s:
            continue
        eq = s.find("=")
        if eq <= 0 or eq == len(s) - 1:
            continue
        name = s[:eq]
        rest = s[eq + 1:]
        if not name.isalpha():
            continue

        unit = None
        value_part = None
        for u in sorted(valid_units, key=len, reverse=True):
            if rest.endswith(u):
                unit = u
                value_part = rest[:-len(u)]
                break
        if unit is None or value_part in (None, ""):
            continue
        if value_part[0] in "+-":
            digits = value_part[1:]
            if len(value_part) == 1:
                continue
        else:
            digits = value_part
        if not digits.isdigit():
            continue
        try:
            value = int(value_part)
        except ValueError:
            continue
        latest[(name, unit)] = value

    if not latest:
        return {}

    by_unit = {}
    for (name, unit), value in latest.items():
        by_unit.setdefault(unit, {})[name] = value

    result = {}
    for unit in valid_units:
        if unit not in by_unit:
            continue
        names = tuple(sorted(by_unit[unit]))
        values = [by_unit[unit][n] for n in names]
        result[unit] = {"count": len(names), "sum": sum(values), "names": names}
    return result

def compress_intervals(intervals):
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list")

    normalized = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError("each interval must be a 2-item sequence")
        a, b = item
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("interval endpoints must be integers")
        if a <= b:
            normalized.append([a, b])
        else:
            normalized.append([b, a])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def serialize_patch(ops):
    if not isinstance(ops, (list, tuple)):
        raise TypeError('ops must be a list or tuple')

    def enc_text(s):
        return s.replace('%', '%25').replace(';', '%3B').replace('=', '%3D')

    parts = []
    for op in ops:
        if not isinstance(op, (list, tuple)) or len(op) != 2:
            raise ValueError('each operation must be a 2-item sequence')
        kind, value = op
        if kind == '=':
            if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
                raise ValueError("'=' value must be a positive integer")
            parts.append('=' + str(value))
        elif kind == '+' or kind == '-':
            if not isinstance(value, str) or len(value) < 1:
                raise ValueError("text value must be a non-empty string")
            parts.append(kind + enc_text(value))
        else:
            raise ValueError('invalid operation kind')
    return ';'.join(parts)

