def merge_event_gaps(events, gap):
    if gap < 0:
        raise ValueError("gap must be non-negative")
    validated = []
    for ev in events:
        if not isinstance(ev, tuple) or len(ev) != 2:
            raise ValueError("each event must be a 2-tuple")
        start, end = ev
        if start > end:
            raise ValueError("event start must be <= end")
        validated.append((start, end))
    if not validated:
        return []
    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [validated[0]]
    for start, end in validated[1:]:
        prev_start, prev_end = merged[-1]
        if start - prev_end <= gap:
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))
    return merged

def parse_int_ranges(spec):
    if spec is None:
        raise ValueError('spec must be a string')
    if not isinstance(spec, str):
        raise ValueError('spec must be a string')
    s = spec.strip()
    if s == '':
        return []

    def parse_nonnegative_int(token):
        token = token.strip()
        if token == '' or token[0] == '+':
            raise ValueError('invalid integer token')
        if token[0] == '-':
            raise ValueError('negative not allowed')
        if not token.isdigit():
            raise ValueError('invalid integer token')
        return int(token)

    result = []
    seen = set()
    parts = spec.split(',')
    for raw_part in parts:
        part = raw_part.strip()
        if part == '':
            raise ValueError('empty item')
        hyphen_count = part.count('-')
        if hyphen_count == 0:
            value = parse_nonnegative_int(part)
            if value not in seen:
                seen.add(value)
                result.append(value)
        else:
            if hyphen_count != 1:
                raise ValueError('malformed range')
            left, right = part.split('-', 1)
            if left.strip() == '' or right.strip() == '':
                raise ValueError('missing endpoint')
            start = parse_nonnegative_int(left)
            end = parse_nonnegative_int(right)
            step = 1 if start <= end else -1
            for value in range(start, end + step, step):
                if value not in seen:
                    seen.add(value)
                    result.append(value)
    return result

def summarize_nested_records(data):
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not data:
        return {
            "group_count": 0,
            "record_count": 0,
            "group_sums": {},
            "category_totals": {},
            "max_group": None,
            "empty_groups": [],
        }

    group_sums = {}
    category_totals = {}
    empty_groups = []
    record_count = 0

    for group_name, records in data.items():
        if not isinstance(group_name, str):
            raise TypeError("group names must be strings")
        if not isinstance(records, list):
            raise TypeError("group values must be lists")

        group_total = 0
        if len(records) == 0:
            empty_groups.append(group_name)

        for record in records:
            if not isinstance(record, list) or len(record) != 2:
                raise TypeError("each record must be a list of exactly two integers")
            category_id, score = record
            if not isinstance(category_id, int) or not isinstance(score, int):
                raise TypeError("category_id and score must be integers")
            group_total += score
            category_totals[category_id] = category_totals.get(category_id, 0) + score
            record_count += 1

        group_sums[group_name] = group_total

    max_sum = max(group_sums.values())
    max_groups = [name for name, total in group_sums.items() if total == max_sum]
    max_group = min(max_groups)

    return {
        "group_count": len(data),
        "record_count": record_count,
        "group_sums": group_sums,
        "category_totals": category_totals,
        "max_group": max_group,
        "empty_groups": sorted(empty_groups),
    }

