def compress_ranges(nums):
    if not nums:
        return ""

    values = sorted(set(nums))
    if not values:
        return ""

    groups = []
    start = prev = values[0]

    def flush(s, e):
        length = e - s + 1
        if length >= 3:
            return f"{s}-{e}"
        if length == 2:
            return f"{s},{e}"
        return str(s)

    for x in values[1:]:
        if x == prev + 1:
            prev = x
        else:
            groups.append(flush(start, prev))
            start = prev = x
    groups.append(flush(start, prev))
    return ";".join(groups)

