    try:
        iterator = iter(entries)
    except TypeError:
        raise TypeError("entries must be iterable")

    valid_severities = {'info', 'warn', 'error'}
    valid_count = 0
    categories = {}
    first_seen = {}

    for idx, entry in enumerate(iterator):
        if not isinstance(entry, str):
            continue
        parts = entry.split('|')
        if len(parts) != 3:
            continue
        category, severity, message = parts
        if not category or not message:
            continue
        if '|' in category or '|' in message:
            continue
        if severity not in valid_severities:
            continue

        valid_count += 1
