    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [validated[0]]

    for start, end in validated[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged

def normalize_route(path: str) -> str:
    if path == '':
        return '.'

    absolute = path.startswith('/')
    trailing = path.endswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if not stack:
        if absolute:
            return '/'
        return '.'

    result = '/'.join(stack)
    if absolute:
        result = '/' + result
    if trailing and result != '/':
        result += '/'
    return result

