def normalize_schedule(slots):
    def valid_slot(slot):
        if not isinstance(slot, tuple):
            return False
        if len(slot) == 2:
            s, e = slot
            label = None
        elif len(slot) == 3:
            s, e, label = slot
        else:
            return False
        if not isinstance(s, int) or not isinstance(e, int):
            return False
        if len(slot) == 3 and not isinstance(label, str):
            return False
        return s < e

    indexed = []
    for i, slot in enumerate(slots):
        if not valid_slot(slot):
            continue
        if len(slot) == 2:
            s, e = slot
            label = None
        else:
            s, e, label = slot
        indexed.append((s, e, label, i))

    if not indexed:
        return []

    indexed.sort(key=lambda x: (x[0], x[1], x[3]))
    merged = []

    cur_s, cur_e, cur_label, cur_i = indexed[0]
    for s, e, label, i in indexed[1:]:
        if s <= cur_e:
            if e > cur_e:
                cur_e = e
            continue
        merged.append((cur_s, cur_e, cur_label))
        cur_s, cur_e, cur_label, cur_i = s, e, label, i
    merged.append((cur_s, cur_e, cur_label))

    result = []
    for s, e, label in merged:
        if label is None:
            result.append((s, e))
        else:
            result.append((s, e, label))
    return result

