def normalize_markdown_bullets(text: str) -> str:
    lines = text.split('\n')
    out = []
    for line in lines:
        if line == '':
            out.append(line)
            continue
        i = 0
        n = len(line)
        while i < n and line[i] == ' ':
            i += 1
        if i < n and line[i] in '-*+' and i + 1 < n and line[i + 1] == ' ':
            out.append(line[:i] + '- ' + line[i + 2:])
