def scan_signal_runs(values, threshold):
    data = list(values)
    runs = []
    start = None
    total = 0
    length = 0

    for i, x in enumerate(data):
        if x > threshold:
            if start is None:
                start = i
                total = x
                length = 1
            else:
                total += x
                length += 1
        else:
            if start is not None:
                runs.append((start, i - 1, length, total))
                start = None
                total = 0
                length = 0

    if start is not None:
        runs.append((start, len(data) - 1, length, total))

    return runs

