def parse_action_log(log: str) -> dict:
    if not isinstance(log, str):
        raise TypeError('log must be a string')

    result = {
        'count_A': 0,
        'count_B': 0,
        'count_C': 0,
        'sum_A': 0,
        'sum_B': 0,
        'sum_C': 0,
        'first_value': None,
        'last_value': None,
    }

    if log == '':
        return result

    if any(ch.isspace() for ch in log):
        raise ValueError('whitespace is not allowed')

    records = log.split('|')
    if any(rec == '' for rec in records):
        raise ValueError('malformed record')

    for idx, rec in enumerate(records):
        if rec.count(':') != 1:
            raise ValueError('malformed record')
        typ, val_str = rec.split(':')
        if typ not in ('A', 'B', 'C'):
            raise ValueError('invalid type')
        if val_str in ('', '+'):
            raise ValueError('invalid value')
        if val_str[0] == '-':
            digits = val_str[1:]
            if digits == '':
                raise ValueError('invalid value')
        else:
            digits = val_str
        if not digits.isdigit():
            raise ValueError('invalid value')
        value = int(val_str)

        count_key = f'count_{typ}'
        sum_key = f'sum_{typ}'
        result[count_key] += 1
        result[sum_key] += value
        if idx == 0:
            result['first_value'] = value
        result['last_value'] = value

    return result

def normalize_event_log(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    grouped = {}
    min_ts = {}

    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("each record must be a 3-tuple")
        timestamp, event_type, payload = record
        if not isinstance(timestamp, int):
            raise ValueError("timestamp must be an integer")
        if not isinstance(event_type, str):
            raise ValueError("event_type must be a string")
        if event_type == 'ignore':
            continue

        if event_type not in min_ts or timestamp < min_ts[event_type]:
            min_ts[event_type] = timestamp
            grouped[event_type] = [payload]
        elif timestamp == min_ts[event_type]:
            grouped[event_type].append(payload)

    return [(etype, grouped[etype]) for etype in sorted(grouped)]

