def staircase_partitions(n):
    if not isinstance(n, int):
        raise TypeError('n must be an integer')
    if n < 0:
        raise ValueError('n must be non-negative')
    if n == 0:
        return []

    result = []

    def backtrack(remaining, start, current):
        if remaining == 0:
            result.append(tuple(current))
            return
        for x in range(start, remaining + 1):
            current.append(x)
            backtrack(remaining - x, x + 1, current)
            current.pop()

    backtrack(n, 1, [])
    result.sort(key=lambda t: (len(t), t))
    return result

def ranked_merge(records, priority_key):
    validated = []
    for rec in records:
        if not isinstance(rec, dict):
            raise ValueError('each record must be a dict')
        required = ('source', 'id', 'priority', 'payload')
        for key in required:
            if key not in rec:
                raise ValueError('missing required key')
        source = rec['source']
        rid = rec['id']
        priority = rec['priority']
        if not isinstance(source, str):
            raise ValueError('source must be a string')
        if not isinstance(rid, str) or rid == '':
            raise ValueError('id must be a non-empty string')
        if not isinstance(priority, int) or priority < 0:
            raise ValueError('priority must be a non-negative integer')
        validated.append(rec.copy())

    best = {}
    order = []
    for idx, rec in enumerate(validated):
        key = (rec['source'], rec['id'])
        if key not in best:
            best[key] = (idx, rec)
            order.append(key)
        else:
            old_idx, old = best[key]
            if rec['priority'] > old['priority']:
                best[key] = (idx, rec)
            # ties keep first; lower priority ignored

    merged = [best[k][1] for k in order if k in best]

    def sort_key(item):
        base = item['priority']
        if priority_key in item:
            return (0, base, item[priority_key])
        return (1, base, 0)

    def safe_compare(a, b):
        try:
            _ = a < b
            _ = a > b
            return True
        except Exception:
            return False

    # Stable sort by priority, then use priority_key only when both sides have comparable values.
    merged_sorted = sorted(merged, key=lambda r: r['priority'])
    if priority_key:
        i = 0
        result = []
        while i < len(merged_sorted):
            j = i + 1
            group = [merged_sorted[i]]
            while j < len(merged_sorted) and merged_sorted[j]['priority'] == merged_sorted[i]['priority']:
                group.append(merged_sorted[j])
                j += 1
            if len(group) > 1 and all(priority_key in r for r in group):
                values = [r[priority_key] for r in group]
                comparable = True
                for x in values:
                    for y in values:
                        if x is y:
                            continue
                        try:
                            _ = x < y
                        except Exception:
                            comparable = False
                            break
                    if not comparable:
                        break
                if comparable:
                    group = sorted(group, key=lambda r: r[priority_key])
            result.extend(group)
            i = j
        merged_sorted = result

    return [(r['source'], r['id'], r['priority'], r['payload']) for r in merged_sorted]

def select_balanced_subsequence(s, t, k):
    if k < 0:
        raise ValueError("k must be non-negative")
    if k == 0:
        return ""
    if k > len(s):
        return ""

    # Precompute next occurrence positions for t.
    # next_pos[i][ch] = smallest index >= i where t[index] == ch, or -1 if none.
    # Build using dynamic dictionaries per suffix for Unicode support.
    suffix_maps = [None] * (len(t) + 1)
    suffix_maps[len(t)] = {}
    for i in range(len(t) - 1, -1, -1):
        m = dict(suffix_maps[i + 1])
        m[t[i]] = i
        suffix_maps[i] = m

    # Memoized feasibility: can we choose r chars from s[i:] and t[j:]?
    from functools import lru_cache

    @lru_cache(None)
    def can(i, j, r):
        if r == 0:
            return True
        if i >= len(s) or j >= len(t):
            return False
        if len(s) - i < r:
            return False
        # Try to find the next character by scanning s and matching in t.
        # For lexicographically smallest, consider possible characters in sorted order.
        seen = set()
        for ii in range(i, len(s)):
            ch = s[ii]
            if ch in seen:
                continue
            seen.add(ch)
            # Find ch in t at or after j.
            pos = suffix_maps[j].get(ch, -1)
            if pos != -1 and can(ii + 1, pos + 1, r - 1):
                return True
        return False

    # Greedy reconstruction of lexicographically smallest valid subsequence.
    result = []
    i = 0
    j = 0
    r = k
    while r > 0:
        candidates = []
        seen = set()
        for ii in range(i, len(s)):
            ch = s[ii]
            if ch in seen:
                continue
            seen.add(ch)
            pos = suffix_maps[j].get(ch, -1)
            if pos != -1 and can(ii + 1, pos + 1, r - 1):
                candidates.append((ch, ii, pos))
        if not candidates:
            return ""
        ch, ii, pos = min(candidates, key=lambda x: (x[0], x[1]))
        result.append(ch)
        i = ii + 1
        j = pos + 1
        r -= 1
    return "".join(result)

def normalize_alarm_schedule(events):
    if events is None:
        raise TypeError('events must be iterable')
    schedule = {}
    for rec in events:
        try:
            n = len(rec)
        except Exception:
            raise ValueError('each record must have exactly 3 items')
        if n != 3:
            raise ValueError('each record must have exactly 3 items')
        label, start, end = rec
        if not isinstance(label, str) or not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('invalid record types')
        if start > end:
            continue
        mins = schedule.setdefault(label, set())
        for minute in range(start, end + 1):
            mins.add(minute)
    return [(label, tuple(sorted(schedule[label]))) for label in sorted(schedule)]

