def parse_marker_grid(text: str) -> dict:
    if text == "":
        raise ValueError("empty input")

    lines = text.split("\n")
    if any(line == "" for line in lines):
        raise ValueError("blank line")

    normalized = [line[:-1] if line.endswith("\r") else line for line in lines]
    width = len(normalized[0])
    if width == 0:
        raise ValueError("zero width")

    for line in normalized:
        if len(line) != width:
            raise ValueError("ragged grid")

    blocked = set()
    markers = {}
    for r, line in enumerate(normalized):
        for c, ch in enumerate(line):
            if ch == ".":
                continue
            if ch == "#":
                blocked.add((r, c))
                continue
            if ch.isdigit():
                if ch in markers:
                    raise ValueError("duplicate marker")
                markers[ch] = (r, c)
                continue
            raise ValueError("invalid character")

    return {
        "width": width,
        "height": len(normalized),
        "blocked": blocked,
        "markers": markers,
    }

