def compress_ranges(nums):
    values = list(nums)
    if not values:
        return ""

    parts = []
    start = prev = values[0]

    def emit(a, b):
        length = b - a + 1
        if length == 1:
            return str(a)
        if length == 2:
            return f"{a},{b}"
        return f"{a}-{b}"

    for x in values[1:]:
        if x == prev + 1:
            prev = x
        else:
            parts.append(emit(start, prev))
            start = prev = x
    parts.append(emit(start, prev))
    return ";".join(parts)

def summarize_runs(data):
    if not isinstance(data, list):
        raise ValueError("data must be a list")

    total_length = 0
    expanded_first = None
    expanded_last = None
    transitions = 0
    prev_value_set = False
    prev_value = None
    counts = {}
    first_seen_order = {}
    seen_index = 0

    for item in data:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError("each element must be a 2-item tuple")
        value, count = item
        if not isinstance(count, int) or count < 0:
            raise ValueError("count must be a non-negative integer")

        if count == 0:
            continue

        total_length += count
        if value not in counts:
            counts[value] = 0
            first_seen_order[value] = seen_index
            seen_index += 1
        counts[value] += count

        if not prev_value_set:
            expanded_first = value
            prev_value_set = True
        else:
            if prev_value != value:
                transitions += 1
        prev_value = value
        expanded_last = value

    if total_length == 0:
        return {
            "length": 0,
            "unique_values": 0,
            "first_value": None,
            "last_value": None,
            "transitions": 0,
            "most_common": None,
        }

    max_count = None
    most_common_value = None
    for value, count in counts.items():
        if max_count is None or count > max_count:
            max_count = count
            most_common_value = value
        elif count == max_count:
            if first_seen_order[value] < first_seen_order[most_common_value]:
                most_common_value = value

    return {
        "length": total_length,
        "unique_values": len(counts),
        "first_value": expanded_first,
        "last_value": expanded_last,
        "transitions": transitions,
        "most_common": most_common_value,
    }

