        raise TypeError("input must be an iterable of integers")

    values = []
    for x in iterator:
        if type(x) is not int:
            raise TypeError("all elements must be integers")
        values.append(x)

    if not values:
        return ""

    values = sorted(set(values))
    parts = []
    start = prev = values[0]

    for n in values[1:]:
