def normalize_history_events(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    result = []
    for event in events:
        if not isinstance(event, dict):
            raise TypeError("each event must be a dict")

        if 'type' not in event:
            raise ValueError("missing type")
        event_type = event['type']
        if not isinstance(event_type, str):
            raise ValueError("type must be a non-empty string")
        event_type_stripped = event_type.strip()
        if not event_type_stripped:
            raise ValueError("type must be a non-empty string")

        payload = event.get('payload', None)
        if payload is None:
            payload_norm = 'NONE'
        elif isinstance(payload, int) and not isinstance(payload, bool):
            payload_norm = str(payload)
        elif isinstance(payload, str):
            payload_norm = payload.upper()
        else:
            raise TypeError("invalid payload")

        tags = event.get('tags', [])
        if not isinstance(tags, list):
            raise TypeError("tags must be a list")
        normalized_tags = []
        seen = set()
        for tag in tags:
            if not isinstance(tag, str):
                raise TypeError("tags must contain strings")
            t = tag.strip()
            if not t:
                continue
            t = t.upper()
            if t not in seen:
                seen.add(t)
                normalized_tags.append(t)
        normalized_tags.sort()
        tag_field = ','.join(normalized_tags)

        result.append(f"{event_type_stripped.upper()}|{payload_norm}|{tag_field}")

    return tuple(result)

