def select_weighted_route(routes, preferences):
    try:
        max_duration, max_toll, scenic_required = preferences
    except Exception:
        raise ValueError("preferences must be a 3-tuple")

    if type(max_duration) is not int or type(max_toll) is not int or type(scenic_required) is not bool:
        raise ValueError("invalid preferences types")
    if max_duration < 0 or max_toll < 0:
        raise ValueError("preferences must be non-negative")

    best = None
    for record in routes:
        try:
            route_id, duration, toll, scenic = record
        except Exception:
            raise ValueError("routes must contain 4-tuples")

        if not isinstance(route_id, str):
            raise ValueError("route_id must be a string")
        if type(duration) is not int or type(toll) is not int or type(scenic) is not bool:
            raise ValueError("invalid route record types")
        if duration < 0 or toll < 0:
            raise ValueError("route values must be non-negative")

        if duration > max_duration or toll > max_toll:
            continue
        if scenic_required and not scenic:
            continue

        candidate = (duration, toll, route_id)
        if best is None or candidate < best[0]:
            best = (candidate, route_id)

    return None if best is None else best[1]

def normalize_path_segments(path):
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    if path == '':
        return '.'

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        if not stack:
            return '/'
        return '/' + '/'.join(stack)

    if not stack:
        return '.'
    return '/'.join(stack)

