            token = s[token_start:i]
            if token == "":
                raise ValueError("empty bracketed token")
            i += 1
        else:
            if s[i].isdigit():
                raise ValueError("invalid unbracketed token")
            token = s[i]
            i += 1

        result.extend([token] * count)

