def normalize_schedule(events):
    merged = {}
    for item in events:
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            continue
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int) or not isinstance(label, str):
            continue
        if start >= end:
            continue
        if label in merged:
            prev_start, prev_end = merged[label]
            merged[label] = (min(prev_start, start), max(prev_end, end))
        else:
            merged[label] = (start, end)
    result = [(start, end, label) for label, (start, end) in merged.items()]
    result.sort(key=lambda x: (x[0], x[1], x[2]))
