def normalize_inventory(items):
    totals = {}
    for pair in items:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise TypeError("each item must be a 2-tuple")
        name, quantity = pair
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        normalized_name = name.strip()
        if normalized_name == "":
            raise ValueError("name must be non-empty after stripping")
        if not isinstance(quantity, int):
            raise TypeError("quantity must be an int")
        totals[normalized_name] = totals.get(normalized_name, 0) + quantity
    result = [(name, qty) for name, qty in sorted(totals.items()) if qty != 0]
    return result

def normalize_vms_config(spec):
    if not isinstance(spec, dict):
        raise TypeError("spec must be a dictionary")

    required_keys = {"memory_mb", "cpu_cores", "disk_gb", "tags", "metadata"}
    if set(spec.keys()) != required_keys:
        raise TypeError("spec must contain exactly the required keys")

    def parse_non_negative_int(value):
        if isinstance(value, bool):
            raise TypeError("invalid integer field")
        if isinstance(value, int):
            if value < 0:
                raise TypeError("invalid integer field")
            return value
        if isinstance(value, str) and value.isdigit():
            return int(value)
        raise TypeError("invalid integer field")

    def dedupe_tags(tags):
        if not isinstance(tags, list):
            raise TypeError("tags must be a list")
        seen = set()
        out = []
        for tag in tags:
            if not isinstance(tag, str):
                raise TypeError("tags must be a list of strings")
            if tag not in seen:
                seen.add(tag)
                out.append(tag)
        return out

    def clean_metadata(value):
        if isinstance(value, dict):
            cleaned = {}
            for k, v in value.items():
                if v is None:
                    continue
                cleaned_v = clean_metadata(v)
                cleaned[k] = cleaned_v
            return cleaned
        if isinstance(value, list):
            cleaned_list = []
            for item in value:
                if item is None:
                    continue
                cleaned_list.append(clean_metadata(item))
            return cleaned_list
        return value

    memory_mb = parse_non_negative_int(spec["memory_mb"])
    cpu_cores = parse_non_negative_int(spec["cpu_cores"])
    disk_gb = parse_non_negative_int(spec["disk_gb"])
    tags = dedupe_tags(spec["tags"])
    metadata = spec["metadata"]
    if not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")
    metadata = clean_metadata(metadata)

    return {
        "memory_mb": memory_mb,
        "cpu_cores": cpu_cores,
        "disk_gb": disk_gb,
        "tags": tags,
        "metadata": metadata,
    }

