def summarize_rle_segments(text: str) -> list[tuple[str, int, int]]:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return []

    segments = []
    start = 0
    current = text[0]
    length = 1

    for i in range(1, len(text)):
        ch = text[i]
        if ch == current:
            length += 1
        else:
            segments.append((current, start, length))
