def parse_scene_commands(text: str) -> dict:
    points = []
    circles = []
    labels = []
    scale = 1.0

    for raw_line in text.split('\n'):
        line = raw_line.strip()
        if not line:
            continue
        if line.lstrip().startswith('#'):
            continue

        parts = line.split()
        if not parts:
            continue

        cmd = parts[0]
        args = parts[1:]

        if cmd == 'ADD':
            if len(args) != 2:
                raise ValueError('ADD requires exactly 2 arguments')
            try:
                x = int(args[0])
                y = int(args[1])
            except Exception:
                raise ValueError('ADD arguments must be integers')
            points.append((x, y))
        elif cmd == 'CIRCLE':
            if len(args) != 1:
                raise ValueError('CIRCLE requires exactly 1 argument')
            try:
                r = int(args[0])
            except Exception:
                raise ValueError('CIRCLE argument must be an integer')
            circles.append(r)
        elif cmd == 'LABEL':
            if len(args) != 1:
                raise ValueError('LABEL requires exactly 1 argument')
            labels.append(args[0])
        elif cmd == 'SCALE':
            if len(args) != 1:
                raise ValueError('SCALE requires exactly 1 argument')
            try:
                f = float(args[0])
            except Exception:
                raise ValueError('SCALE argument must be a float')
            scale *= f
        else:
            raise ValueError('unknown command')

    if points:
        xs = [p[0] for p in points]
        ys = [p[1] for p in points]
        bbox = (min(xs), min(ys), max(xs), max(ys))
    else:
        bbox = None

    return {
        'points': points,
        'circles': circles,
        'labels': labels,
        'scale': scale,
        'bbox': bbox,
    }

def collapse_intervals(points, gap):
    if not isinstance(gap, int):
        raise TypeError("gap must be an integer")
    if gap < 0:
        raise ValueError("gap must be non-negative")

    pts = []
    for p in points:
        if not isinstance(p, int):
            raise TypeError("all points must be integers")
        pts.append(p)

    if not pts:
        return []

    pts = sorted(set(pts))
    intervals = []
    start = prev = pts[0]

    for p in pts[1:]:
        if p - prev > gap + 1:
            intervals.append((start, prev))
            start = p
        prev = p

    intervals.append((start, prev))
    return intervals

def normalize_calendar_dates(records):
    def is_leap(year):
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    month_days = {
        1: 31,
        2: 28,
        3: 31,
        4: 30,
        5: 31,
        6: 30,
        7: 31,
        8: 31,
        9: 30,
        10: 31,
        11: 30,
        12: 31,
    }

    result = []
    for record in records:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("invalid record")
        year, month, day = record
        if not isinstance(year, int) or not isinstance(month, int) or not isinstance(day, int):
            raise ValueError("invalid record")
        if year < 1 or year > 9999 or month < 1 or month > 12:
            raise ValueError("invalid record")
        max_day = month_days[month]
        if month == 2 and is_leap(year):
            max_day = 29
        if day < 1 or day > max_day:
            raise ValueError("invalid record")
        result.append(f"{year:04d}-{month:02d}-{day:02d}")
    return result

