def parse_interval_spec(spec):
    if not isinstance(spec, str):
        raise ValueError("spec must be a string")

    text = spec.strip()
    if text == "":
        return []

    items = [part.strip() for part in text.split(",")]
    if any(part == "" for part in items):
        raise ValueError("malformed item")

    intervals = []

    for item in items:
        # Single integer item
        try:
            n = int(item)
            intervals.append([n, n + 1])
            continue
        except ValueError:
            pass

        # Range item a-b, allowing negative integers and surrounding whitespace.
        # We locate the separator hyphen by finding the last hyphen that is not the first character.
        sep = None
        for i in range(1, len(item)):
            if item[i] == '-':
                sep = i
                break
        if sep is None:
            raise ValueError("malformed item")

        left = item[:sep].strip()
        right = item[sep + 1 :].strip()
        if left == "" or right == "":
            raise ValueError("malformed item")

        try:
            a = int(left)
            b = int(right)
        except ValueError:
            raise ValueError("malformed item")

        if a > b:
            raise ValueError("range start greater than end")

        intervals.append([a, b + 1])

    intervals.sort(key=lambda p: (p[0], p[1]))
    merged = []
    for start, end in intervals:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            if end > merged[-1][1]:
                merged[-1][1] = end
    return merged

def normalize_inventory_log(entries):
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')

    best = {}

    for entry in entries:
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError('each entry must be a tuple/list of length 3')

        sku, name, quantity = entry

        if not isinstance(sku, str) or not isinstance(name, str) or not isinstance(quantity, int):
            raise TypeError('sku and name must be strings; quantity must be int')

        sku_stripped = sku.strip()
        name_stripped = name.strip()

        if sku_stripped == '' or name_stripped == '':
            raise ValueError('sku and name must be non-empty after stripping')
        if quantity < 0:
            raise ValueError('quantity must be non-negative')

        sku_norm = sku_stripped.upper()
        name_norm = ' '.join(name_stripped.split())
        record = (sku_norm, name_norm, quantity)

        if sku_norm not in best:
            best[sku_norm] = record
        else:
            prev = best[sku_norm]
            if quantity > prev[2] or (quantity == prev[2] and name_norm < prev[1]):
                best[sku_norm] = record

    return [best[sku] for sku in sorted(best)]

def summarize_runs(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    result = {}
    segments = text.split(';')
    seen_any = False

    for raw_seg in segments:
        seg = raw_seg.strip()
        if not seg:
            continue
        seen_any = True
        if ':' not in seg:
            raise ValueError("malformed segment")
        name_part, value_part = seg.split(':', 1)
        name = name_part.strip()
        value_str = value_part.strip()
        if not name or not name.isalpha():
            raise ValueError("malformed name")
        if value_str in ('', '+', '-'):
            raise ValueError("malformed value")
        sign = 1
        if value_str[0] in '+-':
            sign = -1 if value_str[0] == '-' else 1
            value_digits = value_str[1:]
        else:
            value_digits = value_str
        if not value_digits.isdigit():
            raise ValueError("malformed value")
        value = sign * int(value_digits)

        if name not in result:
            result[name] = {'count': 0, 'total': 0, 'min': value, 'max': value}
        entry = result[name]
        entry['count'] += 1
        entry['total'] += value
        if value < entry['min']:
            entry['min'] = value
        if value > entry['max']:
            entry['max'] = value

    if not seen_any:
        return {}
    return result

