def normalize_schedule_intervals(intervals):
    if intervals is None:
        raise ValueError('intervals must be an iterable of 2-item integer sequences')

    normalized = []
    for item in intervals:
        try:
            if len(item) != 2:
                raise ValueError
            a, b = item
        except Exception:
            raise ValueError('each interval must contain exactly two values')
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError('each interval endpoint must be an integer')
        start, end = (a, b) if a <= b else (b, a)
        normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def parse_patch_counts(patch: str) -> tuple[int, int]:
    if not isinstance(patch, str):
        raise TypeError("patch must be a string")

    added = 0
    removed = 0
    for line in patch.split('\n'):
        stripped = line.lstrip(' \t')
        if not stripped:
            continue
        if stripped.startswith('+++') or stripped.startswith('---'):
            continue
        if stripped.startswith('+'):
            added += 1
        elif stripped.startswith('-'):
            removed += 1
    return added, removed

def normalize_inventory_log(entries):
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')

    totals = {}
    order = []

    for entry in entries:
        if not isinstance(entry, str):
            continue
        if entry.count(':') != 1:
            continue
        item_part, qty_part = entry.split(':')
        item = item_part.strip()
        qty_text = qty_part.strip()
        if not item or ':' in item:
            continue
        if qty_text in ('', '+', '-'):
            continue
        sign = 1
        if qty_text[0] in '+-':
            sign = -1 if qty_text[0] == '-' else 1
            digits = qty_text[1:]
        else:
            digits = qty_text
        if not digits.isdigit():
            continue
        qty = sign * int(digits)
        if item not in totals:
            totals[item] = 0
            order.append(item)
        totals[item] += qty

    return [f'{item}:{totals[item]}' for item in order]

