def compress_runs(text: str, min_run: int) -> str:
    if min_run < 2:
        raise ValueError("min_run must be at least 2")
    if text == "":
        return ""

    result = []
    current = text[0]
    count = 1

    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            if count >= min_run:
                result.append(current + str(count))
            else:
                result.append(current * count)
            current = ch
            count = 1

    if count >= min_run:
        result.append(current + str(count))
    else:
        result.append(current * count)

    return "".join(result)

