    for idx, rec in enumerate(events):
        if not isinstance(rec, tuple) or len(rec) != 4:
            raise ValueError("each record must be a 4-tuple")
        category, priority, timestamp, payload = rec
        if not isinstance(category, str) or category == "":
            raise ValueError("category must be a non-empty string")
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise ValueError("priority must be an integer")
        if not isinstance(timestamp, int) or isinstance(timestamp, bool):
            raise ValueError("timestamp must be an integer")
        if not isinstance(payload, str):
            raise ValueError("payload must be a string")
        key = (category, priority)
        if key not in selected:
            selected[key] = rec
            order_index[key] = idx
        else:
            cur = selected[key]
            cur_ts = cur[2]
            if timestamp > cur_ts:
                selected[key] = rec
                order_index[key] = idx
            elif timestamp == cur_ts:
                cur_payload = cur[3]
                if payload < cur_payload:
                    selected[key] = rec
                    order_index[key] = idx
                elif payload == cur_payload:
                    pass
    result = list(selected.values())
    result.sort(key=lambda r: (-r[1], r[0]))
    return result

def best_price_plan(prices, window):
    if not isinstance(window, int):
        raise TypeError("window must be an integer")
    if window < 0:
        raise ValueError("window must be non-negative")
    n = len(prices)
    if window == 0:
        return 1
    if window > n:
        raise ValueError("window larger than prices length")
    if n == 0:
        raise ValueError("prices cannot be empty when window > 0")

    current_sum = sum(prices[:window])
    min_sum = current_sum
    best_start = 1

    for start in range(1, n - window + 1):
        current_sum += prices[start + window - 1] - prices[start - 1]
        if current_sum < min_sum:
            min_sum = current_sum
            best_start = start + 1
    return best_start

def normalize_inventory(records, rename_map):
    if not isinstance(records, list):
        raise TypeError("records must be a list")
    if not isinstance(rename_map, dict):
        raise TypeError("rename_map must be a dict")

    result = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError("each record must be a dict")
        if 'id' not in record:
            raise ValueError("missing id")

        item_id = record['id']
        name = record.get('name')
        if name in rename_map:
            name = rename_map[name]
        quantity = int(record.get('quantity', 0))
        tags = record.get('tags', [])
        unique_sorted_tags = sorted({str(tag) for tag in tags})

        result.append({
            'id': item_id,
            'name': name,
            'quantity': quantity,
            'tags': unique_sorted_tags,
        })
    return result

