def normalize_cli_command(command: str) -> str:
    if not isinstance(command, str):
        raise TypeError("command must be a string")

    tokens = command.split()
    if not tokens:
        return ""

    def normalize_int_token(token: str) -> str:
        sign = ""
        body = token
        if token[0] in "+-":
            sign = token[0]
            body = token[1:]
        if not body.isdigit():
            return None
        body = body.lstrip("0")
        if body == "":
