        raise TypeError("rule must be a tuple of length 3")
    if any(isinstance(x, bool) or not isinstance(x, int) for x in rule):
        raise TypeError("rule elements must be integers")

    threshold, low_delta, high_delta = rule

    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be iterable")

    result = []
    for x in iterator:
        if isinstance(x, bool) or not isinstance(x, int):
