def summarize_page_ranges(pages):
    try:
        iterator = iter(pages)
    except TypeError:
        raise TypeError("pages must be iterable")

    unique_pages = set()
    for p in iterator:
        if type(p) is not int:
            raise TypeError("all page identifiers must be integers")
        unique_pages.add(p)

    if not unique_pages:
        return ""

    nums = sorted(unique_pages)
    ranges = []
    start = prev = nums[0]

    for n in nums[1:]:
        if n == prev + 1:
            prev = n
            continue
        if start == prev:
            ranges.append(str(start))
        else:
            ranges.append(f"{start}-{prev}")
        start = prev = n

    if start == prev:
        ranges.append(str(start))
    else:
        ranges.append(f"{start}-{prev}")

    return ", ".join(ranges)

