def encode_ranges(values):
    sentinel = object()
    parts = []
    start = end = sentinel

    def emit(a, b):
        if a == b:
            parts.append(str(a))
        else:
            parts.append(f"{a}-{b}")

    for x in values:
        if not isinstance(x, int) or isinstance(x, bool):
            raise TypeError("all elements must be integers")
        if start is sentinel:
            start = end = x
            continue
        if x <= end + 1:
            if x > end:
                end = x
        else:
            emit(start, end)
            start = end = x
    if start is not sentinel:
        emit(start, end)
    return ",".join(parts)

def run_length_merge(s):
    if not isinstance(s, str):
        raise TypeError('s must be a string')
