        if key == 'country':
            out[key] = clean(value, upper=True)
        elif key == 'postal_code':
            out[key] = clean(value, remove_spaces=True)
        else:
            out[key] = clean(value)

    parts = [out[k] for k in ['street', 'city', 'region', 'postal_code', 'country'] if out[k] != '']
    out['label'] = ', '.join(parts)
    return out

def normalize_ledger_entries(entries):
    import re

    if not isinstance(entries, list):
        raise TypeError("entries must be a list")

    date_re = re.compile(r"^\d{4}-\d{2}-\d{2}$")
    int_re = re.compile(r"^[+-]?\d+$")

    def norm_amount(s):
        s = s.strip()
        if not int_re.match(s):
            return None
        sign = ''
        if s[0] in '+-':
            sign = '-' if s[0] == '-' else ''
            s = s[1:]
        s = s.lstrip('0')
        if s == '':
            s = '0'
        if s == '0':
            sign = ''
        return sign + s

    out = []
    seen = set()
    for item in entries:
        if not isinstance(item, str):
            continue
        parts = item.split(';')
        if len(parts) not in (3, 4):
            continue
        date, amount, description = parts[0].strip(), parts[1], parts[2].strip()
        tag = parts[3].strip() if len(parts) == 4 else None
        if not date_re.match(date):
            continue
        if not description:
            continue
        amount_n = norm_amount(amount)
        if amount_n is None:
            continue
        if len(parts) == 4 and not tag:
            continue
        normalized = f"{date}|{amount_n}|{description}" + (f"|{tag}" if tag is not None else "")
        if normalized in seen:
            continue
        seen.add(normalized)
        out.append(normalized)
    return out

def assign_run_lengths(bits: str) -> list[int]:
    if not isinstance(bits, str):
        raise ValueError("bits must be a string")
    if any(ch not in '01' for ch in bits):
        raise ValueError("bits must contain only '0' and '1'")

    n = len(bits)
    result = [0] * n
    i = 0
    while i < n:
        j = i + 1
        while j < n and bits[j] == bits[i]:
            j += 1
        run_len = j - i
        for k in range(i, j):
            result[k] = run_len
        i = j
    return result

def normalize_command_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                stack.append('..')
        else:
            stack.append(part)

    if not stack:
        return '.'
    return '/'.join(stack)

def encode_run_lengths(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
