def ranked_merge(seqs):
    seqs = list(seqs)
    out = []
    positions = []
    for s_idx, seq in enumerate(seqs):
        seq = list(seq)
        for i, x in enumerate(seq):
            if not isinstance(x, int) or isinstance(x, bool):
                raise TypeError("all elements must be integers")
            if i > 0 and seq[i - 1] > x:
                raise ValueError("each inner sequence must be sorted in nondecreasing order")
            out.append((x, s_idx, i))
    out.sort(key=lambda t: (t[0], t[1], t[2]))
    return [x for x, _, _ in out]

def normalize_inventory_moves(moves):
    if not isinstance(moves, list):
        raise TypeError('moves must be a list')
    totals = {}
    order = []
    for item in moves:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('each move must be a tuple of length 2')
        sku, delta = item
        if isinstance(sku, str) and sku != '' and isinstance(delta, int):
            if sku not in totals:
                totals[sku] = delta
                order.append(sku)
            else:
                totals[sku] += delta
    return [(sku, totals[sku]) for sku in order]

def normalize_event_schedule(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    canonical = []
    seen = set()

    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("each event must be a 3-tuple")
        start, end, label = record
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("start and end must be integers")
        if not isinstance(label, str):
            raise ValueError("label must be a string")
        if start > end:
            raise ValueError("start cannot exceed end")

        norm = (start, end, label.strip())
        if norm not in seen:
            seen.add(norm)
            canonical.append(norm)

    canonical.sort(key=lambda x: (x[0], x[1], x[2]))
    return canonical

def normalize_durations(values):
    result = []
    n = len(values)
    i = 0
    while i < n:
        block = values[i:i+4]
        if len(block) == 4:
            has_pos = any(x > 0 for x in block)
            has_neg = any(x < 0 for x in block)
            if has_pos and has_neg:
                normalized = []
                for x in block:
                    if x > 0:
                        normalized.append(1)
                    elif x < 0:
                        normalized.append(-1)
                    else:
                        normalized.append(0)
                result.extend(normalized)
            else:
                result.extend(block)
        else:
            result.extend(block)
        i += 4
    return result

from urllib.parse import unquote_plus, quote

def canonicalize_query(query: str) -> str:
    if not isinstance(query, str):
        raise TypeError('query must be a string')
    pairs = {}
    if query == '':
        return ''
    for field in query.split('&'):
        if field == '':
            continue
        if '=' in field:
            raw_key, raw_value = field.split('=', 1)
        else:
            raw_key, raw_value = field, ''
        key = unquote_plus(raw_key).strip()
        value = unquote_plus(raw_value).strip()
        if key == '':
            continue
        pairs[key] = value
    if not pairs:
        return ''
    encoded = []
    for key in sorted(pairs):
        encoded.append(f"{quote(key, safe='-_.~')}={quote(pairs[key], safe='-_.~')}")
    return '&'.join(encoded)

def normalize_window_counts(seq, window_size):
    if not isinstance(window_size, int) or window_size < 1:
        raise ValueError("window_size must be a positive integer")

    data = list(seq)
    n = len(data)
    if n == 0 or window_size > n:
        return []

    result = []
    for start in range(n - window_size + 1):
        window = data[start:start + window_size]
        counts = {}
        for value in window:
            counts[value] = counts.get(value, 0) + 1
        snapshot = tuple((value, counts[value] / window_size) for value in sorted(counts))
        result.append(snapshot)
    return result

def parse_compact_intervals(spec: str) -> list[tuple[int, int]]:
    s = spec.strip()
    if not s:
        return []

    def parse_int(text: str) -> int:
        if text == '':
            raise ValueError('empty integer')
        if text[0] == '+':
            text = text[1:]
        if text == '' or not all(ch.isdigit() or (i == 0 and ch == '-') for i, ch in enumerate(text)):
            raise ValueError('invalid integer')
        return int(text)

    intervals = []
    for raw_token in s.split(','):
        token = raw_token.strip()
        if token == '':
            raise ValueError('empty token')
        if ' ' in token or '\t' in token or '\n' in token or '\r' in token:
            raise ValueError('internal whitespace')

        hyphens = [i for i, ch in enumerate(token) if ch == '-']
        if len(hyphens) == 0:
            n = parse_int(token)
            intervals.append((n, n))
        elif len(hyphens) == 1:
            idx = hyphens[0]
            left = token[:idx]
            right = token[idx + 1:]
            a = parse_int(left)
            b = parse_int(right)
            lo, hi = (a, b) if a <= b else (b, a)
            intervals.append((lo, hi))
        else:
            # Allow a leading minus on each side only for forms like -2--1
            # by splitting at the last hyphen that separates two integers.
            sep = None
            for i in range(1, len(token) - 1):
                if token[i] == '-':
                    sep = i
                    break
            if sep is None:
                raise ValueError('invalid range')
            left = token[:sep]
            right = token[sep + 1:]
            a = parse_int(left)
            b = parse_int(right)
            lo, hi = (a, b) if a <= b else (b, a)
            # Reject cases with extra hyphens beyond the separator unless they are sign markers.
            if left.count('-') > (1 if left.startswith('-') else 0) or right.count('-') > (1 if right.startswith('-') else 0):
                raise ValueError('invalid range')
            intervals.append((lo, hi))

    intervals.sort()
    merged = []
    for start, end in intervals:
        if not merged or start > merged[-1][1] + 1:
            merged.append((start, end))
        else:
            prev_start, prev_end = merged[-1]
            if end > prev_end:
                merged[-1] = (prev_start, end)
    return merged

def summarize_run_length(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return []

    result = []
