def canonicalize_command_path(path: str) -> str:
    s = path.strip()
    if not s:
        return "/"

    parts = []
    for segment in s.split('/'):
        seg = segment.strip()
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if parts:
                parts.pop()
            continue
        parts.append(seg)

    return '/' + '/'.join(parts) if parts else '/'

def align_text_grid(lines, width, pad_char):
    if width < 0:
        raise ValueError("width must be non-negative")
    if not isinstance(pad_char, str) or len(pad_char) != 1:
        raise ValueError("pad_char must be a single character string")

    result = []
    for line in lines:
        if len(line) < width:
            result.append(line + pad_char * (width - len(line)))
        else:
            result.append(line[:width])
    return result

def merge_intervals(intervals):
    try:
        items = list(intervals)
    except TypeError:
        raise TypeError("intervals must be iterable")

    normalized = []
    for interval in items:
        try:
            start, end = interval
        except Exception:
            raise ValueError("each interval must contain exactly two elements")
        if len(interval) != 2:
            raise ValueError("each interval must contain exactly two elements")
        if start > end:
            raise ValueError("interval start must not be greater than end")
        normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def stable_group_sort(items, priorities):
    priority_order = {}
    ordered_labels = []
    for label in priorities:
        if label not in priority_order:
            priority_order[label] = len(ordered_labels)
            ordered_labels.append(label)

    groups = {label: [] for label in ordered_labels}
    remainder = []

    for item in items:
        if item in priority_order:
            groups[item].append(item)
        else:
            remainder.append(item)

    result = []
    for label in ordered_labels:
        result.extend(groups[label])
    result.extend(remainder)
    return result

def interval_multiset_signature(intervals):
    try:
        items = list(intervals)
    except TypeError:
        raise TypeError("intervals must be iterable")

    counts = {}
    for pair in items:
        try:
            a, b = pair
        except Exception:
            raise TypeError("each interval must be a length-2 iterable")
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("interval endpoints must be integers")
        start, end = (a, b) if a <= b else (b, a)
        for v in range(start, end + 1):
            counts[v] = counts.get(v, 0) + 1
    return sorted(counts.items())

