from datetime import datetime


def normalize_alarm_events(events):
    normalized = []
    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            continue
        timestamp, severity, code = record
        if not isinstance(timestamp, str):
            continue
        try:
            dt = datetime.strptime(timestamp, "%Y-%m-%d %H:%M")
        except Exception:
            continue
        if not isinstance(severity, int) or isinstance(severity, bool) or severity < 1 or severity > 5:
            continue
        if not isinstance(code, str):
            continue
        cleaned_code = code.strip()
        if not cleaned_code:
            continue
        normalized_ts = dt.strftime("%Y%m%dT%H%M")
        normalized.append((dt, severity, cleaned_code.upper(), f"{normalized_ts}|S{severity}|{cleaned_code.upper()}"))
    normalized.sort(key=lambda x: (x[0], -x[1], x[2]))
    return [item[3] for item in normalized]

def normalize_section_order(sections):
    if not isinstance(sections, list):
        raise TypeError('sections must be a list')
    result = []
    seen = set()
    for item in sections:
        if not isinstance(item, str):
            raise TypeError('all items must be strings')
        normalized = ' '.join(item.strip().lower().split())
        if normalized not in seen:
            seen.add(normalized)
            result.append(normalized)
    return result

def normalize_schedule(intervals, *, inclusive=False):
    if not isinstance(intervals, list):
        raise TypeError('intervals must be a list')
    normalized = []
    for item in intervals:
        try:
            start, end = item
        except Exception:
            raise TypeError('each interval must be a 2-item iterable of integers')
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('each interval must be a 2-item iterable of integers')
        if start > end:
            raise ValueError('interval start must be <= end')
        normalized.append((start, end))
    if not normalized:
        return []
    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        should_merge = start <= last_end or (inclusive and start == last_end + 1)
        if should_merge:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def normalize_acl_rules(rules):
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")

    normalized = []
    seen = set()

    for rule in rules:
        if not isinstance(rule, (tuple, list)) or len(rule) != 3:
            raise ValueError("each rule must be a 3-item tuple or list")

        principal, action, resource = rule
        if not isinstance(principal, str) or not isinstance(action, str) or not isinstance(resource, str):
            raise TypeError("all rule fields must be strings")

        norm_rule = (
            principal.strip().lower(),
            action.strip().lower(),
            resource.strip().upper(),
        )

        if norm_rule not in seen:
            seen.add(norm_rule)
            normalized.append(norm_rule)

    normalized.sort(key=lambda x: (x[0], x[1], x[2]))
    return normalized

def normalize_chat_stream(events):
    result = []
    prev_user = None
    prev_text = None
    for event in events:
        if not isinstance(event, tuple) or len(event) != 3:
            continue
        kind, user, text = event
        if kind == 'sys':
            continue
        if kind != 'msg':
            continue
        if not isinstance(user, str) or user == '':
            continue
        if not isinstance(text, str):
            continue
        cleaned = text.strip()
        if cleaned == '':
            continue
        if prev_user == user and prev_text == cleaned:
            continue
        out = f'{user}: {cleaned}'
        result.append(out)
        prev_user = user
        prev_text = cleaned
    return result

def merge_interval_schedules(schedule_a, schedule_b):
    def validate(schedule):
        validated = []
        for interval in schedule:
            if not hasattr(interval, '__len__') or len(interval) != 2:
                raise ValueError('Each interval must have exactly two items')
            start, end = interval
            if not isinstance(start, int) or not isinstance(end, int):
                raise ValueError('Interval endpoints must be integers')
            if start > end:
                raise ValueError('Interval start must be <= end')
            validated.append((start, end))
        return validated

    intervals = validate(schedule_a) + validate(schedule_b)
    if not intervals:
        return []

    intervals.sort(key=lambda x: (x[0], x[1]))
    merged = [intervals[0]]
    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged

def normalize_inventory_log(events):
    totals = {}
    for record in events:
        if not isinstance(record, tuple) or len(record) != 2:
            raise ValueError("invalid record")
        code, qty = record
        if not isinstance(code, str) or code == "":
            raise ValueError("invalid code")
        if not isinstance(qty, int):
            raise ValueError("invalid qty")
        if qty == 0:
            continue
        totals[code] = totals.get(code, 0) + qty
        if totals[code] == 0:
            del totals[code]
    return ";".join(f"{code}:{totals[code]}" for code in sorted(totals))

