def normalize_inventory_updates(inventory, updates):
    if not isinstance(inventory, dict) or not isinstance(updates, dict):
        raise TypeError("inventory and updates must be dictionaries")

    result = {}

    for source in (inventory, updates):
        for k, v in source.items():
            if not isinstance(k, str):
                raise TypeError("all keys must be strings")
            if not isinstance(v, int):
                raise TypeError("all values must be integers")

    combined = dict(inventory)
    for key, delta in updates.items():
        combined[key] = combined.get(key, 0) + delta

    for key in sorted(combined):
        if combined[key] > 0:
            result[key] = combined[key]

    return result

