def parse_timeline_notes(text):
    from datetime import date

    result = []
    if text is None:
        return result
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        parts = line.split('|')
        if len(parts) not in (2, 3):
            continue
        date_str = parts[0].strip()
        title = parts[1].strip()
        tags = []
        if len(parts) == 3:
            tag_part = parts[2]
            for tag in tag_part.split(','):
                tag = tag.strip()
                if tag:
                    tags.append(tag)
        if len(date_str) != 10:
            continue
        try:
            y, m, d = map(int, date_str.split('-'))
            if date_str[4] != '-' or date_str[7] != '-':
                continue
            date(y, m, d)
        except Exception:
            continue
        if '|' in title:
            continue
        result.append({'date': date_str, 'title': title, 'tags': tags})
    return result

