        left = 0
        mismatches = 0
        for right, ch in enumerate(s):
            if ch != digit:
                mismatches += 1
            while mismatches > k:
                if s[left] != digit:
                    mismatches -= 1
                left += 1
            current_len = right - left + 1
            if current_len > best:
                best = current_len
    return best

def normalize_event_log(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    result = []
    seen = set()
    for event in events:
        if not isinstance(event, str):
            raise TypeError('all events must be strings')
        if event.strip() == '':
            raise ValueError('empty event')
        parts = event.split(':')
        if len(parts) not in (2, 3):
            raise ValueError('malformed event')
        user = parts[0].strip()
        action = parts[1].strip()
        if user == '' or action == '':
            raise ValueError('empty user or action')
        normalized = f"{user.lower()}:{action.upper()}"
        if len(parts) == 3:
            payload = parts[2].strip()
            normalized = f"{normalized}:{payload}"
        if normalized not in seen:
            seen.add(normalized)
            result.append(normalized)
    return result

def normalize_query_params(params):
    if type(params) is not dict:
        raise TypeError("params must be a dict")

    def normalize_value(value):
        if value is None:
            return ''
        if type(value) is str:
            return value
        if type(value) is int or type(value) is bool:
            return str(value)
        if type(value) is list or type(value) is tuple:
            parts = []
            for item in value:
                parts.append(normalize_value(item))
            return ','.join(parts)
        raise TypeError("unsupported value type")

    normalized_items = []
    for key in sorted(params.keys()):
        if type(key) is not str:
            raise TypeError("keys must be strings")
        normalized_items.append((key, normalize_value(params[key])))
    return tuple(normalized_items)

def summarize_runs(values, gap):
    if not isinstance(gap, int) or gap < 0:
        raise ValueError("gap must be a non-negative integer")

    result = []
    it = iter(values)

    try:
        first = next(it)
    except StopIteration:
        return result

    if not isinstance(first, int):
        raise TypeError("all values must be integers")

    start = first
    prev = first
    count = 1

    for x in it:
        if not isinstance(x, int):
            raise TypeError("all values must be integers")
        if x == prev + 1 and abs(x - prev) <= gap:
            prev = x
            count += 1
        else:
            result.append((start, prev, count))
            start = x
            prev = x
            count = 1

    result.append((start, prev, count))
    return result

def normalize_portable_path(path):
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    is_absolute = path.startswith('/')
    has_trailing_slash = path.endswith('/')

    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
            continue
        parts.append(segment)

    if not parts:
        return '/' if is_absolute else '.'

    result = '/'.join(parts)
    if is_absolute:
        result = '/' + result
    if has_trailing_slash and result != '/':
        result += '/'
    return result

def normalize_event_log(events):
    if not isinstance(events, list):
        raise ValueError('events must be a list')

    normalized = []
    for record in events:
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            raise ValueError('each record must be a 3-item list or tuple')
        timestamp, event_type, payload = record
        if not isinstance(timestamp, int):
            raise ValueError('timestamp must be an integer')
        if not isinstance(event_type, str) or event_type == '':
            raise ValueError('event_type must be a non-empty string')
        normalized.append([timestamp, event_type, payload])

    normalized.sort(key=lambda r: r[0])

    result = []
    for record in normalized:
        if result and result[-1][0] == record[0] and result[-1][1] == record[1]:
            result[-1] = [record[0], record[1], record[2]]
        else:
            result.append([record[0], record[1], record[2]])
    return result

def decode_signal_stream(stream):
    if not isinstance(stream, str):
        raise ValueError('stream must be a string')
    if stream == '':
        return []
    if any(ch.isspace() for ch in stream):
        raise ValueError('whitespace is not allowed')

    chunks = stream.split(';')
    if '' in chunks:
        raise ValueError('empty chunk is not allowed')

    result = []
    for chunk in chunks:
        if ':' not in chunk:
            raise ValueError('missing colon')
        label, payload = chunk.split(':', 1)
        if not label:
            raise ValueError('empty label')
        if any(ch in ':;' or ch.isspace() for ch in label):
            raise ValueError('invalid label')

        if payload.startswith('~'):
            decoded = payload[1:]
            result.append((label, decoded))
            continue

        decoded_chars = []
        i = 0
        n = len(payload)
        while i < n:
            ch = payload[i]
            if ch.isdigit():
                raise ValueError('payload cannot start with digits or have consecutive digit sequences')
            if i + 1 < n and payload[i + 1].isdigit():
                j = i + 1
                while j < n and payload[j].isdigit():
                    j += 1
                count = int(payload[i + 1:j])
                if count > 0:
                    decoded_chars.append(ch * count)
                i = j
            else:
                decoded_chars.append(ch)
                i += 1
        result.append((label, ''.join(decoded_chars)))
    return result

def merge_labeled_ranges(items):
    if not isinstance(items, list):
        raise TypeError('items must be a list')
    by_label = {}
    for entry in items:
        if not (isinstance(entry, tuple) and len(entry) == 3):
            raise TypeError('each item must be a tuple (label, start, end)')
        label, start, end = entry
        if not isinstance(label, str) or not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('label must be str and start/end must be int')
        if start >= end:
            raise ValueError('invalid interval')
        by_label.setdefault(label, []).append((start, end))
    result = []
    for label in sorted(by_label):
        intervals = sorted(by_label[label])
        cur_start, cur_end = intervals[0]
        for start, end in intervals[1:]:
            if start <= cur_end:
                if end > cur_end:
                    cur_end = end
            else:
                result.append((label, cur_start, cur_end))
                cur_start, cur_end = start, end
        result.append((label, cur_start, cur_end))
    return result

def rank_tokens(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    tokens = []
    current = []
    for ch in text:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'):
            current.append(ch.lower())
        else:
            if current:
                tokens.append(''.join(current))
                current = []
    if current:
        tokens.append(''.join(current))

    unique = set(tokens)
    return sorted(unique, key=lambda s: (-len(s), s))

def normalize_schedule_labels(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    normalized = []
    for item in events:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError("each event must be a tuple of length 3")
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("start and end must be integers")
        if start > end:
            raise ValueError("start must be less than or equal to end")
        if not isinstance(label, str):
            raise TypeError("label must be a string")

        stripped = label.strip()
        parts = stripped.split()
        normalized_label = "_".join(parts).upper()
        if normalized_label == "":
            normalized_label = "UNKNOWN"
        normalized.append((start, end, normalized_label))

    normalized.sort(key=lambda x: (x[0], x[1], x[2]))
    return normalized

def merge_interval_maps(map_a, map_b):
    def validate_map(m):
        for item in m:
            if not isinstance(item, tuple) or len(item) != 3:
                raise ValueError("Each interval must be a 3-tuple")
            start, end, label = item
            if not isinstance(start, int) or not isinstance(end, int):
                raise ValueError("Interval endpoints must be integers")
            if start >= end:
                raise ValueError("Interval must satisfy start < end")
            if not isinstance(label, str):
                raise ValueError("Label must be a string")

    validate_map(map_a)
    validate_map(map_b)

    events = []
    for start, end, label in map_a:
        events.append((start, 1, 'a_add', label))
        events.append((end, 1, 'a_remove', label))
    for start, end, label in map_b:
        events.append((start, 1, 'b_add', label))
        events.append((end, 1, 'b_remove', label))

    points = sorted(set([x for x, _, _, _ in events]))
    if not points:
        return []

    def active_label_for(intervals, x):
        labels = [label for s, e, label in intervals if s <= x < e]
        unique = set(labels)
        if len(unique) > 1:
            raise ValueError("Conflicting overlaps within a map")
        return next(iter(unique)) if unique else None

    result = []
    all_segments = sorted(set([p for ivs in (map_a, map_b) for seg in ivs for p in seg[:2]]))
    if len(all_segments) < 2:
        return []
    for i in range(len(all_segments) - 1):
        s, e = all_segments[i], all_segments[i + 1]
        if s == e:
            continue
        la = active_label_for(map_a, s)
        lb = active_label_for(map_b, s)
        if la is None and lb is None:
            continue
        if la is None:
            lab = lb
        elif lb is None:
            lab = la
        elif la == lb:
            lab = la
        else:
            lab = f"{la}|{lb}"
        if result and result[-1][2] == lab and result[-1][1] == s:
            result[-1] = (result[-1][0], e, lab)
        else:
            result.append((s, e, lab))
    return result

def compress_ranges(nums):
    if not nums:
        return ""
    unique_sorted = sorted(set(nums))
    parts = []
    start = prev = unique_sorted[0]
    for x in unique_sorted[1:]:
        if x == prev + 1:
            prev = x
        else:
            parts.append(f"{start}" if start == prev else f"{start}-{prev}")
            start = prev = x
    parts.append(f"{start}" if start == prev else f"{start}-{prev}")
    return ",".join(parts)

def compress_segments(data):
    if not isinstance(data, list):
        raise TypeError("data must be a list")
    if len(data) == 0:
        return []

    for x in data:
        if not isinstance(x, int) or isinstance(x, bool):
            raise TypeError("all elements must be integers")

    result = []
    current = data[0]
    count = 1

    for x in data[1:]:
        if x == current:
            count += 1
        else:
            if count == 1:
                result.append(current)
            else:
                result.append((current, count))
            current = x
            count = 1

    if count == 1:
        result.append(current)
    else:
        result.append((current, count))

    return result

def normalize_inventory_changes(entries):
    totals = {}
    for record in entries:
        if not isinstance(record, tuple) or len(record) != 3:
            continue
        product, location, delta = record
        if not isinstance(product, str) or not isinstance(location, str) or not isinstance(delta, int):
            continue
        key = (product, location)
        totals[key] = totals.get(key, 0) + delta
    return [(product, location, totals[(product, location)]) for product, location in sorted(totals)]

def normalize_measurements(records):
    seen = set()
    valid = []
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 2:
            continue
        label, value = rec
        if not isinstance(label, str) or label.strip() == "":
            continue
        if value is None:
            continue
        if not isinstance(value, (int, float)):
            continue
        if label in seen:
            continue
        seen.add(label)
        valid.append((label, float(value)))
    valid.sort(key=lambda x: (len(x[0]), x[0]))
    return valid

def normalize_slack_schedule(lines):
    import re

    day_map = {
        'mon': 'Mon', 'tue': 'Tue', 'wed': 'Wed', 'thu': 'Thu',
        'fri': 'Fri', 'sat': 'Sat', 'sun': 'Sun'
    }
    day_pattern = re.compile(r'\b(mon|tue|wed|thu|fri|sat|sun)\b', re.IGNORECASE)
    time_pattern = re.compile(r'\b(\d{2}):(\d{2})-(\d{2}):(\d{2})\b')

    result = []
    seen = set()

    for line in lines:
        if not isinstance(line, str):
            continue
        day_match = day_pattern.search(line)
        time_match = time_pattern.search(line)
        if not day_match or not time_match:
            continue

        day = day_map[day_match.group(1).lower()]
        sh, sm, eh, em = map(int, time_match.groups())
        if not (0 <= sh <= 23 and 0 <= eh <= 23 and 0 <= sm <= 59 and 0 <= em <= 59):
            continue
        start = sh * 60 + sm
        end = eh * 60 + em
        if start >= end:
            continue

        slot = f"{day} {sh:02d}:{sm:02d}-{eh:02d}:{em:02d}"
        if slot not in seen:
            seen.add(slot)
            result.append(slot)

    return result

def decode_run_lengths(data):
    if isinstance(data, str):
        if data.strip() == "":
            return []
        result = []
        tokens = data.split()
        for token in tokens:
            if token.count(":") != 1:
                raise ValueError("invalid token format")
            left, right = token.split(":")
            if left == "" or right == "":
                raise ValueError("invalid token format")
            try:
                count = int(left)
                value = int(right)
            except Exception:
                raise ValueError("invalid integer")
            if count < 0:
                raise ValueError("negative count")
            result.extend([value] * count)
        return result
    if isinstance(data, list):
        if len(data) == 0:
            return []
        if len(data) % 2 != 0:
            raise ValueError("list must have even length")
        result = []
        for i in range(0, len(data), 2):
            count = data[i]
            value = data[i + 1]
            if not isinstance(count, int) or not isinstance(value, int):
                raise ValueError("list elements must be integers")
            if count < 0:
                raise ValueError("negative count")
            result.extend([value] * count)
        return result
    raise ValueError("unsupported type")

def run_length_encode_deltas(seq):
    try:
        items = list(seq)
    except TypeError:
        raise TypeError('seq must be iterable')

    for x in items:
        if not isinstance(x, int):
            raise TypeError('all elements must be integers')

    if len(items) < 2:
        return []

    diffs = [items[i] - items[i - 1] for i in range(1, len(items))]
    result = []
    current = diffs[0]
    count = 1

    for d in diffs[1:]:
        if d == current:
            count += 1
        else:
            result.append((current, count))
            current = d
            count = 1

    result.append((current, count))
    return result

def merge_sorted_unique(seqs):
    values = []
    for seq in seqs:
        for item in seq:
            values.append(item)
    if not values:
        return []
    values.sort()
    result = []
    sentinel = object()
    last = sentinel
    for item in values:
        if last is sentinel or item != last:
            result.append(item)
            last = item
    return result

def normalize_path_segments(path: str) -> str:
    segments = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if segments:
                segments.pop()
            continue
        segments.append(part)
    return '/'.join(segments)

def compress_intervals(values):
    try:
        items = list(values)
    except TypeError:
        raise TypeError("values must be iterable")

    seen = set()
    for x in items:
        if type(x) is not int:
            raise TypeError("all elements must be integers")
        seen.add(x)

    if not seen:
        return []

    nums = sorted(seen)
    result = []
    start = prev = nums[0]

    for n in nums[1:]:
        if n == prev + 1:
            prev = n
        else:
            result.append((start, prev))
            start = prev = n
    result.append((start, prev))
    return result

def summarize_run_length(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return ""

    parts = []
    current = text[0]
    count = 1

    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(f"{current}{count}")
            current = ch
            count = 1

    parts.append(f"{current}{count}")
    return "|".join(parts)

def normalize_scene_key(path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    parts = []
    current = []
    for ch in path:
        if ch == '/' or ch == '\\':
            if current:
                segment = ''.join(current)
                if segment == '..':
                    if parts:
                        parts.pop()
                elif segment != '.':
                    parts.append(segment)
                current = []
            else:
                continue
        else:
            current.append(ch)

    if current:
        segment = ''.join(current)
        if segment == '..':
            if parts:
                parts.pop()
        elif segment != '.':
            parts.append(segment)

    return ':'.join(parts) if parts else 'root'

def normalize_schedule_intervals(intervals):
    valid = []
    for item in intervals:
        if len(item) != 2:
            raise ValueError("Each interval must have exactly two elements")
        start, end = item
        if start >= end:
            continue
        valid.append((start, end))

    if not valid:
        return []

    valid.sort(key=lambda x: (x[0], x[1]))
    merged = [valid[0]]

    for start, end in valid[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))

    return merged

def summarize_spans(events, max_gap):
    if not isinstance(max_gap, int):
        raise TypeError("max_gap must be an integer")
    if max_gap < 1:
        raise ValueError("max_gap must be at least 1")
    for x in events:
        if not isinstance(x, int):
            raise TypeError("events must contain only integers")
    if not events:
        return []
    unique_sorted = sorted(set(events))
    spans = []
    start = prev = unique_sorted[0]
    for v in unique_sorted[1:]:
        if v - prev <= max_gap:
            prev = v
        else:
            spans.append((start, prev))
            start = prev = v
    spans.append((start, prev))
    return spans

def canonicalize_header_pairs(pairs):
    cleaned = []
    for item in pairs:
        try:
            a, b = item
        except Exception:
            continue
        if not isinstance(a, str) or not isinstance(b, str):
            continue
        name = a.strip()
        value = b.strip()
        if not name:
            continue
        cleaned.append((name.lower(), value))

    last_index = {}
    for idx, (name, value) in enumerate(cleaned):
        last_index[name] = idx

    result = []
    for idx, (name, value) in enumerate(cleaned):
        if last_index[name] == idx:
            result.append([name, value])
    return result

def normalize_inventory_log(entries):
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')

    totals = {}
    order = {}
    next_index = 0

    for rec in entries:
        if not isinstance(rec, (list, tuple)) or len(rec) != 3:
            raise TypeError('each record must be a 3-item sequence')
        item_id, delta, location = rec
        if not isinstance(item_id, str) or not isinstance(location, str):
            raise TypeError('item_id and location must be strings')
        if item_id == '' or location == '':
            raise ValueError('item_id and location must be non-empty strings')
        if not isinstance(delta, int) or isinstance(delta, bool):
            raise TypeError('delta must be an integer')

        key = (item_id, location)
        if key not in totals:
            totals[key] = 0
            order[key] = next_index
            next_index += 1
        totals[key] += delta

    result = [(item_id, location, total) for (item_id, location), total in totals.items() if total != 0]
    result.sort(key=lambda x: (x[0], x[1]))
    return result

def canonicalize_inventory_changes(changes):
    totals = {}
    for record in changes:
        try:
            item_id, delta = record
        except Exception:
            raise ValueError("each record must be a 2-item iterable")
        if not isinstance(item_id, str):
            raise ValueError("item_id must be a string")
        if not isinstance(delta, int):
            raise ValueError("delta must be an int")
        normalized = item_id.strip().lower()
        if normalized == "":
            raise ValueError("item_id cannot be empty after normalization")
        totals[normalized] = totals.get(normalized, 0) + delta
    result = [(item_id, net_delta) for item_id, net_delta in totals.items() if net_delta != 0]
    result.sort(key=lambda pair: (-abs(pair[1]), pair[0]))
    return result

def summarize_shelf(records):
    active = set()
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError('each record must be a 3-tuple')
        shelf_id, book_code, status = rec
        if status not in ('placed', 'removed'):
            raise ValueError('invalid status')
        key = (shelf_id, book_code)
        if status == 'placed':
            active.add(key)
        else:
            active.discard(key)
    active_list = sorted(active)
    counts = {}
    for shelf_id, book_code in active_list:
        counts[shelf_id] = counts.get(shelf_id, 0) + 1
    return {'active': active_list, 'counts': counts}

def compress_ranges(values):
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    unique = []
    seen = set()
    for x in values:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("all elements must be integers")
        if x not in seen:
            seen.add(x)
            unique.append(x)

    if not unique:
        return ""

    nums = sorted(unique)
    parts = []
    start = prev = nums[0]

    for n in nums[1:]:
        if n == prev + 1:
            prev = n
            continue
        length = prev - start + 1
        if length >= 3:
            parts.append(f"{start}-{prev}")
        else:
            parts.extend(str(i) for i in range(start, prev + 1))
        start = prev = n

    length = prev - start + 1
    if length >= 3:
        parts.append(f"{start}-{prev}")
    else:
        parts.extend(str(i) for i in range(start, prev + 1))

    return ",".join(parts)

def run_length_encode_segments(s: str) -> list[tuple[str, int]]:
    if not isinstance(s, str):
        raise TypeError('s must be a str')
    if s == '':
        return []

    result = []
    current_char = s[0]
    count = 1

    for ch in s[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append((current_char, count))
            current_char = ch
            count = 1

    result.append((current_char, count))
    return result

def normalize_inventory_events(events):
    totals = {}
    result = []
    for event in events:
        if not isinstance(event, dict):
            continue
        if set(event.keys()) != {"sku", "delta", "warehouse"}:
            continue
        sku = event.get("sku")
        delta = event.get("delta")
        warehouse = event.get("warehouse")
        if not isinstance(sku, str) or sku == "":
            continue
        if type(delta) is not int:
            continue
        key = (sku, warehouse)
        new_total = totals.get(key, 0) + delta
        totals[key] = new_total
        result.append({"sku": sku, "delta": delta, "warehouse": warehouse, "resulting_total": new_total})
    return result

def normalize_path(path: str) -> str:
    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
            continue
        parts.append(segment)
    return '/' + '/'.join(parts) if parts else '/'

def compress_ranges(values):
    unique_sorted = sorted(set(values))
    if not unique_sorted:
        return []

    ranges = []
    start = prev = unique_sorted[0]

    for x in unique_sorted[1:]:
        if x == prev + 1:
            prev = x
        else:
            ranges.append((start, prev))
            start = prev = x
    ranges.append((start, prev))
    return ranges

def normalize_schedule(slots):
    valid = []
    for item in slots:
        try:
            start, end = item
        except Exception:
            continue
        if isinstance(start, int) and isinstance(end, int) and 0 <= start < end <= 1440:
            valid.append((start, end))
    if not valid:
        return []
    valid.sort(key=lambda x: (x[0], x[1]))
    merged = [valid[0]]
    for start, end in valid[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
