def normalize_durations(items):
    result = []
    for item in items:
        if not isinstance(item, str):
            raise ValueError('all items must be strings')
        if item == '':
            raise ValueError('empty string is invalid')
        suffix = item[-1]
        if suffix not in ('s', 'm', 'h'):
            raise ValueError('invalid suffix')
        num_part = item[:-1]
        if num_part == '':
            raise ValueError('missing numeric part')
        if num_part[0] == '-':
            raise ValueError('negative values are invalid')
        if not num_part.isdigit():
            raise ValueError('invalid numeric part')
        value = int(num_part)
        seconds = value
        if suffix == 'm':
            seconds = value * 60
        elif suffix == 'h':
            seconds = value * 3600
        if seconds % 3600 == 0:
            result.append(f'{seconds // 3600}h')
        elif seconds % 60 == 0:
            result.append(f'{seconds // 60}m')
        else:
            result.append(f'{seconds}s')
    return result

def compress_runs(items):
    try:
        iterator = iter(items)
    except TypeError:
        raise TypeError("items must be iterable")

    result = []
    sentinel = object()
    prev = sentinel
    count = 0

    for value in iterator:
        try:
            hash(value)
        except TypeError:
            raise TypeError("iterable contains unhashable value")

        if prev is sentinel:
            prev = value
            count = 1
        elif value == prev:
            count += 1
        else:
            result.append((prev, count))
            prev = value
            count = 1

    if prev is not sentinel:
        result.append((prev, count))

    return result

def summarize_runs(s):
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if s == "":
        return {"count": 0, "longest_nondec_run": 0, "first_invalid_index": None}

    parts = s.split(',')
    count = 0
    first_invalid_index = None
    longest = 0
    current = 0
    prev_val = None

    for idx, raw in enumerate(parts):
        token = raw.strip()
        valid = False
        if token:
            if token[0] == '-':
                valid = len(token) > 1 and token[1:].isdigit()
            else:
                valid = token.isdigit()
        if not valid:
            if first_invalid_index is None:
                first_invalid_index = idx
            current = 0
            prev_val = None
            continue

        val = int(token)
        count += 1
        if current == 0:
            current = 1
        else:
            if prev_val is not None and val >= prev_val:
                current += 1
            else:
                current = 1
        prev_val = val
        if current > longest:
            longest = current

    return {"count": count, "longest_nondec_run": longest, "first_invalid_index": first_invalid_index}

