def normalize_path_tokens(path: str) -> str:
    if path == "":
        return "."

    absolute = path.startswith("/")
    parts = path.split("/")
    stack = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
