        raise ValueError("min_run_length must be an integer >= 1")

    items = list(seq)
    if not items:
        return []

    for x in items:
        if not isinstance(x, int):
            raise TypeError("seq must contain only integers")

    result = []
    start = 0
    current = items[0]

    for i in range(1, len(items) + 1):
