def summarize_transcript(log: str) -> dict:
    speakers = []
    seen = set()
    total_words = 0
    longest_message = ""
    longest_count = -1

    for line in log.splitlines():
        stripped = line.strip()
        if ":" not in stripped:
            continue
        speaker_part, message_part = stripped.split(":", 1)
        speaker = speaker_part.strip()
        if speaker == "":
            continue
        message = message_part.strip()
        words = message.split() if message else []
        count = len(words)
        if speaker not in seen:
            seen.add(speaker)
            speakers.append(speaker)
        total_words += count
        if count > longest_count:
            longest_count = count
            longest_message = message
    if longest_count == -1:
        return {'speakers': [], 'word_count': 0, 'longest_message': ''}
    return {'speakers': speakers, 'word_count': total_words, 'longest_message': longest_message}

def select_weighted_variant(items, top_k, variant):
    if not isinstance(items, list):
        raise ValueError('items must be a list')
    if not isinstance(top_k, int):
        raise ValueError('top_k must be an integer')
    if top_k < 0:
        raise ValueError('top_k must be non-negative')
    if variant not in {'score', 'weight', 'hybrid'}:
        raise ValueError('invalid variant')

    validated = []
    for item in items:
        if not isinstance(item, dict):
            raise ValueError('each item must be a dict')
        if set(item.keys()) != {'id', 'score', 'weight'}:
            raise ValueError('each item must have exactly id, score, and weight')
        item_id = item['id']
        score = item['score']
        weight = item['weight']
        if not isinstance(item_id, str) or item_id == '':
            raise ValueError('id must be a non-empty string')
        if not isinstance(score, int):
            raise ValueError('score must be an integer')
        if not isinstance(weight, (int, float)):
            raise ValueError('weight must be numeric')
        validated.append({'id': item_id, 'score': score, 'weight': weight})

    if top_k == 0:
        return []

    if variant == 'score':
        key_func = lambda x: (-x['score'], x['id'])
    elif variant == 'weight':
        key_func = lambda x: (-x['weight'], x['id'])
    else:
        key_func = lambda x: (-(x['score'] * x['weight']), x['id'])

    sorted_items = sorted(validated, key=key_func)
    return [dict(item) for item in sorted_items[:top_k]]

