def format_duration(seconds):
    if not isinstance(seconds, int) or isinstance(seconds, bool) or seconds < 0:
        raise ValueError("seconds must be a non-negative integer")

    if seconds == 0:
        return "now"

    units = [
        (365 * 24 * 60 * 60, "year"),
        (24 * 60 * 60, "day"),
        (60 * 60, "hour"),
        (60, "minute"),
        (1, "second"),
    ]

    parts = []
    remaining = seconds
    for unit_seconds, name in units:
        value, remaining = divmod(remaining, unit_seconds)
        if value:
            label = name if value == 1 else name + "s"
            parts.append(f"{value} {label}")

    if len(parts) == 1:
        return parts[0]
    return ", ".join(parts[:-1]) + " and " + parts[-1]

def normalize_mixed_numbers(values):
    if not isinstance(values, list):
        raise ValueError("values must be a list")

    result = []
    for item in values:
        if not isinstance(item, str):
            raise ValueError("all items must be strings")
        s = item
        if s == "":
            raise ValueError("invalid number string")

        sign = ""
        if s[0] in "+-":
            sign = s[0]
            s = s[1:]
        if s == "":
            raise ValueError("invalid number string")

        if s.count(".") > 1:
            raise ValueError("invalid number string")

        if "." in s:
            left, right = s.split(".", 1)
            if left == "" and right == "":
                raise ValueError("invalid number string")
            if left and not left.isdigit():
                raise ValueError("invalid number string")
            if right and not right.isdigit():
                raise ValueError("invalid number string")
            if left == "":
                left = "0"
            left = left.lstrip("0") or "0"
            right = right.rstrip("0")
            if left == "0" and right == "":
                result.append("0")
                continue
            normalized = left
            if right != "":
                normalized += "." + right
        else:
            if not s.isdigit():
                raise ValueError("invalid number string")
            left = s.lstrip("0") or "0"
            if left == "0":
                result.append("0")
                continue
            normalized = left

        if normalized == "0":
            result.append("0")
        else:
            if sign == "-":
                result.append("-" + normalized)
            else:
                result.append(normalized)
    return result

def merge_interval_logs(entries):
    if entries is None:
        raise TypeError('entries must be an iterable of records')
    normalized = {}
    for item in entries:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each entry must be a 2-tuple')
        label, interval = item
        if not isinstance(label, str) or label == '':
            raise ValueError('label must be a non-empty string')
        if not isinstance(interval, tuple) or len(interval) != 2:
            raise TypeError('interval must be a 2-tuple')
        start, end = interval
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('interval endpoints must be integers')
        if start > end:
            start, end = end, start
        normalized.setdefault(label, []).append((start, end))

    result = []
    for label in sorted(normalized):
        intervals = sorted(normalized[label])
        merged = []
        for start, end in intervals:
            if not merged:
                merged.append([start, end])
                continue
            prev_start, prev_end = merged[-1]
            if start <= prev_end + 1:
                if end > prev_end:
                    merged[-1][1] = end
            else:
                merged.append([start, end])
        for start, end in merged:
            result.append((label, (start, end)))
    return result

def parse_coordinate_path(s):
    if not isinstance(s, str):
        raise ValueError('input must be a string')
    if s.strip() == '':
        return [(0, 0)]

    result = [(0, 0)]
    x = y = 0
    tokens = s.split(',')
    for raw in tokens:
        token = raw.strip()
        if not token:
            raise ValueError('empty token')
        if len(token) < 2:
            raise ValueError('malformed token')
        direction = token[0]
        steps_str = token[1:]
        if direction not in 'UDLR':
            raise ValueError('unknown direction')
        if not steps_str.isdigit():
            raise ValueError('invalid steps')
        steps = int(steps_str)
        if steps <= 0:
            raise ValueError('steps must be positive')
        if direction == 'U':
            y += steps
        elif direction == 'D':
            y -= steps
        elif direction == 'R':
            x += steps
        else:
            x -= steps
        result.append((x, y))
    return result

def merge_intervals_with_payloads(items):
    if items is None:
        raise ValueError('items must be a list of interval-payload pairs')
