            raise ValueError('each item must be a 2-tuple')
        interval, payload = item
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            raise ValueError('interval must have exactly two endpoints')
        a, b = interval
        if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
            raise ValueError('endpoints must be numeric')
        start, end = (a, b) if a <= b else (b, a)
        merged_input.append((start, end, payload))
    if not merged_input:
        return []
    merged_input.sort(key=lambda x: (x[0], x[1]))
    result = []
    cur_start, cur_end, cur_payloads = merged_input[0][0], merged_input[0][1], [merged_input[0][2]]
    for start, end, payload in merged_input[1:]:
        if start <= cur_end:
            if end > cur_end:
                cur_end = end
            cur_payloads.append(payload)
        else:
            result.append(((cur_start, cur_end), cur_payloads))
            cur_start, cur_end, cur_payloads = start, end, [payload]
    result.append(((cur_start, cur_end), cur_payloads))
    return result

def normalize_event_windows(windows):
