            raise ValueError("each record must be a 3-item tuple")
        timestamp, kind, payload = rec
        if not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError("timestamp must be a non-negative integer")
        if not isinstance(kind, str):
            raise ValueError("kind must be a string")
        key = (timestamp, kind, repr(payload))
        if key in seen:
            continue
        seen.add(key)
        normalized.append({"timestamp": timestamp, "kind": kind, "payload": payload})
    normalized.sort(key=lambda d: d["timestamp"])
    return normalized

def normalize_inventory_events(events):
    totals = {}
    for event in events:
        try:
            item, delta = event
        except Exception:
            raise ValueError("each event must be a 2-tuple")

        if not isinstance(item, str):
            raise ValueError("item must be a string")
        normalized_item = item.strip()
        if normalized_item == "":
            raise ValueError("item cannot be empty after stripping")

        if isinstance(delta, int):
            normalized_delta = delta
        elif isinstance(delta, str):
            s = delta.strip()
            if s == "":
                raise ValueError("delta string cannot be empty")
            sign = 1
            if s[0] in "+-":
                if s[0] == '-':
                    sign = -1
                s = s[1:]
            if s == "" or not s.isdigit():
                raise ValueError("delta must be an integer")
            normalized_delta = sign * int(s)
        else:
            raise ValueError("delta must be an integer or integer string")

        totals[normalized_item] = totals.get(normalized_item, 0) + normalized_delta
        if totals[normalized_item] == 0:
            del totals[normalized_item]

    return sorted(totals.items(), key=lambda kv: kv[0])

def normalize_schedule(slots, inclusive_end=False):
    try:
        items = list(slots)
    except TypeError:
        raise TypeError("slots must be an iterable of 2-item sequences")

    validated = []
    for slot in items:
        if len(slot) != 2:
            raise ValueError("each slot must contain exactly two integers")
        start, end = slot
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("slot boundaries must be integers")
        if start >= end:
            raise ValueError("each slot must satisfy start < end")
        validated.append((start, end))

    if not validated:
        return []

    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [validated[0]]

    for start, end in validated[1:]:
        last_start, last_end = merged[-1]
        if inclusive_end:
            overlaps = start <= last_end
        else:
            overlaps = start < last_end

        if overlaps:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged

def compress_intervals(values, gap):
    if not isinstance(gap, int) or gap <= 0:
        raise ValueError("gap must be a positive integer")

    vals = list(values)
    for v in vals:
        if not isinstance(v, int):
            raise ValueError("all values must be integers")

    if not vals:
        return []

    runs = []
    start = prev = vals[0]
    count = 1

    for v in vals[1:]:
        if abs(v - prev) <= gap:
            prev = v
            count += 1
        else:
            runs.append((start, prev, count))
            start = prev = v
            count = 1

    runs.append((start, prev, count))
    return runs

def segment_signature(text: str) -> list[int]:
    if text == "":
        return []

    result = []
    current = text[0]
    length = 1

    def signed_len(ch: str, n: int) -> int:
        if "A" <= ch <= "Z":
            return n
        if "a" <= ch <= "z":
            return -n
        return 0

    for ch in text[1:]:
        if ch == current:
            length += 1
        else:
            result.append(signed_len(current, length))
            current = ch
            length = 1

    result.append(signed_len(current, length))
    return result

def normalize_org_path(path: str) -> str:
    parts = []
