                parts.pop()
            continue
        parts.append(segment)
    return '/'.join(parts)

def compact_intervals(values):
    try:
        items = list(values)
    except TypeError:
        raise TypeError("values must be iterable")

    for x in items:
        if type(x) is not int:
            raise TypeError("all elements must be ints")

    if not items:
        return []

    uniq = sorted(set(items))
    result = []
    start = prev = uniq[0]

    for n in uniq[1:]:
        if n == prev + 1:
            prev = n
        else:
            result.append([start, prev])
            start = prev = n
    result.append([start, prev])
    return result

def compress_intervals(intervals):
    normalized = []
    for item in intervals:
        try:
            if len(item) != 2:
                raise ValueError
            start, end = item
        except Exception:
            raise ValueError("Each interval must contain exactly two values")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Interval endpoints must be integers")
        if start > end:
            raise ValueError("Interval start must be <= end")
        normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def canonicalize_event_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    s = path.strip()
    if s == "":
