    parts = []
    for segment in s.split("/"):
        if segment == "" or segment == ".":
            continue
        if segment == "..":
            if parts:
                parts.pop()
            continue
        parts.append(segment)

    return "/" + "/".join(parts) if parts else "/"

def normalize_log_fields(records):
    if not isinstance(records, list):
