    result = []
    for item in records:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("each record must be a 2-item tuple")
        timestamp, message = item
        if not isinstance(timestamp, int):
            raise TypeError("timestamp must be an int")
        if not isinstance(message, str):
            continue
        if timestamp < 0:
            continue
        normalized_message = '_'.join(message.strip().lower().split())
        result.append((timestamp // 60, normalized_message))
    return result

def select_minimal_cover(segments, universe):
    points = sorted(set(universe))
    if not points:
        return []

    n = len(segments)
    seg_sets = []
    for start, end in segments:
        if start <= end:
            covered = set(range(start, end + 1))
        else:
            covered = set()
        seg_sets.append(covered)

    target = set(points)
    best = None

    # Enumerate subsets by increasing size, then lexicographically by indices.
    for size in range(1, n + 1):
        def backtrack(start_idx, chosen, covered):
            nonlocal best
            if best is not None:
                return
            if len(chosen) == size:
                if covered >= target:
                    best = chosen.copy()
                return
            # Prune if not enough segments left.
            if start_idx >= n or len(chosen) + (n - start_idx) < size:
                return
            for i in range(start_idx, n):
                chosen.append(i)
                backtrack(i + 1, chosen, covered | seg_sets[i])
                chosen.pop()
                if best is not None:
                    return

        backtrack(0, [], set())
        if best is not None:
            return best

    return None

def normalize_inventory(lines):
    result = {}
    units = {}
    for line in lines:
        if not isinstance(line, str):
            raise ValueError('each line must be a string')
        parts = line.split(',')
        if len(parts) != 3:
            raise ValueError('malformed line')
        name_raw, qty_raw, unit_raw = (p.strip() for p in parts)
        if not name_raw or not qty_raw or not unit_raw:
            raise ValueError('empty field')
        name = name_raw.lower()
        unit = unit_raw.lower()
        if not unit.isalpha():
            raise ValueError('invalid unit')
        try:
            qty = int(qty_raw)
        except Exception:
            raise ValueError('invalid quantity')
        if name in units and units[name] != unit:
            raise ValueError('conflicting units')
        units[name] = unit
        if name in result:
            result[name] = (result[name][0] + qty, unit)
        else:
            result[name] = (qty, unit)
    return result

