def parse_duration(spec: str) -> int:
    if not isinstance(spec, str) or spec == '':
        raise ValueError('invalid duration')

    multipliers = {'w': 7 * 24 * 60 * 60, 'd': 24 * 60 * 60, 'h': 60 * 60, 'm': 60, 's': 1}
    order = {'w': 0, 'd': 1, 'h': 2, 'm': 3, 's': 4}

    sign = 1
    i = 0
    if spec[0] in '+-':
        sign = -1 if spec[0] == '-' else 1
        i = 1
        if i >= len(spec):
            raise ValueError('invalid duration')

    total = 0
    last_order = -1
    seen = set()

    while i < len(spec):
        if not spec[i].isdigit():
            raise ValueError('invalid duration')
        start = i
        while i < len(spec) and spec[i].isdigit():
            i += 1
        if i >= len(spec):
            raise ValueError('invalid duration')
        unit = spec[i]
        if unit not in multipliers:
            raise ValueError('invalid duration')
        unit_order = order[unit]
        if unit_order <= last_order or unit in seen:
            raise ValueError('invalid duration')
        seen.add(unit)
        last_order = unit_order
        value = int(spec[start:i])
        total += value * multipliers[unit]
        i += 1

    return sign * total

def canonicalize_permissions(entries):
    result = {}

    def normalize_path(path):
        path = path.strip()
        while '//' in path:
            path = path.replace('//', '/')
        if path.endswith('/') and path != '/':
            path = path[:-1]
        if path == '':
            path = '/'
        return path

    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise TypeError('each entry must be a 2-item tuple')
        path, mode = entry
        if not isinstance(path, str):
            raise TypeError('path must be a string')
        norm_path = normalize_path(path)

        if isinstance(mode, int):
            if mode < 0 or mode > 0o777:
                raise ValueError('integer mode out of range')
            norm_mode = mode
        elif isinstance(mode, str):
            if mode == '' or not mode.isdigit():
                raise ValueError('string mode must contain digits only')
            norm_mode = int(mode, 8)
            if norm_mode < 0 or norm_mode > 0o777:
                raise ValueError('string mode out of range')
        else:
            raise TypeError('mode must be int or str')

        result[norm_path] = norm_mode

    return result

