def normalize_route_steps(path):
    if path is None:
        raise ValueError("path must be a string")
    if not isinstance(path, str):
        raise ValueError("path must be a string")

    stripped = path.strip()
    if stripped == "":
        return [(0, 0)]

    steps = stripped.split(',')
    if any(step.strip() == "" for step in steps):
        raise ValueError("malformed route")

    x, y = 0, 0
    visited = [(0, 0)]
    seen = {(0, 0)}

    for raw_step in steps:
        step = raw_step.strip()
        if ':' not in step:
            raise ValueError("malformed route")
        parts = step.split(':')
        if len(parts) != 2:
            raise ValueError("malformed route")
        direction = parts[0].strip()
        count_text = parts[1].strip()
        if direction not in {'N', 'S', 'E', 'W'}:
            raise ValueError("malformed route")
        if count_text == "" or not count_text.isdigit():
            raise ValueError("malformed route")
        count = int(count_text)
        if count < 0:
            raise ValueError("malformed route")

        dx, dy = 0, 0
        if direction == 'N':
            dy = 1
        elif direction == 'S':
            dy = -1
        elif direction == 'E':
            dx = 1
        else:
            dx = -1

        for _ in range(count):
            x += dx
            y += dy
            coord = (x, y)
            if coord not in seen:
                seen.add(coord)
                visited.append(coord)

    return visited

def normalize_records(records):
    try:
        iterator = iter(records)
    except TypeError:
        raise TypeError("records must be iterable")

    seen = {}
    for rec in iterator:
        key = value = None
        is_mapping = False
        if hasattr(rec, 'keys') and callable(getattr(rec, 'keys')):
            try:
                keys = set(rec.keys())
            except Exception:
                keys = None
            if keys == {'key', 'value'}:
                is_mapping = True
                key = rec['key']
                value = rec['value']
        if not is_mapping:
            try:
                pair = list(rec)
            except TypeError:
                raise TypeError("invalid record")
            if len(pair) != 2:
                raise TypeError("record must have exactly two items")
            key, value = pair
        norm_key = str(key).strip().upper()
        if norm_key == '':
            continue
        if norm_key in seen:
            continue
        norm_value = str(value).strip()
        seen[norm_key] = f"{norm_key}={norm_value}"
    return [seen[k] for k in sorted(seen)]

