        except TypeError:
            raise TypeError('elements must be hashable')

        if current is sentinel:
            current = item
            count = 1
        elif item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1

    if current is not sentinel:
        result.append((current, count))

    return result

def decode_runlength_segments(text: str) -> list[str]:
    if text == "":
        return []
    result = []
    segments = text.split(';')
    for segment in segments:
        if segment == "":
            raise ValueError("empty segment")
        parts = segment.split(':')
        if len(parts) != 2:
            raise ValueError("malformed segment")
        count_str, payload = parts
        if count_str == "" or count_str[0] in '+-':
            raise ValueError("invalid count")
        if not count_str.isdigit():
            raise ValueError("invalid count")
        count = int(count_str)
        if count < 0:
            raise ValueError("negative count")
        result.extend([payload] * count)
    return result

def compress_intervals(values):
    seen = set()
    for v in values:
        if type(v) is not int:
            raise TypeError("all elements must be integers")
        seen.add(v)

    if not seen:
        return []

    nums = sorted(seen)
    intervals = []
    start = prev = nums[0]

    for x in nums[1:]:
        if x == prev + 1:
            prev = x
        else:
            intervals.append((start, prev))
            start = prev = x
    intervals.append((start, prev))
    return intervals

def normalize_log_lines(lines):
    allowed = {"INFO", "WARN", "ERROR"}
    result = []
    for item in lines:
        if not isinstance(item, str):
            continue
        s = item.strip()
        if not s:
            continue
        if '|' not in s:
            continue
        level_part, message_part = s.split('|', 1)
        level = level_part.strip().upper()
        if level not in allowed:
            continue
        message = ' '.join(message_part.strip().split())
        result.append(f"{level}|{message}")
    return result

def normalize_invoice_lines(lines):
    try:
        iterator = iter(lines)
    except TypeError:
        raise TypeError('lines must be an iterable of strings')

    normalized_lines = []
    comments_removed = 0

    for item in iterator:
        if not isinstance(item, str):
            raise TypeError('lines must be an iterable of strings')

        stripped = item.strip()
        if stripped == '':
            continue
        if stripped.startswith('#'):
            comments_removed += 1
            continue

        def normalize_text(text):
            return ' '.join(text.strip().split()).upper()

        if '::' in stripped:
            left, right = stripped.split('::', 1)
            normalized = f"{normalize_text(left)} :: {normalize_text(right)}"
        else:
            normalized = normalize_text(stripped)

        normalized_lines.append(normalized)

    summary = {
        'count': len(normalized_lines),
        'unique': len(set(normalized_lines)),
        'comments_removed': comments_removed,
    }
    return normalized_lines, summary

def parse_grid_paths(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    count = 0
    labels = []
    total_weight = 0
    longest_path = ''
    valid = True

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if line == '':
            continue

        parts = [p.strip() for p in line.split(',')]
        if len(parts) != 3:
            valid = False
            continue

        label, weight_str, path = parts

        if not label or any(ch not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_' for ch in label):
            valid = False
            continue

        try:
            weight = int(weight_str, 10)
        except Exception:
            valid = False
            continue

        if not path or any(ch not in 'UDLR' for ch in path):
            valid = False
            continue

        count += 1
        labels.append(label)
        total_weight += weight
        if len(path) > len(longest_path):
            longest_path = path

    return {
        'count': count,
        'labels': labels,
        'total_weight': total_weight,
        'longest_path': longest_path,
        'valid': valid,
    }

