def normalize_event_schedule(events):
    seen = set()
    by_day = {}
    total_events = 0
    total_duration = 0

    if not isinstance(events, list):
        return {"days": [], "total_events": 0, "total_duration": 0}

    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 4:
            continue
        day, start_minute, end_minute, label = rec
        if not isinstance(day, str):
            continue
        if not isinstance(label, str) or label == "":
            continue
        if not isinstance(start_minute, int) or not isinstance(end_minute, int):
            continue
        if not (0 <= start_minute < end_minute <= 1440):
            continue
        if rec in seen:
            continue
        seen.add(rec)
        by_day.setdefault(day, []).append((start_minute, end_minute, label))
        total_events += 1
        total_duration += end_minute - start_minute

    days = []
    for day in sorted(by_day):
        day_events = sorted(by_day[day], key=lambda x: (x[0], x[1], x[2]))
        duration = sum(end - start for start, end, _ in day_events)
        days.append({"day": day, "events": day_events, "duration": duration})

    return {"days": days, "total_events": total_events, "total_duration": total_duration}

def normalize_log_events(events):
    if not events:
        return []

    normalized = []
    for event in events:
        if not isinstance(event, dict):
            continue

        required = ("ts", "user", "action", "status", "tags")
        if any(key not in event for key in required):
            continue

        ts = event["ts"]
        user = event["user"]
        action = event["action"]
        status = event["status"]
        tags = event["tags"]

        if not isinstance(ts, int):
            continue
        if not isinstance(user, str) or user.strip() == "":
            continue
        if not isinstance(action, str) or action.strip() == "":
            continue
        if status not in ("ok", "fail"):
