def normalize_events(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')

    normalized = []
    seen = set()
    for event in events:
        try:
            if len(event) != 3:
                raise ValueError('each event must have exactly 3 items')
            timestamp, label, kind = event
        except TypeError:
            raise ValueError('each event must be a 3-item sequence')

        if not isinstance(timestamp, int):
            raise TypeError('timestamp must be int')
        if not isinstance(label, str):
            raise TypeError('label must be str')
        if kind not in ('start', 'end'):
            raise ValueError('kind must be start or end')

        norm_label = ' '.join(label.split()).lower()
        key = (timestamp, norm_label, kind)
        if key in seen:
            raise ValueError('duplicate event')
        seen.add(key)
        normalized.append((timestamp, norm_label, kind))

    grouped = {}
    for timestamp, label, kind in normalized:
        grouped.setdefault(label, []).append((timestamp, kind))

    result = []
    for label in sorted(grouped):
        items = sorted(grouped[label], key=lambda x: (x[0], 0 if x[1] == 'start' else 1))
        starts = ends = 0
        stack = []
        intervals = []
        valid = True
        for timestamp, kind in items:
            if kind == 'start':
                starts += 1
                stack.append(timestamp)
            else:
                ends += 1
                if not stack:
                    valid = False
                    break
                s = stack.pop(0)
                intervals.append((s, timestamp))
        if valid and starts == ends and not stack:
            result.append((label, intervals))

    return result

def canonicalize_route(route):
    if not isinstance(route, str):
        raise TypeError('route must be a string')

    parts = []
    for raw in route.split('/'):
        segment = raw.strip()
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
            continue
        parts.append(segment)
    return '/' + '/'.join(parts)

def split_around_marker(s: str, marker: str) -> tuple[str, str]:
    if marker == "":
        raise ValueError("marker must not be empty")
    index = s.find(marker)
    if index == -1:
        raise ValueError("marker not found")
    return s[:index], s[index + len(marker):]

import re

def normalize_ticket_codes(codes):
    pattern = re.compile(r'^T-[A-Z]+-[0-9]+$')
    result = []
    seen = set()
    for item in codes:
        if not isinstance(item, str):
            continue
        normalized = item.strip().upper()
