def compress_sorted_runs(values):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if len(values) == 0:
        return []
    for x in values:
        if not isinstance(x, int):
            raise TypeError("all elements must be integers")
    result = []
    current = values[0]
    count = 1
    for x in values[1:]:
        if x == current:
            count += 1
        else:
            result.append([current, count])
            current = x
            count = 1
    result.append([current, count])
    return result

def normalize_path_segments(path: str) -> str:
    if path == '':
        return '.'

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        if not stack:
            return '/'
        return '/' + '/'.join(stack)

    if not stack:
        return '.'
    return '/'.join(stack)

def normalize_file_manifest(entries):
    if not isinstance(entries, list):
        raise ValueError

    def normalize_path(path):
        path = path.replace('\\', '/')
        while '//' in path:
            path = path.replace('//', '/')
        while path.startswith('./'):
            path = path[2:]
        return path

    best = {}
    order = {}

    for idx, entry in enumerate(entries):
        if not (isinstance(entry, (tuple, list)) and len(entry) == 2):
            raise ValueError
        path, size = entry
        if not isinstance(path, str) or path == '' or '\x00' in path:
            raise ValueError
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise ValueError

        norm_path = normalize_path(path)
        if norm_path == '':
            raise ValueError

        if norm_path not in best:
            best[norm_path] = size
            order[norm_path] = idx
        else:
            current_size = best[norm_path]
            if size > current_size:
                best[norm_path] = size
                order[norm_path] = idx
            elif size == current_size:
                pass

    result = [(p, best[p]) for p in sorted(best.keys())]
    return result

def normalize_chat_command(command: str) -> dict:
    if not isinstance(command, str):
        raise ValueError("command must be a string")

    s = command.strip()
    if not s or not s.startswith('/'):
        raise ValueError("invalid command")

    parts = s.split()
    first = parts[0]
    action = first[1:]
    if not action or not action.replace('_', '').isalnum() or not action[0].isalpha() and not action[0].isdigit():
        raise ValueError("invalid action")
    if not all(ch.isalnum() or ch == '_' for ch in action):
        raise ValueError("invalid action")

    target = None
    options = {}
    seen_target = False

    for token in parts[1:]:
        if '=' in token:
            key, value = token.split('=', 1)
            if not key or not all(ch.isalnum() or ch == '_' for ch in key):
                raise ValueError("invalid option key")
            options[key] = value
        else:
            if not seen_target:
                target = token
                seen_target = True
            else:
                raise ValueError("unexpected extra token")

    return {"action": action, "target": target, "options": options}

