def summarize_shelf_layout(shelves):
    if not isinstance(shelves, list):
        raise TypeError("shelves must be a list")

    if len(shelves) == 0:
        return {"densest": None, "emptiest": None, "uniform": True}

    counts = []
    for shelf in shelves:
        if not isinstance(shelf, list):
            raise TypeError("each shelf must be a list")
        count = 0
        for title in shelf:
            if isinstance(title, str):
                if title.strip() != "":
                    count += 1
        counts.append(count)

    max_count = max(counts)
    min_count = min(counts)
    densest = next(i for i, c in enumerate(counts) if c == max_count)
    emptiest = next(i for i, c in enumerate(counts) if c == min_count)
    uniform = all(c == counts[0] for c in counts)
    return {"densest": densest, "emptiest": emptiest, "uniform": uniform}

