    if not isinstance(text, str):
        raise TypeError("text must be a string")

    runs = []
    if text == "":
        return {"runs": [], "longest": 0, "starts_with": None, "ends_with": None}

    current_char = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current_char:
            count += 1
        else:
            runs.append((current_char, count))
            current_char = ch
            count = 1
    runs.append((current_char, count))

    longest = max(cnt for _, cnt in runs)
    return {
        "runs": runs,
        "longest": longest,
        "starts_with": text[0],
        "ends_with": text[-1],
    }

