def score_compact_pattern(text: str, pattern: str) -> int:
    def tokenize(s: str):
        s = s.strip()
        if not s:
            return []
        return s.split()

    words = tokenize(text)
    tokens = tokenize(pattern)

    from functools import lru_cache

    n = len(words)
    m = len(tokens)

    @lru_cache(None)
    def dp(i, j):
        if j == m:
            return 0 if i == n else None
        tok = tokens[j]
        if tok == '?':
            if i >= n:
                return None
            rest = dp(i + 1, j + 1)
            return None if rest is None else 2 + rest
        if tok == '*':
            best = None
            for k in range(i, n + 1):
                rest = dp(k, j + 1)
                if rest is not None:
                    score = (k - i) + rest
                    if best is None or score > best:
                        best = score
            return best
        if i < n and words[i] == tok:
            rest = dp(i + 1, j + 1)
            return None if rest is None else 1 + rest
        return None

    ans = dp(0, 0)
    return -1 if ans is None else ans

def stable_group_sum(records):
    if not isinstance(records, list):
        raise TypeError('records must be a list')

    groups = {}
    order = []

    for item in records:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError('each record must be a 3-tuple')
        group_id, weight, label = item

        if not isinstance(group_id, int) or isinstance(group_id, bool):
            raise TypeError('group_id must be an int')
        if not isinstance(weight, (int, float)) or isinstance(weight, bool):
            raise TypeError('weight must be numeric')
        if not isinstance(label, str):
            raise TypeError('label must be a str')

        if group_id not in groups:
            groups[group_id] = [0, []]
            order.append(group_id)
        groups[group_id][0] += weight
        groups[group_id][1].append(label)

    result = []
    for group_id in sorted(order):
        total_weight, labels = groups[group_id]
        result.append((group_id, total_weight, labels))
    return result

from datetime import date


def _parse_iso_date(text):
    if not isinstance(text, str) or len(text) != 10:
        raise ValueError('invalid date')
    if text[4] != '-' or text[7] != '-':
        raise ValueError('invalid date')
    y = text[0:4]
    m = text[5:7]
    d = text[8:10]
    if not (y.isdigit() and m.isdigit() and d.isdigit()):
        raise ValueError('invalid date')
    try:
        return date(int(y), int(m), int(d))
    except ValueError:
        raise ValueError('invalid date')


