def summarize_runs(values):
    sentinel = object()
    runs = []
    prev = sentinel
    current_value = sentinel
    current_len = 0
    changes = 0
    seen = []

    for x in values:
        if type(x) is not int:
            raise TypeError('all elements must be integers')
        seen.append(x)
        if prev is sentinel:
            current_value = x
            current_len = 1
        elif x == current_value:
            current_len += 1
        else:
            runs.append((current_value, current_len))
            changes += 1
            current_value = x
            current_len = 1
        prev = x

    if prev is sentinel:
        return {'runs': [], 'longest_run': None, 'changes': 0, 'palindrome': True}

    runs.append((current_value, current_len))

    longest_run = runs[0]
    for run in runs[1:]:
        if run[1] > longest_run[1]:
            longest_run = run

    palindrome = seen == seen[::-1]
    return {'runs': runs, 'longest_run': longest_run, 'changes': changes, 'palindrome': palindrome}

def canonicalize_event_log(entries):
    result = []
    seen = set()

    for entry in entries:
        if not isinstance(entry, tuple):
            continue
        if len(entry) == 2:
            timestamp, label = entry
            metadata = {}
        elif len(entry) == 3:
            timestamp, label, metadata = entry
            if not isinstance(metadata, dict):
                continue
            metadata = dict(metadata)
        else:
            continue

        if type(timestamp) is bool or not isinstance(timestamp, int):
            continue
        if not isinstance(label, str):
            continue
        label = label.strip()
        if not label:
            continue

        tags = metadata.get("tags")
        if isinstance(tags, list):
            metadata["tags"] = tuple(tags)

        key = (timestamp, label)
        if key in seen:
            continue
        seen.add(key)
        result.append((timestamp, label, metadata))

    result.sort(key=lambda x: x[0])
    return result

def normalize_routing_table(entries):
    def parse_ip(ip):
        if not isinstance(ip, str):
            raise ValueError("IP must be a string")
        parts = ip.split('.')
        if len(parts) != 4:
            raise ValueError("Invalid IPv4 address")
        octets = []
        for part in parts:
            if part == '' or not part.isdigit():
                raise ValueError("Invalid IPv4 address")
            if len(part) > 1 and part[0] == '+':
                raise ValueError("Invalid IPv4 address")
            value = int(part)
            if value < 0 or value > 255:
                raise ValueError("Invalid IPv4 address")
            octets.append(str(value))
        return '.'.join(octets), tuple(int(x) for x in octets)

    if not isinstance(entries, list):
        raise ValueError("entries must be a list")

    best = {}
    for record in entries:
        if not (isinstance(record, tuple) and len(record) == 4):
            raise ValueError("Each record must be a 4-tuple")
        destination, prefix_length, gateway, metric = record
        dest_norm, dest_key = parse_ip(destination)
        if not isinstance(prefix_length, int) or isinstance(prefix_length, bool) or prefix_length < 0 or prefix_length > 32:
            raise ValueError("Invalid prefix length")
        if gateway is None:
            gw_norm = None
            gw_key = (-1,)
        else:
            gw_norm, gw_key = parse_ip(gateway)
        if not isinstance(metric, int) or isinstance(metric, bool) or metric < 0:
            raise ValueError("Invalid metric")
        key = (dest_norm, prefix_length, gw_norm)
        current = best.get(key)
        if current is None or metric < current[3]:
            best[key] = (dest_norm, prefix_length, gw_norm, metric, dest_key, gw_key)

    def sort_key(item):
        dest_norm, prefix_length, gw_norm, metric, dest_key, gw_key = item
        gw_sort = (0, ()) if gw_norm is None else (1, gw_key)
        return (dest_key, -prefix_length, gw_sort, metric)

    result = []
    for item in sorted(best.values(), key=sort_key):
        result.append((item[0], item[1], item[2], item[3]))
    return result

def compare_patch_counts(original: str, modified: str) -> dict:
    if not isinstance(original, str) or not isinstance(modified, str):
        raise TypeError("both arguments must be strings")

    o_lines = original.splitlines()
    m_lines = modified.splitlines()
    max_len = max(len(o_lines), len(m_lines))

    result = {"added": 0, "removed": 0, "changed": 0, "same": 0}
    for i in range(max_len):
        has_o = i < len(o_lines)
        has_m = i < len(m_lines)
        if has_o and has_m:
            if o_lines[i] == m_lines[i]:
                result["same"] += 1
            else:
                result["changed"] += 1
        elif has_m:
            result["added"] += 1
        else:
            result["removed"] += 1
    return result

