def normalize_dna_windows(seq, window_size):
    if not isinstance(seq, str):
        raise TypeError("seq must be a string")
    if not isinstance(window_size, int):
        raise TypeError("window_size must be an integer")
    if window_size <= 0:
        raise ValueError("window_size must be positive")

    seq = seq.upper()
    allowed = set("ACGTN")
    for ch in seq:
        if ch not in allowed:
            raise ValueError("seq contains invalid characters")

    result = []
    for i in range(0, len(seq) - len(seq) % window_size, window_size):
        window = seq[i:i + window_size]
        if window and all(ch == 'N' for ch in window):
            result.append('X' * window_size)
        else:
            result.append(window)
    return result

