def summarize_sign_blocks(nums):
    def category(x):
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("all elements must be integers")
        if x > 0:
            return "positive"
        if x < 0:
            return "negative"
        return "zero"

    it = iter(nums)
    try:
        first = next(it)
    except StopIteration:
        return {"blocks": [], "longest": None, "transitions": 0}

    first_cat = category(first)
    blocks = []
    current_cat = first_cat
    current_len = 1
    transitions = 0
    longest_cat = first_cat
    longest_len = 1

    for x in it:
        cat = category(x)
        if cat == current_cat:
            current_len += 1
        else:
            blocks.append((current_cat, current_len))
            transitions += 1
            if current_len > longest_len:
                longest_cat, longest_len = current_cat, current_len
            current_cat = cat
            current_len = 1
    blocks.append((current_cat, current_len))
    if current_len > longest_len:
        longest_cat, longest_len = current_cat, current_len

    return {"blocks": blocks, "longest": (longest_cat, longest_len), "transitions": transitions}

