        else:
            result.append((current_char, current_len))
            current_char = ch
            current_len = 1
    result.append((current_char, current_len))
    return result

def splice_runs(values):
    if not isinstance(values, list):
        raise TypeError('values must be a list of integers')
    result = []
    if not values:
        return result
    for x in values:
        if type(x) is not int:
            raise TypeError('values must be a list of integers')
    current = values[0]
    count = 1
    for x in values[1:]:
        if x == current:
            count += 1
        else:
            result.append([current, count])
            current = x
            count = 1
    result.append([current, count])
    return result

def canonicalize_path(path: str) -> str:
    if path == '':
        return '.'

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
        else:
            stack.append(part)

    if absolute:
        return '/' if not stack else '/' + '/'.join(stack)
    return '.' if not stack else '/'.join(stack)

def summarize_changes(records):
    totals = {}
    for record in records:
        if not isinstance(record, tuple) or len(record) != 3:
            raise TypeError("each record must be a 3-item tuple")
        user_id, action, value = record
        if not isinstance(user_id, str):
            raise ValueError("user_id must be a string")
        if action not in ("add", "subtract"):
            raise ValueError("invalid action")
        if type(value) is not int or value < 0:
            raise ValueError("value must be a non-negative integer")
        delta = value if action == "add" else -value
        totals[user_id] = totals.get(user_id, 0) + delta
    return sorted(totals.items(), key=lambda item: (-item[1], item[0]))

def normalize_menu(menu):
    result = []
    for record in menu:
        try:
            if len(record) != 3:
                raise ValueError
        except TypeError:
            raise ValueError
        name, price, tags = record
        if not isinstance(name, str):
            raise ValueError
        try:
            price_value = float(price)
        except (TypeError, ValueError):
            raise ValueError
        try:
            tag_iter = iter(tags)
        except TypeError:
            raise ValueError
        if price_value < 0:
            continue
        seen = set()
        norm_tags = []
        for tag in tag_iter:
            if not isinstance(tag, str):
                raise ValueError
            t = tag.strip().lower()
            if t and t not in seen:
                seen.add(t)
                norm_tags.append(t)
        result.append({"name": name.strip().lower(), "price": round(price_value, 2), "tags": tuple(norm_tags)})
    return result

from math import gcd

def normalized_segment_signature(points):
    pts = list(points)
    if len(pts) < 2:
        return ()

    cleaned = [pts[0]]
    for p in pts[1:]:
        if not (isinstance(p, (tuple, list)) and len(p) == 2 and isinstance(p[0], int) and isinstance(p[1], int)):
            raise TypeError("each point must be a 2-item sequence of integers")
        if not (isinstance(cleaned[-1], (tuple, list)) and len(cleaned[-1]) == 2 and isinstance(cleaned[-1][0], int) and isinstance(cleaned[-1][1], int)):
            raise TypeError("each point must be a 2-item sequence of integers")
        if p[0] != cleaned[-1][0] or p[1] != cleaned[-1][1]:
            cleaned.append(p)

    first = cleaned[0]
    if not (isinstance(first, (tuple, list)) and len(first) == 2 and isinstance(first[0], int) and isinstance(first[1], int)):
        raise TypeError("each point must be a 2-item sequence of integers")

    if len(cleaned) < 2:
        return ()

    signature = []
    prev = cleaned[0]
    for curr in cleaned[1:]:
        dx = curr[0] - prev[0]
        dy = curr[1] - prev[1]
        g = gcd(abs(dx), abs(dy))
        signature.append((dx // g, dy // g))
        prev = curr
    return tuple(signature)

def normalize_nested_paths(data):
    def normalize_string(s):
        if s.startswith('~/'):
            s = '/home/user/' + s[2:]
        elif s.startswith('./'):
            s = s[2:]
        elif s.startswith('../'):
            s = s[3:]

        while '//' in s:
            s = s.replace('//', '/')

        if s == '':
            return '.'
        return s

    def walk(x):
        if isinstance(x, str):
            return normalize_string(x)
        if isinstance(x, bool) or x is None or isinstance(x, int):
            return x
        if isinstance(x, list):
            return [walk(v) for v in x]
        if isinstance(x, tuple):
            return tuple(walk(v) for v in x)
        if isinstance(x, dict):
            return {k: walk(v) for k, v in x.items()}
        raise TypeError('Unsupported type')

    return walk(data)

def normalize_catalog_record(record):
