def normalize_selector(selector: str) -> str:
    def valid_ident(name: str) -> bool:
        return bool(name) and all(ch.isalnum() or ch == '_' for ch in name)

    if selector.strip() == '':
        return ''

    out = []
    for token in selector.split():
        if token.count('.') > 1 or token.count('#') > 1:
            raise ValueError('multiple markers in token')

        elem = ''
        cls = ''
        ident = ''

        first_dot = token.find('.') if '.' in token else len(token)
        first_hash = token.find('#') if '#' in token else len(token)
        cut = min(first_dot, first_hash)
        if cut != len(token):
            elem = token[:cut]
            rest = token[cut:]
        else:
            elem = token
            rest = ''

        if elem and not elem.isalpha():
            raise ValueError('invalid element name')

        if rest:
            if rest[0] == '#':
                rest = rest[1:]
                if not rest:
                    raise ValueError('empty id')
                j = rest.find('.')
                if j == -1:
                    ident = rest
                    rest = ''
                else:
                    ident = rest[:j]
                    rest = rest[j:]
            elif rest[0] == '.':
                rest = rest[1:]
                if not rest:
                    raise ValueError('empty class')
                j = rest.find('#')
                if j == -1:
                    cls = rest
                    rest = ''
                else:
                    cls = rest[:j]
                    rest = rest[j:]
            else:
                raise ValueError('invalid token')

            if rest:
                if rest[0] == '#':
                    if ident:
                        raise ValueError('multiple ids')
                    rest = rest[1:]
                    if not rest:
                        raise ValueError('empty id')
                    j = rest.find('.')
                    if j != -1:
                        raise ValueError('too many markers')
                    ident = rest
                    rest = ''
                elif rest[0] == '.':
                    if cls:
                        raise ValueError('multiple classes')
                    rest = rest[1:]
                    if not rest:
                        raise ValueError('empty class')
                    j = rest.find('#')
                    if j != -1:
                        raise ValueError('too many markers')
                    cls = rest
                    rest = ''

        if ident and not valid_ident(ident):
            raise ValueError('invalid id')
        if cls and not valid_ident(cls):
            raise ValueError('invalid class')

        normalized = elem
        if ident:
            normalized += '#' + ident
        if cls:
            normalized += '.' + cls
        out.append(normalized)

    return ' '.join(out)

def flatten_and_sum(data):
    def walk(x):
        if isinstance(x, bool):
            raise TypeError('unsupported type: bool')
        if isinstance(x, (int, float)):
            return x
        if isinstance(x, list) or isinstance(x, tuple):
            total = 0
            for item in x:
                total += walk(item)
            return total
        if isinstance(x, dict):
            total = 0
            for key in x:
                total += walk(x[key])
            return total
        raise TypeError(f'unsupported type: {type(x).__name__}')

    if not isinstance(data, (list, tuple, dict)):
        raise TypeError(f'unsupported type: {type(data).__name__}')
    return walk(data)

