def merge_ranges(ranges):
    try:
        items = list(ranges)
    except TypeError:
        raise TypeError("ranges must be an iterable of 2-item iterables")

    normalized = []
    for item in items:
        try:
            a, b = item
        except Exception:
            raise ValueError("each interval must contain exactly two values")
        if a > b:
            raise ValueError("interval start must be <= end")
        normalized.append((a, b))

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged

def extract_grouped_records(text: str) -> dict[str, list[str]]:
    result = {}
    if text == "":
        return result
    for line in text.split("\n"):
        if line.strip() == "":
            continue
        if line.count("=") != 1:
            raise ValueError("Each non-empty line must contain exactly one '='")
        key_part, value_part = line.split("=", 1)
        key = key_part.strip()
        value = value_part.strip()
        if key == "":
            raise ValueError("Key cannot be empty")
        if key not in result:
            result[key] = []
        result[key].append(value)
    return result

def compress_integer_runs(data):
    if isinstance(data, (str, bytes, bytearray)):
        raise TypeError("data must be a sequence of integers")
    try:
        iterator = iter(data)
    except TypeError:
        raise TypeError("data must be a sequence of integers")

    result = []
    sentinel = object()
    current_value = sentinel
    count = 0
    seen_any = False

    for item in iterator:
        seen_any = True
        if not isinstance(item, int) or isinstance(item, bool):
            raise TypeError("data must be a sequence of integers")
        if current_value is sentinel:
            current_value = item
