def normalize_ledger(entries):
    def is_leap(year):
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def valid_date(date_str):
        parts = date_str.split('-')
        if len(parts) != 3:
            return False
        y_s, m_s, d_s = parts
        if len(y_s) != 4 or len(m_s) != 2 or len(d_s) != 2 or not (y_s.isdigit() and m_s.isdigit() and d_s.isdigit()):
            return False
        year = int(y_s)
        month = int(m_s)
        day = int(d_s)
        if not (2000 <= year <= 2099):
            return False
        if not (1 <= month <= 12):
            return False
        days_in_month = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return 1 <= day <= days_in_month[month - 1]

    def valid_amount(amount_str):
        if amount_str == '':
            return False
        if amount_str[0] in '+-':
            digits = amount_str[1:]
            if digits == '':
                return False
            return digits.isdigit()
        return amount_str.isdigit()

    normalized = []
    for entry in entries:
        parts = entry.split('|', 2)
        if len(parts) != 3:
            raise ValueError('invalid entry')
        date_part = parts[0].strip()
        amount_part = parts[1].strip()
        desc_part = parts[2].strip()
        if not valid_date(date_part):
            raise ValueError('invalid entry')
        if not valid_amount(amount_part):
            raise ValueError('invalid entry')
        normalized.append(f'{date_part} | {str(int(amount_part))} | {desc_part}')
    return normalized

