def summarize_moves(moves):
    x = 0
    y = 0
    min_x = 0
    min_y = 0
    max_x = 0
    max_y = 0
    visited = {(0, 0)}
    invalid_count = 0

    def apply(direction, steps):
        nonlocal x, y, min_x, min_y, max_x, max_y
        for _ in range(steps):
            if direction == 'N':
                y += 1
            elif direction == 'S':
                y -= 1
            elif direction == 'E':
                x += 1
            else:
                x -= 1
            visited.add((x, y))
            if x < min_x:
                min_x = x
            if y < min_y:
                min_y = y
            if x > max_x:
                max_x = x
            if y > max_y:
                max_y = y

    for move in moves:
        if not isinstance(move, str) or len(move) < 2:
            invalid_count += 1
            continue
        direction = move[0]
        steps_text = move[1:]
        if direction not in {'N', 'S', 'E', 'W'} or not steps_text.isdigit():
            invalid_count += 1
            continue
        steps = int(steps_text)
        apply(direction, steps)

    return {
        'final_position': (x, y),
        'bounding_box': (min_x, min_y, max_x, max_y),
        'invalid_count': invalid_count,
        'visited_count': len(visited),
    }

