def best_window_sum(values, k):
    if not isinstance(k, int):
        raise TypeError("k must be an integer")
    if k < 1:
        raise ValueError("k must be at least 1")

    vals = list(values)
    n = len(vals)
    if k > n:
        return None

    window_sum = sum(vals[:k])
    best = window_sum
    for i in range(k, n):
        window_sum += vals[i] - vals[i - k]
        if window_sum > best:
            best = window_sum
    return best

