def normalize_inventory(records):
    if not isinstance(records, list):
        raise ValueError("records must be a list")

    merged = {}
    for record in records:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("each record must be a tuple of length 3")
        product_code, quantity, price = record
        if not isinstance(product_code, str):
            raise ValueError("product_code must be a string")
        if not isinstance(quantity, int):
            raise ValueError("quantity must be an integer")
        if not isinstance(price, (int, float)):
            raise ValueError("price must be a number")

        code = product_code.strip().upper()
        if code == "":
            continue

        if code not in merged:
            merged[code] = [0, 0.0]
        merged[code][0] += quantity
        merged[code][1] += quantity * float(price)

    result = []
    for code in sorted(merged):
        total_qty, total_weighted = merged[code]
        if total_qty == 0:
            avg_price = 0.0
        else:
            avg_price = round(total_weighted / total_qty, 2)
        result.append((code, total_qty, avg_price))
    return result

def summarize_variant_lanes(variants):
    if not isinstance(variants, list):
        raise TypeError("variants must be a list")

    result = {}
    for record in variants:
        if not isinstance(record, tuple) or len(record) != 3:
            raise TypeError("each record must be a 3-tuple")
        lane, variant_id, enabled = record

        if not isinstance(lane, str):
            raise TypeError("lane must be a string")
        if lane == "":
            raise ValueError("lane must not be empty")
        if type(variant_id) is not int:
            raise TypeError("variant_id must be an int")
        if not isinstance(enabled, bool):
            raise TypeError("enabled must be a bool")

        if lane not in result:
            result[lane] = {"count": 0, "enabled_count": 0, "variant_ids": set()}

        summary = result[lane]
        summary["count"] += 1
        if enabled:
            summary["enabled_count"] += 1
        summary["variant_ids"].add(variant_id)

    for lane in result:
        result[lane] = {
            "count": result[lane]["count"],
            "enabled_count": result[lane]["enabled_count"],
            "variant_ids": sorted(result[lane]["variant_ids"]),
        }
    return result

