def normalize_event_schedule(events):
    valid = []
    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 4:
            continue
        day, start, end, label = rec
        if not isinstance(day, str) or not day:
            continue
        if not isinstance(label, str) or not label:
            continue
        if not isinstance(start, int) or not isinstance(end, int):
            continue
        if start >= end:
            continue
        valid.append((day, start, end, label))

    by_day = {}
    for day, start, end, label in valid:
        by_day.setdefault(day, []).append((start, end, label))

    result = []
    for day in sorted(by_day):
        intervals = sorted(by_day[day], key=lambda x: (x[0], x[1], x[2]))
        merged = []
        for start, end, label in intervals:
            if not merged:
                merged.append([start, end, label])
                continue
            ps, pe, pl = merged[-1]
            if label == pl and start <= pe:
                merged[-1][1] = max(pe, end)
            else:
                merged.append([start, end, label])
        result.append((day, [(s, e, l) for s, e, l in merged]))
    return result

def normalize_router_rules(rules):
    import re

    allowed_methods = {"GET", "POST", "PUT", "DELETE", "PATCH"}
    target_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    unreserved = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")

    def decode_path(path):
        res = []
        i = 0
        n = len(path)
        while i < n:
            ch = path[i]
            if ch == '%' and i + 2 < n and all(c in '0123456789ABCDEFabcdef' for c in path[i+1:i+3]):
                byte = int(path[i+1:i+3], 16)
                c = chr(byte)
                if c in unreserved:
                    res.append(c)
                else:
                    res.append('%' + path[i+1:i+3].upper())
                i += 3
            else:
                res.append(ch)
                i += 1
        return ''.join(res)

    def normalize_path(path):
        if not path:
            raise ValueError('empty path')
        absolute = path.startswith('/')
        path = decode_path(path)
        parts = [p for p in path.split('/') if p != '']
        stack = []
        for part in parts:
            if part == '.':
                continue
            if part == '..':
                if stack and stack[-1] != '..':
                    stack.pop()
                else:
                    if absolute:
                        raise ValueError('path escapes root')
                    stack.append('..')
            else:
                stack.append(part)
        if absolute:
            norm = '/' + '/'.join(stack)
            return '/' if norm == '' else norm
        else:
            norm = '/'.join(stack)
            return norm or '.'

    out = []
    seen = set()
    for rule in rules:
        if not isinstance(rule, str):
            raise ValueError('rule must be string')
        if '->' in rule:
            left, right = rule.split('->', 1)
            target = right.strip()
            if not target_re.match(target):
                raise ValueError('invalid target')
        else:
            left = rule
            target = None
        left = left.strip()
        if not left:
            raise ValueError('empty rule')
        parts = left.split(None, 1)
        if len(parts) != 2:
            raise ValueError('missing path')
        method, path = parts[0].upper(), parts[1].strip()
        if method not in allowed_methods:
            raise ValueError('invalid method')
        norm_path = normalize_path(path)
        normalized = f'{method} {norm_path}'
        if target is not None:
            normalized += f' -> {target}'
        if normalized not in seen:
            seen.add(normalized)
            out.append(normalized)
    return out

def normalize_chat_threads(threads):
    if not isinstance(threads, list):
        raise TypeError('threads must be a list')

    topic_data = {}
    thread_count = 0
    total_messages = 0
    total_read = 0

    for thread in threads:
        if not isinstance(thread, dict) or set(thread.keys()) != {'topic', 'messages'}:
            continue
        topic = thread['topic']
        messages = thread['messages']
        if not isinstance(topic, str) or not isinstance(messages, list):
            continue

        thread_count += 1
        entry = topic_data.setdefault(topic, {'message_count': 0, 'read_count': 0, 'senders': set()})

        for message in messages:
            if not isinstance(message, dict) or set(message.keys()) != {'sender', 'text', 'read'}:
                continue
            sender = message['sender']
            text = message['text']
            read = message['read']
            if not isinstance(sender, str) or not isinstance(text, str) or not isinstance(read, bool):
                continue

            entry['message_count'] += 1
            if read:
                entry['read_count'] += 1
            entry['senders'].add(sender)
            total_messages += 1
            if read:
                total_read += 1

    topics = []
    for topic in sorted(topic_data):
        entry = topic_data[topic]
        topics.append({
            'topic': topic,
            'message_count': entry['message_count'],
            'read_count': entry['read_count'],
            'senders': sorted(entry['senders']),
        })

    return {
        'topics': topics,
        'totals': {
            'thread_count': thread_count,
            'message_count': total_messages,
            'read_count': total_read,
            'topic_count': len(topic_data),
        }
    }

