def decode_rle_segments(encoded):
    if encoded == "":
        return []
    if not isinstance(encoded, str):
        raise ValueError("encoded must be a string")
    parts = encoded.split("|")
    if any(part == "" for part in parts):
        raise ValueError("empty segment")
    result = []
    for part in parts:
        if ":" not in part:
            raise ValueError("missing colon")
        count_text, char = part.split(":", 1)
        if count_text == "" or char == "":
            raise ValueError("malformed segment")
        if count_text.startswith("-") or not count_text.isdigit():
            raise ValueError("invalid count")
        if len(char) != 1:
            raise ValueError("segment must contain exactly one character")
        count = int(count_text)
        result.append(char * count)
    return result

def compress_ranges(values):
    if not isinstance(values, list):
        raise TypeError('values must be a list')
