        if not isinstance(x, int):
            raise TypeError('all elements must be integers')
    if not values:
        return []
    nums = sorted(set(values))
    ranges = []
    start = end = nums[0]
    for n in nums[1:]:
        if n == end + 1:
            end = n
        else:
            ranges.append((start, end))
            start = end = n
    ranges.append((start, end))
    return ranges

