def normalize_route(steps):
    if not isinstance(steps, list):
        raise TypeError('steps must be a list')

    allowed = {'N', 'S', 'E', 'W', 'U', 'D'}
    counts = {'N': 0, 'S': 0, 'E': 0, 'W': 0, 'U': 0, 'D': 0}

    for step in steps:
        if isinstance(step, str):
            if step not in allowed:
                raise ValueError('invalid direction')
            counts[step] += 1
        elif isinstance(step, tuple):
            if len(step) != 2:
                raise ValueError('tuple step must have length 2')
            label, count = step
            if label not in allowed:
                raise ValueError('invalid direction')
            if not isinstance(count, int):
                raise ValueError('count must be an integer')
            if count < 0:
                raise ValueError('count must be non-negative')
            counts[label] += count
        else:
            raise TypeError('invalid step type')

    result_counts = {
        'N': max(counts['N'] - counts['S'], 0),
        'S': max(counts['S'] - counts['N'], 0),
        'E': max(counts['E'] - counts['W'], 0),
        'W': max(counts['W'] - counts['E'], 0),
        'U': max(counts['U'] - counts['D'], 0),
        'D': max(counts['D'] - counts['U'], 0),
    }

    parts = []
    for direction in ['N', 'S', 'E', 'W', 'U', 'D']:
        parts.extend([direction] * result_counts[direction])
    return '>'.join(parts)

def flatten_headers(headers, joiner):
    if not isinstance(joiner, str):
        raise ValueError('joiner must be a string')
    if not isinstance(headers, list) or len(headers) == 0:
        raise ValueError('headers must be a non-empty list')
    max_len = 0
    for row in headers:
        if not isinstance(row, list):
            raise ValueError('each row must be a list')
        if len(row) > max_len:
            max_len = len(row)
        for cell in row:
            if not isinstance(cell, str):
                raise ValueError('all cells must be strings')
    result = []
    for col in range(max_len):
        parts = []
        for row in headers:
            if col < len(row):
                cell = row[col]
                if cell != '':
                    parts.append(cell)
        result.append(joiner.join(parts) if parts else '')
    return result

def canonical_compose(commands):
