def normalize_schedule(events):
    if not events:
        return {}

    grouped = {}
    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 3:
            continue
        start, end, label = rec
        if not isinstance(start, int) or not isinstance(end, int) or not isinstance(label, str):
            continue
        if start >= end:
            continue
        grouped.setdefault(label, []).append((start, end))

    result = {}
    for label in sorted(grouped):
        intervals = sorted(grouped[label])
        merged = []
        cur_start, cur_end = intervals[0]
        for s, e in intervals[1:]:
            if s <= cur_end:
                if e > cur_end:
                    cur_end = e
            else:
                merged.append((cur_start, cur_end))
                cur_start, cur_end = s, e
        merged.append((cur_start, cur_end))
        result[label] = merged
    return result

def normalize_task_spans(spans, limit):
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError("limit must be a non-negative integer")

    if spans is None:
        raise ValueError("spans must be a list of intervals")

    normalized = []
    for interval in spans:
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            raise ValueError("each interval must contain exactly two integers")
        start, end = interval
        if not isinstance(start, int) or isinstance(start, bool) or not isinstance(end, int) or isinstance(end, bool):
            raise ValueError("interval endpoints must be integers")
        if start > end:
            raise ValueError("interval start must be <= end")
        if start < 0 or end < 0 or start > limit or end > limit:
            raise ValueError("interval endpoints must be within [0, limit]")
        normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def normalize_patch_stack(stack):
    if not isinstance(stack, list):
        raise TypeError('stack must be a list')

    normalized = []

    for record in stack:
        if not isinstance(record, list):
            raise TypeError('each record must be a list')
        if len(record) != 3:
            raise ValueError('each record must have exactly 3 elements')

        op, start, end = record

        if not isinstance(op, str):
            raise TypeError('op must be a string')
        if op not in ('add', 'remove'):
            raise ValueError('op must be add or remove')
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('start and end must be integers')
        if start >= end:
            raise ValueError('start must be less than end')

        current = [op, start, end]
        if normalized and normalized[-1][0] == op and normalized[-1][2] == start:
            normalized[-1][2] = end
        else:
            normalized.append(current)

    for prev, nxt in zip(normalized, normalized[1:]):
        if nxt[1] < prev[2]:
            raise ValueError('overlapping intervals are not allowed')

    return normalized

