def normalize_betting_slip(slip):
    if not isinstance(slip, list):
        raise TypeError("slip must be a list")

    def normalize_name(name):
        if not isinstance(name, str):
            raise ValueError("name must be a string")
        stripped = name.strip()
        if not stripped:
            raise ValueError("name must be non-empty")
        return " ".join(stripped.split())

    def normalize_odds(odds):
        if isinstance(odds, bool):
            raise ValueError("odds must be a positive integer")
        if isinstance(odds, int):
            if odds <= 0:
                raise ValueError("odds must be positive")
            return odds
        if isinstance(odds, str) and odds.isdigit():
            value = int(odds)
            if value <= 0:
                raise ValueError("odds must be positive")
            return value
        raise ValueError("unsupported odds type")

    seen = set()
    entries = []
    total = 0

    for entry in slip:
        if isinstance(entry, dict):
            if set(entry.keys()) != {"name", "odds"}:
                raise ValueError("invalid entry dict")
            name = entry["name"]
            odds = entry["odds"]
        elif isinstance(entry, (tuple, list)) and len(entry) == 2:
            name, odds = entry
        else:
            raise ValueError("invalid entry format")

        normalized_name = normalize_name(name)
        normalized_odds = normalize_odds(odds)

        if normalized_name in seen:
            continue
        seen.add(normalized_name)
        entries.append((normalized_name, normalized_odds))
        total += normalized_odds

    return total, entries

