import math


def normalize_nested_numbers(data):
    if isinstance(data, bool):
        return data
    if isinstance(data, int):
        return data
    if isinstance(data, float):
        if math.isfinite(data) and data.is_integer():
            return int(data)
        return data
    if isinstance(data, str):
        s = data.strip()
        if s == "":
            return data
        try:
            n = int(s, 10)
            return n
        except Exception:
            pass
        try:
            f = float(s)
            if math.isfinite(f) and f.is_integer():
                return int(f)
            return f
        except Exception:
            return data
    if isinstance(data, list):
        return [normalize_nested_numbers(x) for x in data]
    if isinstance(data, tuple):
        return tuple(normalize_nested_numbers(x) for x in data)
    if isinstance(data, set):
        return {normalize_nested_numbers(x) for x in data}
    if isinstance(data, dict):
        return {k: normalize_nested_numbers(v) for k, v in data.items()}
    return data

def normalize_record(record):
    if not isinstance(record, dict):
        # Support dictionary-like objects via key access, but require mapping-style behavior.
        pass

    name = record['name']
    age = record['age']
    tags = record['tags']

    if not isinstance(name, str):
        raise TypeError('name must be a string')
    normalized_name = ' '.join(name.split())
    if normalized_name == '':
        raise ValueError('name cannot be empty')

    if isinstance(age, int) and not isinstance(age, bool):
        normalized_age = age
    elif isinstance(age, str):
        s = age.strip()
        if s == '':
            raise ValueError('invalid age')
        try:
            normalized_age = int(s)
        except Exception:
            raise ValueError('invalid age')
    else:
        raise ValueError('invalid age')
    if normalized_age < 0:
        raise ValueError('age must be non-negative')

    try:
        iterator = iter(tags)
    except TypeError:
        raise TypeError('tags must be iterable')

    seen = set()
    normalized_tags = []
    for tag in iterator:
        if not isinstance(tag, str):
            raise TypeError('all tags must be strings')
        cleaned = tag.strip()
        if cleaned == '':
            continue
        if cleaned not in seen:
            seen.add(cleaned)
            normalized_tags.append(cleaned)

    return {'name': normalized_name, 'age': normalized_age, 'tags': normalized_tags}

