def normalize_course_prerequisites(prerequisites):
    if not isinstance(prerequisites, list):
        raise TypeError('prerequisites must be a list')

    normalized = []
    seen = set()

    for item in prerequisites:
        if not isinstance(item, str):
            raise TypeError('each prerequisite must be a string')

        stripped = item.strip()
        if not stripped:
            continue

        parts = [part.strip() for part in stripped.split('>')]
        chain = []
        used = set()
        for part in parts:
            if not part:
                continue
            if part in used:
                continue
            used.add(part)
            chain.append(part)

        if not chain:
            continue

        tup = tuple(chain)
        if tup in seen:
            continue
        seen.add(tup)
        normalized.append(tup)

    normalized.sort()
    return normalized

def compress_ranges(nums):
    unique = sorted(set(nums))
    if not unique:
        return []
    result = []
    start = prev = unique[0]
    for x in unique[1:]:
        if x == prev + 1:
            prev = x
        else:
