def condense_path(path: str) -> str:
    if path == "":
        return "/"

    parts = path.split("/")
    stack = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            continue
        stack.append(part)

    return "/" + "/".join(stack) if stack else "/"

def plan_stair_tokens(n, tokens):
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return []

    valid = []
    for t in tokens:
        if isinstance(t, int) and t > 0:
            valid.append(t)

    valid.sort()
    m = len(valid)
    if m == 0:
        return []

    best = None

    def better(a, b):
        if b is None:
            return True
        if len(a) != len(b):
            return len(a) < len(b)
        return a < b

    def backtrack(i, remaining, chosen):
        nonlocal best
        if remaining == 0:
            candidate = chosen.copy()
            if better(candidate, best):
                best = candidate
            return
        if remaining < 0 or i == m:
            return
        if best is not None and len(chosen) >= len(best):
            return

        # include current token
        chosen.append(valid[i])
        backtrack(i + 1, remaining - valid[i], chosen)
        chosen.pop()

        # skip current token
        backtrack(i + 1, remaining, chosen)

    backtrack(0, n, [])
    return best if best is not None else []

def ranked_merge(left, right):
    if not hasattr(left, "__len__") or not hasattr(left, "__getitem__"):
        raise TypeError("left must be a finite sequence")
    if not hasattr(right, "__len__") or not hasattr(right, "__getitem__"):
        raise TypeError("right must be a finite sequence")

    i = j = 0
    n, m = len(left), len(right)
    result = []

    while i < n and j < m:
        a = left[i]
        b = right[j]
        try:
            if a <= b:
                result.append(a)
                i += 1
            else:
                result.append(b)
                j += 1
        except TypeError:
            raise TypeError("elements are not comparable")

    while i < n:
        result.append(left[i])
        i += 1
    while j < m:
        result.append(right[j])
        j += 1

    return result

def parse_duration_words(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    stripped = text.strip()
    if not stripped:
        raise ValueError("empty input")

    units = {
        "second": 1,
        "seconds": 1,
        "minute": 60,
        "minutes": 60,
        "hour": 3600,
        "hours": 3600,
        "day": 86400,
        "days": 86400,
    }

    parts = stripped.split()
    if len(parts) % 2 != 0:
        raise ValueError("malformed duration")

    total = 0
    i = 0
    while i < len(parts):
        num_s = parts[i]
        unit_s = parts[i + 1]

        if num_s.startswith('-'):
            raise ValueError("negative numbers are not allowed")
        if num_s.startswith('+'):
            num_s = num_s[1:]
        if not num_s or not num_s.isdigit():
            raise ValueError("invalid number")

        unit_key = unit_s.lower()
        if unit_key not in units:
            raise ValueError("unknown unit")

        total += int(num_s) * units[unit_key]
        i += 2

    return total

def normalize_inventory_log(records):
    result = []
    for record in records:
        if not isinstance(record, str):
            raise ValueError('malformed record')
        parts = record.split('|')
        if len(parts) != 3:
            raise ValueError('malformed record')
        item, action, qty = (p.strip() for p in parts)
        if not item or not action or not qty:
            raise ValueError('malformed record')
        action_l = action.lower()
        if action_l not in {'add', 'remove', 'adjust'}:
            raise ValueError('malformed record')
        try:
            n = int(qty)
        except Exception:
            raise ValueError('malformed record')
        if action_l == 'remove':
            n = -abs(n)
        result.append(f'{item.lower()}:{action_l}:{n}')
    return result

def parse_weighted_pairs(text):
    if text == "":
        return []
    parts = text.split(';')
    result = []
    for part in parts:
        if part == "":
            raise ValueError("empty entry")
        if part != part.strip():
            raise ValueError("whitespace around entry")
        if ':' not in part or '@' not in part:
            raise ValueError("missing separator")
        left, rest = part.split(':', 1)
        right, weight_str = rest.rsplit('@', 1)
        if left == "" or right == "" or weight_str == "":
            raise ValueError("empty token")
        if any(ch in left for ch in ':@;') or any(ch in right for ch in ':@;'):
            raise ValueError("invalid token")
        if left != left.strip() or right != right.strip() or weight_str != weight_str.strip():
            raise ValueError("embedded whitespace")
        try:
            weight = int(weight_str, 10)
        except Exception as e:
            raise ValueError("invalid weight") from e
        result.append((left, right, weight))
    result.sort(key=lambda t: (-t[2], t[0], t[1]))
    return result

