def normalize_budget_allocations(budgets, target_total):
    if not budgets:
        raise ValueError("budgets must not be empty")
    if not isinstance(target_total, int) or target_total < 0:
        raise ValueError("target_total must be a non-negative integer")

    vals = []
    for x in budgets:
        if not isinstance(x, int) or x < 0:
            raise ValueError("budgets must contain only non-negative integers")
        vals.append(x)

    n = len(vals)
    current = sum(vals)
    if current == target_total:
        return vals[:]

    if current < target_total:
        extra = target_total - current
        base = vals[:]
        for i in range(n):
            if extra == 0:
                break
            base[i] += 1
            extra -= 1
        if extra:
            # Distribute remaining one by one in a round-robin manner, preserving lexicographic minimality.
            i = 0
            while extra > 0:
                base[i % n] += 1
                extra -= 1
                i += 1
        return base

    # current > target_total: reduce while keeping numbers non-negative and lexicographically smallest
    deficit = current - target_total
    out = vals[:]
    for i in range(n):
        if deficit == 0:
            break
        dec = min(out[i], deficit)
        out[i] -= dec
        deficit -= dec
    return out

