def summarize_sticker_batch(records):
    if records == []:
        return "EMPTY"

    packs = 0
    units = 0
    revenue = 0
    promo_packs = 0
    names = set()

    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 4:
            raise ValueError("each record must be a tuple of length 4")

        pack_name, count, price_cents, promo = rec

        if not isinstance(pack_name, str):
