        raise TypeError('text must be a string')
    s = text.strip().lower()
    s = re.sub(r'\s+', '-', s)
    s = re.sub(r'[^a-z0-9-]', '', s)
    s = re.sub(r'-+', '-', s)
    return s.strip('-')

def compress_intervals(points):
    if not isinstance(points, list):
        raise TypeError("points must be a list")
    for p in points:
        if not isinstance(p, int):
            raise TypeError("all points must be integers")
    if not points:
        return []
    uniq = sorted(set(points))
    intervals = []
    start = prev = uniq[0]
    for x in uniq[1:]:
        if x == prev + 1:
            prev = x
        else:
            intervals.append((start, prev))
            start = prev = x
    intervals.append((start, prev))
    return intervals

def normalize_room_label(label):
    if not isinstance(label, str):
        raise TypeError('label must be a string')
    s = label.strip()
    if s == '':
        raise ValueError('normalized label is empty')
    out = []
    prev_space = False
    for ch in s:
        if ch.isspace():
            if not prev_space:
                out.append('_')
                prev_space = True
            continue
        prev_space = False
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch in '_-':
            out.append(ch.upper())
    result = ''.join(out)
    if result == '':
        raise ValueError('normalized label is empty')
    return result

def normalize_path(path: str) -> str:
    if path == '':
        return '.'

    is_absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                if is_absolute:
                    stack.pop()
                else:
                    stack.pop()
            else:
                if not is_absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if is_absolute:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'

def normalize_identifier_path(s):
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    parts = []
    for segment in s.split('/'):
        trimmed = segment.strip()
        if trimmed:
            parts.append(trimmed.lower())
    return '/'.join(parts)

def normalize_invoice_lines(lines):
    result = []
    for line in lines:
        if line.strip() == "":
            continue
        parts = [p.strip() for p in line.split("|")]
        if len(parts) not in (3, 4):
            raise ValueError("Each non-empty line must have 3 or 4 pipe-separated fields")
        sku = parts[0].upper()
        try:
            quantity = int(parts[1])
        except Exception:
            raise ValueError("Invalid quantity")
        try:
            unit_price = float(parts[2])
        except Exception:
            raise ValueError("Invalid unit_price")
        description = parts[3] if len(parts) == 4 else ""
        result.append({"sku": sku, "quantity": quantity, "unit_price": unit_price, "description": description})
    return result

def repair_timeline(events):
    best = {}
    order = {}
    for idx, rec in enumerate(events):
        if not isinstance(rec, (tuple, list)) or len(rec) != 2:
            continue
        label, minute = rec
        if not isinstance(label, str) or label == "":
            continue
        if not isinstance(minute, int) or isinstance(minute, bool) or minute < 0:
            continue
        if label not in best:
            best[label] = minute
            order[label] = idx
        else:
            if minute < best[label]:
                best[label] = minute
                order[label] = idx
            elif minute == best[label] and idx < order[label]:
                order[label] = idx
    survivors = [(m, lbl) for lbl, m in best.items()]
    survivors.sort(key=lambda x: (x[0], x[1]))
    return ";".join(f"{lbl}@{m}" for m, lbl in survivors)

def parse_weighted_pairs(text: str) -> dict[str, int]:
    if text is None:
        raise TypeError('text must be a string')
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    result: dict[str, int] = {}
    if text.strip() == '':
        return result

    items = text.split(';')
    for raw_item in items:
        item = raw_item.strip()
        if item == '':
            continue
        if '=' not in item:
            raise ValueError('malformed item')
        key, weight = item.split('=', 1)
        if key == '' or weight == '':
            raise ValueError('malformed item')
        if key.strip() != key or weight.strip() != weight:
            raise ValueError('malformed item')
        if any(ch not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-' for ch in key):
            raise ValueError('malformed item')
        if weight[0] in '+-':
            digits = weight[1:]
            if digits == '':
                raise ValueError('malformed item')
        else:
            digits = weight
        if not digits.isdigit():
            raise ValueError('malformed item')
        value = int(weight)
        result[key] = result.get(key, 0) + value
    return result

