def merge_account_events(events):
    valid_actions = ('deposit', 'transfer_in', 'transfer_out', 'withdraw')
    action_delta = {
        'deposit': 1,
        'transfer_in': 1,
        'transfer_out': -1,
        'withdraw': -1,
    }
    per_account = {}

    for event in events:
        if not isinstance(event, (tuple, list)) or len(event) != 3:
            continue
        account_id, action, amount = event
        if not isinstance(account_id, str) or account_id == '':
            continue
        if action not in action_delta:
            continue
        if not isinstance(amount, int) or amount < 0:
            continue

        entry = per_account.setdefault(account_id, {'net': 0, 'count': 0, '_actions': {}})
        entry['net'] += action_delta[action] * amount
        entry['count'] += 1
        entry['_actions'][action] = entry['_actions'].get(action, 0) + 1

    if not per_account:
        return {}

    result = {}
    for account_id in sorted(per_account):
        entry = per_account[account_id]
        actions = entry['_actions']
        result[account_id] = {
            'net': entry['net'],
            'count': entry['count'],
            'actions': {k: actions[k] for k in sorted(actions)}
        }
    return result

def canonical_chemical_formula(formula: str) -> str:
    s = formula.strip()
    if not s:
        raise ValueError('empty formula')

    n = len(s)
    i = 0

    def parse_count() -> int:
        nonlocal i
        if i >= n or not s[i].isdigit():
            return 1
        j = i
        while j < n and s[j].isdigit():
            j += 1
        num = s[i:j]
        if num[0] == '0':
            raise ValueError('invalid count')
        val = int(num)
        if val == 0:
            raise ValueError('invalid count')
        i = j
        return val

    def merge(target, source, mult=1):
        for k, v in source.items():
            target[k] = target.get(k, 0) + v * mult

    def parse_group():
        nonlocal i
        counts = {}
        seen_item = False
        while i < n and s[i] != ')':
            ch = s[i]
            if ch == '(':
                i += 1
                inner = parse_group()
                if i >= n or s[i] != ')':
                    raise ValueError('unmatched parenthesis')
                if not inner:
                    raise ValueError('empty group')
                i += 1
                mult = parse_count()
                merge(counts, inner, mult)
                seen_item = True
            elif ch.isupper():
                j = i + 1
                while j < n and s[j].islower():
                    j += 1
                symbol = s[i:j]
                i = j
                mult = parse_count()
                counts[symbol] = counts.get(symbol, 0) + mult
                seen_item = True
            elif ch.isdigit() or ch.islower() or ch.isspace():
                raise ValueError('malformed formula')
            else:
                raise ValueError('malformed formula')
        return counts if seen_item else {}

    counts = parse_group()
    if i != n:
        if s[i] == ')':
            raise ValueError('unmatched parenthesis')
        raise ValueError('malformed formula')

    if not counts:
        raise ValueError('empty formula')

    parts = []
    for symbol in sorted(counts):
        c = counts[symbol]
        parts.append(symbol if c == 1 else f'{symbol}{c}')
    return ''.join(parts)

def parse_compound_counts(formula: str) -> dict[str, int]:
    if not formula:
        raise ValueError("empty formula")

    n = len(formula)
    i = 0

    def parse_number() -> int:
        nonlocal i
        if i >= n or not formula[i].isdigit():
            return 1
        if formula[i] == '0':
            raise ValueError("zero multiplier not allowed")
        val = 0
        while i < n and formula[i].isdigit():
            val = val * 10 + (ord(formula[i]) - 48)
            i += 1
        if val <= 0:
            raise ValueError("invalid multiplier")
        return val

    def merge(dst: dict[str, int], src: dict[str, int], mul: int) -> None:
        for k, v in src.items():
            dst[k] = dst.get(k, 0) + v * mul

    def parse_group() -> dict[str, int]:
        nonlocal i
        counts: dict[str, int] = {}
        seen_item = False
        while i < n and formula[i] != ')':
            ch = formula[i]
            if ch == '(':
                i += 1
                inner = parse_group()
                if i >= n or formula[i] != ')':
                    raise ValueError("unmatched parenthesis")
                i += 1
                mul = parse_number()
                merge(counts, inner, mul)
                seen_item = True
            elif ch.isupper():
                start = i
                i += 1
                while i < n and formula[i].islower():
                    i += 1
                symbol = formula[start:i]
                mul = parse_number()
                counts[symbol] = counts.get(symbol, 0) + mul
                seen_item = True
            elif ch.isdigit():
                raise ValueError("number in invalid position")
            else:
                raise ValueError("invalid character")
        if not seen_item and (i >= n or formula[i] == ')'):
            return counts
        return counts

    result = parse_group()
    if i != n:
        if formula[i] == ')':
            raise ValueError("unmatched closing parenthesis")
        raise ValueError("trailing invalid input")
    return result

