def normalize_event_log(events):
    try:
        iterator = iter(events)
    except TypeError:
        raise ValueError("events must be iterable")

    grouped = {}
    for event in iterator:
        if not isinstance(event, (list, tuple)) or len(event) != 3:
            raise ValueError("each event must be a 3-item sequence")
        timestamp, category, value = event
        if not isinstance(timestamp, int):
            raise ValueError("timestamp must be an integer")
        if not isinstance(category, str):
            raise ValueError("category must be a string")
        if not (isinstance(value, (int, float)) or value is None):
            raise ValueError("value must be an int, float, or None")

        data = grouped.setdefault(category, {
            "count": 0,
            "first_timestamp": timestamp,
            "last_timestamp": timestamp,
            "value_total": 0.0,
            "value_count": 0,
            "missing_values": 0,
        })
        data["count"] += 1
        if timestamp < data["first_timestamp"]:
            data["first_timestamp"] = timestamp
        if timestamp > data["last_timestamp"]:
            data["last_timestamp"] = timestamp
        if value is None:
            data["missing_values"] += 1
        else:
            data["value_total"] += float(value)
            data["value_count"] += 1

    result = {}
    for category in sorted(grouped):
        data = grouped[category]
        value_mean = None
        if data["value_count"] > 0:
            value_mean = data["value_total"] / data["value_count"]
        result[category] = {
            "count": data["count"],
            "first_timestamp": data["first_timestamp"],
            "last_timestamp": data["last_timestamp"],
            "value_total": data["value_total"],
            "value_mean": value_mean,
            "missing_values": data["missing_values"],
        }
    return result

def parse_packet_flags(spec: str) -> int:
    flags = {
        'URG': 1,
        'ACK': 2,
        'PSH': 4,
        'RST': 8,
        'SYN': 16,
        'FIN': 32,
    }
    if spec.strip() == '':
        return 0
    result = 0
    for token in spec.split():
        if token == '0':
            continue
        if token not in flags:
            raise ValueError(f'Invalid token: {token}')
        result |= flags[token]
    return result

def normalize_route(stops):
