            raise TypeError('Each command must be a tuple of length 2')
        ingredient, delta = cmd
        if not isinstance(ingredient, str):
            raise TypeError('Ingredient must be a string')
        if not isinstance(delta, int):
            raise TypeError('Delta must be an integer')
        quantities[ingredient] = quantities.get(ingredient, 0) + delta
        if quantities[ingredient] == 0:
