    for raw in tokens:
        token = raw.strip()
        if not token:
            raise ValueError('empty token')
        t = token.upper()
        if t == 'N':
            y += 1
        elif t == 'S':
            y -= 1
        elif t == 'E':
            x += 1
        elif t == 'W':
            x -= 1
        else:
            raise ValueError(f'invalid token: {token}')
    return (x, y)

def compress_segments(values):
    result = []
    iterator = iter(values)
    index = 0

    try:
        first = next(iterator)
    except StopIteration:
        return result

    if type(first) is not int:
        raise TypeError("all elements must be integers")

    current_value = first
    start_index = 0
    length = 1

    for item in iterator:
        if type(item) is not int:
            raise TypeError("all elements must be integers")
        if item == current_value:
            length += 1
        else:
            result.append((current_value, start_index, length))
            start_index = index + 1
            current_value = item
            length = 1
        index += 1

    result.append((current_value, start_index, length))
    return result

def expand_compact_tags(text: str) -> str:
    parts = [part.strip() for part in text.split(';')]
    out = []
    for part in parts:
        if not part:
            continue
        if '[' not in part and ']' not in part:
            out.append(part)
            continue
        if part.count('[') != 1 or part.count(']') != 1:
            raise ValueError('unmatched or nested brackets')
        open_idx = part.find('[')
        close_idx = part.rfind(']')
        if open_idx > close_idx:
            raise ValueError('unmatched brackets')
        tag = part[:open_idx]
        content = part[open_idx + 1:close_idx]
        if not tag or not tag.isalpha() or not tag.isupper():
            raise ValueError('invalid tag name')
        if '[' in content or ']' in content:
            raise ValueError('nested brackets in content')
        if close_idx != len(part) - 1:
            raise ValueError('trailing invalid characters')
        out.append(f'<{tag}>{content}</{tag}>')
    return ''.join(out)

def normalize_launch_commands(commands):
    result = []
    for item in commands:
        if isinstance(item, str):
            s = item.strip()
            if s:
                result.append(s)
        elif isinstance(item, (list, tuple)):
            if len(item) != 2:
                raise ValueError("tuple/list items must have exactly 2 elements")
            label, command = item
            if not isinstance(label, str) or not isinstance(command, str):
                raise TypeError("label and command must be strings")
            label = label.strip()
            command = command.strip()
            if not label:
                raise ValueError("label must not be empty")
            if command:
                result.append(f"{label}: {command}")
        else:
            raise TypeError("invalid command specification")
    return result

