def parse_weighted_votes(text):
    if text.strip() == "":
        return {}

    result = {}
    seen_order = []
    entries = text.split(',')
    for raw_entry in entries:
        entry = raw_entry.strip()
        if entry == "":
            raise ValueError("Malformed entry")
        if entry.count(':') != 1:
            raise ValueError("Malformed entry")
        name_part, weight_part = entry.split(':')
        name = name_part.strip()
        weight_str = weight_part.strip()
        if name == "" or weight_str == "":
            raise ValueError("Malformed entry")
        if ',' in name or ':' in name:
            raise ValueError("Malformed entry")
        try:
            weight = int(weight_str)
        except Exception:
            raise ValueError("Malformed entry")
        if name not in result:
            result[name] = weight
            seen_order.append(name)
        else:
            result[name] += weight
    return {name: result[name] for name in seen_order}

