def summarize_runs(s):
    if not isinstance(s, str):
        raise ValueError('input must be a string')

    parts = [p.strip() for p in s.split(',')]
    values = []
    for part in parts:
        if part == '':
            continue
        try:
            values.append(int(part, 10))
        except Exception:
            raise ValueError('invalid integer token')

    if not values:
        return {
            'count': 0,
            'longest_non_decreasing_run': 0,
            'first_drop_index': -1,
            'strict_increases': 0,
        }

    count = len(values)
    strict_increases = 0
    first_drop_index = -1
    longest = 1
    current = 1

    for i in range(1, count):
        if values[i] > values[i - 1]:
            strict_increases += 1
            current += 1
        elif values[i] == values[i - 1]:
            current += 1
        else:
            if first_drop_index == -1:
                first_drop_index = i
            if current > longest:
                longest = current
            current = 1
    if current > longest:
        longest = current

    return {
        'count': count,
        'longest_non_decreasing_run': longest,
        'first_drop_index': first_drop_index,
        'strict_increases': strict_increases,
    }

