def normalize_schedule(events, day_start=0, day_end=1440):
    if not isinstance(day_start, int) or not isinstance(day_end, int):
        raise TypeError("day_start and day_end must be integers")
    if day_start > day_end:
        raise ValueError("day_start must not exceed day_end")
    try:
        iterator = iter(events)
    except TypeError:
        raise TypeError("events must be iterable")

    cleaned = []
    for event in iterator:
        try:
            start, end = event
        except Exception:
            continue
        if not isinstance(start, int) or not isinstance(end, int):
            continue
        if start >= end:
            continue
        start = max(start, day_start)
        end = min(end, day_end)
        if start >= end:
            continue
        cleaned.append((start, end))

    if not cleaned:
        return []

    cleaned.sort(key=lambda x: (x[0], x[1]))
    merged = [cleaned[0]]
    for start, end in cleaned[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def summarize_grid_walk(grid, start):
    if not isinstance(grid, list) or not grid:
        raise ValueError("grid must be a non-empty list of strings")
    if not all(isinstance(row, str) and row for row in grid):
        raise ValueError("grid rows must be non-empty strings")
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("grid rows must have equal length")
    if (
        not isinstance(start, tuple)
        or len(start) != 2
        or not all(isinstance(x, int) for x in start)
    ):
        raise ValueError("start must be a pair of integers")

    rows = len(grid)
    r, c = start
    if not (0 <= r < rows and 0 <= c < width):
        return {"path": [], "steps": 0, "status": "invalid"}

    allowed = {'^', 'v', '<', '>', 'X'}
    path = [(r, c)]
    seen = {(r, c)}
    steps = 0

    while True:
        ch = grid[r][c]
        if ch not in allowed:
            return {"path": path, "steps": steps, "status": "invalid"}
        if ch == 'X':
            return {"path": path, "steps": steps, "status": "stopped"}

        if ch == '^':
            nr, nc = r - 1, c
        elif ch == 'v':
            nr, nc = r + 1, c
        elif ch == '<':
            nr, nc = r, c - 1
        else:
            nr, nc = r, c + 1

        if not (0 <= nr < rows and 0 <= nc < width):
            return {"path": path, "steps": steps + 1, "status": "escaped"}

        steps += 1
        r, c = nr, nc
        path.append((r, c))
        if (r, c) in seen:
            return {"path": path, "steps": steps, "status": "invalid"}
        seen.add((r, c))

def normalize_reactions(log):
    latest = {}
    for event in log:
        if not isinstance(event, tuple) or len(event) != 2:
            continue
        user, reaction = event
        if not isinstance(user, str) or not isinstance(reaction, str):
            continue
        latest[user.lower()] = reaction.lower()
    if not latest:
        return ''
    return ';'.join(f'{user}:{latest[user]}' for user in sorted(latest))

def pack_observation_runs(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    # Validate hashability without modifying the input.
    for item in events:
        try:
            hash(item)
        except TypeError:
            raise TypeError("all items must be hashable")

    if not events:
        return []

    result = []
    current_value = events[0]
    count = 1

    for item in events[1:]:
        if item == current_value:
            count += 1
        else:
            result.append((current_value, count))
            current_value = item
            count = 1

    result.append((current_value, count))
    return result

def compress_runs(seq):
    if not isinstance(seq, (list, tuple)):
        raise TypeError('seq must be a list or tuple of integers')
    result = []
    if len(seq) == 0:
        return result
    prev = seq[0]
    if isinstance(prev, bool) or not isinstance(prev, int):
        raise TypeError('all elements must be integers')
    count = 1
    for x in seq[1:]:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError('all elements must be integers')
        if x == prev:
            count += 1
        else:
            result.append((prev, count))
            prev = x
            count = 1
    result.append((prev, count))
    return result

def render_int_art(values, width):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if not isinstance(width, int):
        raise TypeError("width must be an int")
    if width < 1:
        raise ValueError("width must be at least 1")

    lines = []
    for v in values:
        if not isinstance(v, int):
            raise TypeError("all values must be integers")
        if v > 0:
            marks = "#" * min(v, width)
        elif v < 0:
            marks = "-" * min(-v, width)
        else:
            marks = ""
        lines.append(marks + " " * (width - len(marks)))
    return "\n".join(lines)

def plan_round_robin(tasks, slot_size, rounds):
    if not isinstance(slot_size, int):
        raise TypeError("slot_size must be an int")
    if not isinstance(rounds, int):
        raise TypeError("rounds must be an int")
    if slot_size < 1:
        raise ValueError("slot_size must be positive")
    if rounds < 0:
        raise ValueError("rounds must be non-negative")

    task_list = list(tasks)
    for name in task_list:
        if not isinstance(name, str) or name == "":
            raise ValueError("all task names must be non-empty strings")

    if not task_list or rounds == 0:
        return []

    schedule = []
    for _ in range(rounds):
        for idx, name in enumerate(task_list, start=1):
            schedule.append((name, slot_size * idx))
    return schedule

def normalize_inventory(transactions):
    totals = {}
    order = []

    for tx in transactions:
        if not isinstance(tx, str):
            raise ValueError("Invalid transaction")
        if tx.count(":") != 1:
            raise ValueError("Invalid transaction")
        name, qty_text = tx.split(":")
        if name == "":
            raise ValueError("Invalid transaction")
        if qty_text == "":
            raise ValueError("Invalid transaction")
        if qty_text[0] in "+-":
            digits = qty_text[1:]
            if digits == "" or not digits.isdigit():
                raise ValueError("Invalid transaction")
        else:
            if not qty_text.isdigit():
                raise ValueError("Invalid transaction")
        qty = int(qty_text)
        if name not in totals:
            totals[name] = 0
            order.append(name)
        totals[name] += qty

    parts = []
    for name in order:
        total = totals[name]
        if total != 0:
            parts.append(f"{name}={total}")
    return ";".join(parts)

def normalize_schedules(schedules):
    validated = []
    for item in schedules:
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError('Each schedule must be a tuple of length 3')
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('Start and end must be integers')
        if not isinstance(label, str) or label == '':
            raise ValueError('Label must be a non-empty string')
        if start > end:
            raise ValueError('Start must be less than or equal to end')
        validated.append((start, end, label))

    validated.sort(key=lambda x: (x[0], x[1], x[2]))

    result = []
    for start, end, label in validated:
        if result and result[-1][2] == label and start <= result[-1][1] + 1:
            prev_start, prev_end, prev_label = result[-1]
            result[-1] = (prev_start, max(prev_end, end), prev_label)
        else:
            result.append((start, end, label))
    return result

def normalize_permissions(spec):
    if spec is None:
        raise ValueError('spec must be a string')
    if not isinstance(spec, str):
        raise ValueError('spec must be a string')

    action_rank = {'admin': 0, 'execute': 1, 'write': 2, 'read': 3}
    allowed_actions = set(action_rank)
    result = set()

    if spec.strip() == '':
        return []

    for raw_token in spec.split(','):
        token = raw_token.strip()
        if token == '':
            continue
        if ':' not in token:
            raise ValueError('missing colon')
        left, right = token.split(':', 1)
        action = left.strip().lower()
        target = right.strip().lower()
        if action not in allowed_actions:
            raise ValueError('unknown action')
        if target == '':
            raise ValueError('empty target')
        for ch in target:
            if not (ch.isalnum() or ch == '_'):
                raise ValueError('invalid target')
        result.add((action, target))

    return [f'{a}:{t}' for a, t in sorted(result, key=lambda p: (action_rank[p[0]], p[1]))]

def normalize_route_segments(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a str')

    absolute = path.startswith('/')
    trailing = path.endswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            continue
        stack.append(part)

    if not stack:
        return '/' if absolute else ''

    result = '/'.join(stack)
    if absolute:
        result = '/' + result
    if trailing:
        result += '/'
    return result

def normalize_schedule(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    validated = []
    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError("each event must be a 3-item tuple")
        day, start, duration = rec
        if not isinstance(day, int) or isinstance(day, bool):
            raise ValueError("day must be int")
        if not isinstance(start, int) or isinstance(start, bool):
            raise ValueError("start must be int")
        if not isinstance(duration, int) or isinstance(duration, bool):
            raise ValueError("duration must be int")
        if day < 1 or day > 7:
            raise ValueError("day out of range")
        if start < 0 or start > 1439:
            raise ValueError("start out of range")
        if duration <= 0:
            raise ValueError("duration must be positive")
        end = start + duration
        if end > 1440:
            raise ValueError("interval exceeds day")
        validated.append((day, start, end))

    if not validated:
        return ""

    by_day = {}
    for day, start, end in validated:
        by_day.setdefault(day, []).append((start, end))

    def fmt(mins):
        h, m = divmod(mins, 60)
        return f"{h:02d}:{m:02d}"

    parts = []
    for day in sorted(by_day):
        intervals = sorted(by_day[day])
        merged = []
        cur_s, cur_e = intervals[0]
        for s, e in intervals[1:]:
            if s <= cur_e:
                if e > cur_e:
                    cur_e = e
            else:
                merged.append((cur_s, cur_e))
                cur_s, cur_e = s, e
        merged.append((cur_s, cur_e))
        for s, e in merged:
            parts.append(f"D{day}:{fmt(s)}-{fmt(e)}")
    return ";".join(parts)

def normalize_profile_records(records):
    if not isinstance(records, list):
        raise TypeError("records must be a list")

    result = []
    for rec in records:
        if not isinstance(rec, dict):
            raise TypeError("each record must be a dict")

        rec_id = rec.get('id', None)
        if not isinstance(rec_id, int) or isinstance(rec_id, bool) or rec_id <= 0:
            continue

        name = rec.get('name', '')
        email = rec.get('email', '')
        tags = rec.get('tags', [])

        name = str(name).strip().title()
        email = str(email).strip().lower()

        if isinstance(tags, str):
            raw_tags = tags.split(',')
        else:
            try:
                raw_tags = list(tags)
            except TypeError:
                raw_tags = [tags]

        cleaned = []
        seen = set()
        for tag in raw_tags:
            t = str(tag).strip()
            if not t:
                continue
            if t not in seen:
                seen.add(t)
                cleaned.append(t)
        cleaned.sort()

        result.append({'id': rec_id, 'name': name, 'email': email, 'tags': cleaned})

    return result

def parse_purchase_order(lines):
    order_id = None
    customer = None
    items = []

    for raw in lines:
        if not isinstance(raw, str):
            raise ValueError('all lines must be strings')
        line = raw.strip()
        if line == '' or line.startswith('#'):
            continue
        if line.startswith('ORDER '):
            if order_id is not None:
                raise ValueError('duplicate ORDER')
            parts = line.split()
            if len(parts) != 2 or not parts[1]:
                raise ValueError('malformed ORDER')
            order_id = parts[1]
            if ' ' in order_id:
                raise ValueError('malformed ORDER')
        elif line.startswith('CUSTOMER='):
            if customer is not None:
                raise ValueError('duplicate CUSTOMER')
            customer = line[len('CUSTOMER='):]
            if customer == '':
                raise ValueError('malformed CUSTOMER')
        elif line.startswith('ITEM '):
            parts = line.split()
            if len(parts) != 4:
                raise ValueError('malformed ITEM')
            sku, qty_s, price_s = parts[1], parts[2], parts[3]
            if not sku or ' ' in sku:
                raise ValueError('malformed ITEM')
            try:
                quantity = int(qty_s)
            except Exception:
                raise ValueError('invalid quantity')
            if str(quantity) != qty_s or quantity <= 0:
                raise ValueError('invalid quantity')
            try:
                unit_price = float(price_s)
            except Exception:
                raise ValueError('invalid price')
            if unit_price < 0:
                raise ValueError('invalid price')
            line_total = quantity * unit_price
            items.append({'sku': sku, 'quantity': quantity, 'unit_price': unit_price, 'line_total': line_total})
        else:
            raise ValueError('malformed line')

    if order_id is None or customer is None:
        raise ValueError('missing required fields')

    grand_total = sum(item['line_total'] for item in items)
    return {
        'order_id': order_id,
        'customer': customer,
        'items': items,
        'grand_total': grand_total,
    }

def normalize_section_labels(labels):
    if not isinstance(labels, list):
        raise TypeError("labels must be a list")
    result = []
    for item in labels:
        if not isinstance(item, str):
            raise TypeError("all labels must be strings")
        collapsed = " ".join(item.split())
        if collapsed == "":
            result.append("<EMPTY>")
        else:
            result.append(collapsed.upper())
    return result

def normalize_route_segments(path):
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    if path == '':
        return ''
    parts = [seg for seg in path.split('/') if seg != '']
    normalized = []
    for seg in parts:
        low = seg.lower()
        if low.isalpha() and len(low) > 3:
            low = low[:3]
        normalized.append(low)
    return '/'.join(normalized)

def compress_ranges(nums):
    if not isinstance(nums, list):
        raise TypeError('nums must be a list')
    for x in nums:
        if not isinstance(x, int):
            raise TypeError('all elements must be integers')
    if not nums:
        return []
    values = sorted(set(nums))
    ranges = []
    start = prev = values[0]
    for v in values[1:]:
        if v == prev + 1:
            prev = v
        else:
            ranges.append((start, prev))
            start = prev = v
    ranges.append((start, prev))
    return ranges

def normalize_priority_queue(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')

    validated = []
    for item in events:
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError('each event must be a 3-tuple')
        priority, timestamp, payload = item
        if not isinstance(priority, int):
            raise ValueError('priority must be int')
        if not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError('timestamp must be a non-negative int')
        validated.append(item)

    return sorted(validated, key=lambda x: (x[0], x[1], str(x[2])))

def normalize_inventory_movements(movements):
    totals = {}
    for record in movements:
        if record is None:
            continue
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            continue
        item, action, quantity = record
        if not isinstance(item, str) or item == '':
            continue
        if action not in ('in', 'out', 'adjust'):
            continue
        if not isinstance(quantity, int):
            continue
        if action == 'in':
            totals[item] = totals.get(item, 0) + quantity
        elif action == 'out':
            totals[item] = totals.get(item, 0) - quantity
        else:
            totals[item] = quantity
    return sorted((item, total) for item, total in totals.items() if total != 0)

def summarize_packet_stream(packets):
    accepted = []
    for item in packets:
        if item == 'DROP':
            if not accepted:
                raise ValueError('DROP with no packet to remove')
            accepted.pop()
            continue
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('Invalid packet description')
        kind, size = item
        if not isinstance(kind, str) or kind == '' or not isinstance(size, int) or size < 0:
            raise ValueError('Invalid packet tuple')
        accepted.append((kind, size))

    if not accepted:
        return ''

    order = []
    seen = set()
    totals = {}
    counts = {}
    for kind, size in accepted:
        if kind not in seen:
            seen.add(kind)
            order.append(kind)
        counts[kind] = counts.get(kind, 0) + 1
        totals[kind] = totals.get(kind, 0) + size

    parts = []
    for kind in order:
        parts.append(f'{kind}={counts[kind]}:{totals[kind]}')
    return ';'.join(parts)

def distribute_tokens(users, token_count):
    if not isinstance(users, list):
        raise TypeError("users must be a list")
    if not isinstance(token_count, int):
        raise TypeError("token_count must be an integer")
    if token_count < 0:
        raise ValueError("token_count must be non-negative")
    for u in users:
        if not isinstance(u, str) or u == "":
            raise ValueError("each user must be a non-empty string")

    result = {}
    for u in users:
        if u not in result:
            result[u] = []

    if token_count == 0 or not users:
        return result if users else {}

    distinct_order = []
    seen = set()
    for u in users:
        if u not in seen:
            seen.add(u)
            distinct_order.append(u)

    for token in range(1, token_count + 1):
        idx = (token - 1) % len(users)
        user = users[idx]
        result[user].append(token)
    return result

