def summarize_changes(before, after):
    if not isinstance(before, list) or not isinstance(after, list):
        raise TypeError("before and after must be lists")
    if len(before) != len(after):
        raise ValueError("before and after must have the same length")

    increased = 0
    decreased = 0
    unchanged = 0
    delta_sum = 0

    for b, a in zip(before, after):
        diff = a - b
        delta_sum += diff
        if diff > 0:
            increased += 1
        elif diff < 0:
            decreased += 1
        else:
            unchanged += 1

    return {
        "increased": increased,
        "decreased": decreased,
        "unchanged": unchanged,
        "delta_sum": delta_sum,
    }

def summarize_spans(text, keywords):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    try:
        kws = list(keywords)
    except TypeError:
        raise TypeError("keywords must be iterable of strings")
    lowered = []
    for kw in kws:
        if not isinstance(kw, str):
            raise TypeError("keywords must be iterable of strings")
        if kw == "":
            raise ValueError("empty keyword is invalid")
        lowered.append(kw.lower())
    unique_keywords = []
    seen = set()
    for kw in lowered:
        if kw not in seen:
            seen.add(kw)
            unique_keywords.append(kw)
    if not unique_keywords:
        return {'counts': {}, 'first_positions': {}, 'longest_run': (None, 0)}
    words = []
    current = []
    for ch in text:
        if ch.isascii() and ch.isalnum():
            current.append(ch.lower())
        else:
            if current:
                words.append(''.join(current))
                current = []
    if current:
        words.append(''.join(current))
    counts = {kw: 0 for kw in unique_keywords}
    first_positions = {kw: -1 for kw in unique_keywords}
    positions = {kw: [] for kw in unique_keywords}
    for i, w in enumerate(words):
        if w in counts:
            counts[w] += 1
            positions[w].append(i)
            if first_positions[w] == -1:
                first_positions[w] = i
    best_kw = None
    best_len = 0
    best_first = None
    for kw in unique_keywords:
        pos = positions[kw]
        max_run = 0
        run = 0
        prev = None
        for p in pos:
            if prev is not None and p == prev + 1:
                run += 1
            else:
                run = 1
            if run > max_run:
                max_run = run
            prev = p
        if max_run > 0:
            candidate_first = first_positions[kw]
            if (max_run > best_len or
                (max_run == best_len and (best_first is None or candidate_first < best_first)) or
                (max_run == best_len and candidate_first == best_first and kw < best_kw)):
                best_kw = kw
                best_len = max_run
                best_first = candidate_first
    if best_kw is None:
        longest_run = (None, 0)
    else:
        longest_run = (best_kw, best_len)
    return {'counts': counts, 'first_positions': first_positions, 'longest_run': longest_run}

def normalize_inventory(records):
    valid = []
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            continue
        category, item_id, quantity = rec
        if not isinstance(category, str) or not isinstance(item_id, str):
            continue
        if not isinstance(quantity, int) or quantity < 0:
            continue
        valid.append((category, item_id, quantity))

    if not valid:
        return {'categories': {}, 'grand_total': 0}

    by_category = {}
    for category, item_id, quantity in valid:
        if category not in by_category:
            by_category[category] = {}
        if item_id not in by_category[category]:
            by_category[category][item_id] = 0
        by_category[category][item_id] += quantity

    categories_out = {}
    grand_total = 0
    for category in sorted(by_category):
        items = by_category[category]
        items_out = {}
        total = 0
        for item_id in sorted(items):
            qty = items[item_id]
            items_out[item_id] = qty
            total += qty
        categories_out[category] = {'total': total, 'items': items_out}
        grand_total += total

    return {'categories': categories_out, 'grand_total': grand_total}

def summarize_ranges(nums):
    if not nums:
        return ""

    parts = []
    start = prev = nums[0]

    for x in nums[1:]:
        if x == prev + 1:
            prev = x
        else:
            if start == prev:
                parts.append(str(start))
            else:
                parts.append(f"{start}-{prev}")
            start = prev = x

    if start == prev:
        parts.append(str(start))
    else:
        parts.append(f"{start}-{prev}")

    return ",".join(parts)

def select_min_cost_path(grid):
    if not isinstance(grid, list) or len(grid) == 0:
        raise ValueError("grid must be a non-empty list of rows")
    if not all(isinstance(row, list) for row in grid):
        raise ValueError("grid must be a list of lists")
    if any(len(row) == 0 for row in grid):
        raise ValueError("rows must be non-empty")
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("all rows must have the same length")
    for row in grid:
        for cell in row:
            if not isinstance(cell, int):
                raise ValueError("all cells must be integers")

    rows = len(grid)
    cols = width
    dp = [0] * cols
    dp[0] = grid[0][0]
    for j in range(1, cols):
        dp[j] = dp[j - 1] + grid[0][j]
    for i in range(1, rows):
        dp[0] += grid[i][0]
        for j in range(1, cols):
            dp[j] = min(dp[j], dp[j - 1]) + grid[i][j]
    return dp[-1]

def pack_ranges(values):
    items = []
    for v in values:
        if type(v) is not int:
            raise TypeError('all elements must be integers')
        items.append(v)

    if not items:
        return ''

    nums = sorted(set(items))
    parts = []
    i = 0
    n = len(nums)

    while i < n:
        start = nums[i]
        j = i
        while j + 1 < n and nums[j + 1] == nums[j] + 1:
            j += 1
        length = j - i + 1
        if length >= 3:
            parts.append(f'{start}-{nums[j]}')
        elif length == 2:
            parts.append(str(nums[i]))
            parts.append(str(nums[j]))
        else:
            parts.append(str(start))
        i = j + 1

    return ','.join(parts)

def normalize_spreadsheet_headers(headers):
    if not isinstance(headers, list):
        raise TypeError("headers must be a list")

    seen = {}
    result = []

    for header in headers:
        if not isinstance(header, str):
            raise TypeError("all headers must be strings")

        if header not in seen:
            seen[header] = 1
            result.append(header)
        else:
            k = seen[header] + 1
            candidate = f"{header}({k})"
            while candidate in seen:
                k += 1
                candidate = f"{header}({k})"
            seen[header] = k
            seen[candidate] = 1
            result.append(candidate)

    return result

def parse_tape(spec: str) -> list[tuple[int, str]]:
    s = spec.strip()
    if s == "":
        return []
    parts = [p.strip() for p in s.split(';')]
    if any(p == "" for p in parts):
        raise ValueError("empty segment")
    result = []
    for part in parts:
        if part.count('*') != 1:
            raise ValueError("malformed segment")
        count_str, symbol = part.split('*')
        if count_str == "" or symbol == "":
            raise ValueError("malformed segment")
        if count_str.startswith('-'):
            raise ValueError("negative count")
        if not count_str.isdigit():
            raise ValueError("non-numeric count")
        count = int(count_str)
        result.append((count, symbol))
    return result

def canonicalize_command_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    s = path.strip()
    parts = []
    for comp in s.split('/'):
        if comp == '' or comp == '.':
            continue
        if comp == '..':
            if parts:
                parts.pop()
            continue
        parts.append(comp)
    return '/'.join(parts) if parts else '.'

def normalize_inventory(records):
    totals = {}
    weighted = {}
    for record in records:
        if len(record) != 3:
            raise TypeError('each record must have exactly 3 items')
        sku, quantity, price = record
        if not isinstance(sku, str) or not isinstance(quantity, int) or not isinstance(price, (int, float)):
            raise TypeError('invalid record types')
        if quantity < 0:
            raise ValueError('quantity cannot be negative')
        if quantity == 0:
            continue
        if sku not in totals:
            totals[sku] = 0
            weighted[sku] = 0.0
        totals[sku] += quantity
        weighted[sku] += quantity * float(price)
    result = []
    for sku in sorted(totals):
        total_quantity = totals[sku]
        if total_quantity == 0:
            continue
        avg = weighted[sku] / total_quantity
        result.append((sku, total_quantity, float(avg)))
    return result

def summarize_runs(data):
    runs = []
    total_items = 0
    distinct = set()

    iterator = iter(data)
    try:
        first = next(iterator)
    except StopIteration:
        return {"runs": [], "longest_run": None, "total_items": 0, "distinct_values": 0}

    if type(first) is not int:
        raise TypeError("all elements must be integers")

    current_value = first
    current_length = 1
    total_items = 1
    distinct.add(first)

    for item in iterator:
        if type(item) is not int:
            raise TypeError("all elements must be integers")
        total_items += 1
        distinct.add(item)
        if item == current_value:
            current_length += 1
        else:
            runs.append((current_value, current_length))
            current_value = item
            current_length = 1

    runs.append((current_value, current_length))

    longest = runs[0]
    for run in runs[1:]:
        if run[1] > longest[1]:
            longest = run

    return {
        "runs": runs,
        "longest_run": longest,
        "total_items": total_items,
        "distinct_values": len(distinct),
    }

