def normalize_cli_args(args):
    result = []
    for arg in args:
        if not isinstance(arg, str):
            raise ValueError('all arguments must be strings')
        if not arg.startswith('-'):
            continue
        if arg == '-':
            raise ValueError('invalid lone dash')
        if arg.startswith('--'):
            body = arg[2:]
            if body.startswith('no-'):
                name = body[3:]
                if not name or '=' in name or name.count('=') > 0:
                    raise ValueError('invalid long option')
                result.append((name, 'false'))
            else:
                if body.count('=') > 1:
                    raise ValueError('invalid long option')
                if '=' in body:
                    name, value = body.split('=', 1)
                    if not name:
                        raise ValueError('invalid long option')
                    result.append((name, value))
                else:
                    if not body:
                        raise ValueError('invalid long option')
                    result.append((body, 'true'))
        else:
            body = arg[1:]
            if not body or '=' in body:
                raise ValueError('invalid short option')
            if not body.isalpha():
                raise ValueError('invalid short option')
            for ch in body:
                result.append((ch, 'true'))
    return result

def normalize_transcript(lines):
    result = []
    for raw in lines:
        if not isinstance(raw, str):
            raise TypeError('all items must be strings')
        s = raw.strip()
        if not s:
            continue
        label_end = s.find(':')
        if label_end > 0:
            prefix = s[:label_end]
            if prefix and all(ch.isupper() or ch.isdigit() or ch == '_' for ch in prefix):
                s = s[label_end + 1:].lstrip()
        s = ' '.join(s.split())
        s = s.lower()
        if s:
            result.append(s)
    return result

def normalize_ledger(entries):
    if entries == []:
        return ""
    totals = {}
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise TypeError("Each entry must be a 2-tuple")
        name, amount = entry
        if not isinstance(name, str):
            raise TypeError("Account name must be a string")
        normalized = name.strip()
        if normalized == "":
            raise ValueError("Account name cannot be empty")
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError("Amount must be int or float")
        totals[normalized] = totals.get(normalized, 0) + amount
    parts = []
    for name in sorted(totals):
        total = totals[name]
        if isinstance(total, float) and total.is_integer():
            total = int(total)
        parts.append(f"{name}={total}")
    return ";".join(parts)

def normalize_kv_pairs(text: str) -> dict:
    result = {}
    for raw_line in text.split('\n'):
        line = raw_line.strip()
        if not line:
            continue
        if line.count('=') != 1:
            raise ValueError('each non-empty line must contain exactly one =')
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError('key must be non-empty')
        result[key] = value
    return result

