def normalize_breadcrumb_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    is_absolute = path.startswith('/')
    parts = []

    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts and parts[-1] != '..':
                parts.pop()
            else:
                if not is_absolute:
                    parts.append('..')
