        normalized = " ".join(item.strip().split())
        if normalized:
            result.append(normalized.lower())
    return result

def segment_run_lengths(s: str) -> list[tuple[str, int]]:
    if not isinstance(s, str):
        raise TypeError('s must be a str')

    def ws_category(ch: str) -> str:
        if ch == ' ':
            return 'space'
        if ch == '\t':
            return 'tab'
        if ch == '\n':
            return 'newline'
        return 'other_ws'

    if s == '':
        return []

    result = []
    prev_token = None
    count = 0

    for ch in s:
        if ch.isspace():
            token = ws_category(ch)
        else:
            token = ch

        if prev_token is None:
            prev_token = token
            count = 1
        elif token == prev_token:
            count += 1
        else:
            result.append((prev_token, count))
            prev_token = token
            count = 1

    result.append((prev_token, count))
    return result

def segment_label_runs(text: str) -> list[tuple[str, str, int]]:
    def label_of(ch: str) -> str:
        if 'a' <= ch <= 'z':
            return 'lower'
        if 'A' <= ch <= 'Z':
            return 'upper'
        if '0' <= ch <= '9':
            return 'digit'
        if ch in (' ', '\t', '\n', '\r'):
            return 'space'
        return 'other'

    if text == '':
        return []

    result = []
    current_char = text[0]
    run_len = 1

    for ch in text[1:]:
        if ch == current_char:
            run_len += 1
        else:
            result.append((label_of(current_char), current_char, run_len))
            current_char = ch
            run_len = 1

    result.append((label_of(current_char), current_char, run_len))
    return result

def compress_ranges(nums):
    if isinstance(nums, (str, bytes)):
        raise TypeError("nums must be a sequence of integers")
    try:
        iterator = iter(nums)
    except TypeError:
        raise TypeError("nums must be a sequence of integers")

    seen = set()
    unique = []
    for x in iterator:
        if not isinstance(x, int) or isinstance(x, bool):
            raise TypeError("nums must be a sequence of integers")
        if x not in seen:
            seen.add(x)
            unique.append(x)

    if not unique:
        return ""

    parts = []
    start = prev = unique[0]
    for x in unique[1:]:
        if x == prev + 1:
            prev = x
        else:
            length = prev - start + 1
            if length >= 3:
                parts.append(f"{start}-{prev}")
            else:
                parts.extend(str(n) for n in range(start, prev + 1))
            start = prev = x
    length = prev - start + 1
    if length >= 3:
        parts.append(f"{start}-{prev}")
    else:
        parts.extend(str(n) for n in range(start, prev + 1))

    return ",".join(parts)

def canonicalize_quota_string(s):
    if not isinstance(s, str):
        raise TypeError('s must be a string')

    totals = {}
    saw_valid = False

    for raw_token in s.split(','):
        token = raw_token.strip()
        if token == '':
            continue
        saw_valid = True

        if token.count(':') > 1:
            raise ValueError('too many colons')

        if ':' in token:
            name_part, quota_part = token.split(':', 1)
            name = name_part.strip()
            quota_str = quota_part.strip()
            if name == '':
                raise ValueError('missing department name')
            if quota_str == '':
                raise ValueError('missing quota')
            if quota_str[0] == '+':
                raise ValueError('invalid quota')
            if quota_str[0] == '-':
                raise ValueError('negative quota')
            if not quota_str.isdigit():
                raise ValueError('invalid quota')
            quota = int(quota_str)
        else:
            name = token
            if name == '':
                raise ValueError('missing department name')
            quota = 1

        totals[name] = totals.get(name, 0) + quota

    if not saw_valid:
        return ''

    return ','.join(f'{name}:{totals[name]}' for name in sorted(totals))

