def summarize_ragged_matrix(matrix):
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of rows")

    row_count = len(matrix)
    col_count = 0
    row_sums = []
    filled_cells = 0

    for row in matrix:
        if not isinstance(row, list):
            raise TypeError("each row must be a list")
        if len(row) > col_count:
            col_count = len(row)
        row_total = 0
        for value in row:
            if type(value) is not int:
                raise TypeError("all elements must be integers")
            row_total += value
            filled_cells += 1
        row_sums.append(row_total)

    col_sums = [0] * col_count
    for row in matrix:
        for i, value in enumerate(row):
            col_sums[i] += value

    missing_cells = row_count * col_count - filled_cells

    return {
        "row_count": row_count,
        "col_count": col_count,
        "filled_cells": filled_cells,
        "missing_cells": missing_cells,
        "row_sums": row_sums,
        "col_sums": col_sums,
    }

def compress_segments(values):
    result = []
    iterator = iter(values)
    try:
        first = next(iterator)
    except StopIteration:
        return result
    if type(first) is not int:
        raise TypeError("all elements must be integers")
    current = first
    count = 1
    for item in iterator:
        if type(item) is not int:
            raise TypeError("all elements must be integers")
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def normalize_query_string(query):
    if not isinstance(query, str):
        raise TypeError('query must be a string')
    if query == '':
        return ''

    items = {}
    for segment in query.split('&'):
        if segment == '':
            continue
        if segment.count('=') != 1:
            raise ValueError('each segment must contain exactly one =')
        key, value = segment.split('=')
        key = key.strip().lower()
        value = value.strip().lower()
        items[key] = value

    return '&'.join(f'{k}={items[k]}' for k in sorted(items))

def normalize_inventory(records):
    if records is None:
        raise ValueError('records must be iterable of strings')
    result = {}
    for rec in records:
        if not isinstance(rec, str):
            raise ValueError('each record must be a string')
        parts = rec.split(',')
        if len(parts) != 3:
            raise ValueError('each record must have exactly three fields')
        category, item, quantity = (p.strip() for p in parts)
        if item == '':
            raise ValueError('item name cannot be empty')
        if quantity == '':
            raise ValueError('quantity cannot be empty')
        try:
            qty = int(quantity, 10)
        except Exception as e:
            raise ValueError('invalid quantity') from e
        result.setdefault(item, set()).add(qty)
    return {item: sorted(qtys) for item, qtys in result.items()}

