def normalize_battle_log(log: str) -> str:
    def valid_ident(s: str) -> bool:
        return len(s) > 0 and all(ch.isalnum() or ch == '_' for ch in s)

    if log == '':
        return ''

    items = []
    for frag in log.split(';'):
        if frag == '':
            continue
        if '->' in frag:
            parts = frag.split('->')
            if len(parts) != 2:
                raise ValueError('Malformed fragment')
            a, b = parts
            typ = 'attack'
        elif '!' in frag:
            parts = frag.split('!')
            if len(parts) != 2:
                raise ValueError('Malformed fragment')
            a, b = parts
            typ = 'defeat'
        elif '?' in frag:
            parts = frag.split('?')
            if len(parts) != 2:
                raise ValueError('Malformed fragment')
            a, b = parts
            typ = 'heal'
        else:
            raise ValueError('Malformed fragment')
        if not (valid_ident(a) and valid_ident(b)):
            raise ValueError('Malformed fragment')
        items.append((a, typ, b))

    items.sort()
    return '\n'.join(f'{a}|{typ}|{b}' for a, typ, b in items)

