def normalize_sensor_readings(data):
    valid = {}
    order = []
    for item in data:
        if not isinstance(item, tuple) or len(item) != 2:
            continue
        timestamp, value = item
        if not isinstance(timestamp, int) or isinstance(timestamp, bool):
            continue
        if timestamp < 0:
            continue
        if not (isinstance(value, (int, float)) and not isinstance(value, bool)):
            continue
        if timestamp in valid:
            continue
        valid[timestamp] = float(value)
        order.append(timestamp)

    if not valid:
        return []

    timestamps = sorted(valid)
    values = [valid[t] for t in timestamps]
    min_v = min(values)
    max_v = max(values)

    result = []
    if max_v == min_v:
        for t in timestamps:
            result.append((t, 0.0))
        return result

    denom = max_v - min_v
    for t in timestamps:
        norm = (valid[t] - min_v) / denom
        result.append((t, round(float(norm), 6)))
    return result

def normalize_instructions(instructions):
    if not isinstance(instructions, list):
        raise ValueError("instructions must be a list")

    result = []
    for item in instructions:
        if not isinstance(item, str):
            raise ValueError("each instruction must be a string")
        if item.count('=') != 1:
            raise ValueError("each instruction must contain exactly one '='")
        name, value = item.split('=', 1)
        name = name.strip()
        value = value.strip()
        if not name:
            raise ValueError("name must be non-empty")
        if not all(ch.isalnum() or ch == '_' for ch in name):
            raise ValueError("invalid name")
        result.append(name.lower() + '=' + value)
    return result

def compress_stamped_ranges(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    result = []
    if not events:
        return result

    def validate_item(item):
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("each event must be a 2-element tuple")
        value, stamp = item
        if not isinstance(stamp, int):
            raise TypeError("stamp must be an integer")
        try:
            hash(value)
        except Exception:
            raise TypeError("value must be hashable")
        return value, stamp

    current_value, current_stamp = validate_item(events[0])
    run_start = current_stamp
    run_length = 1

    for item in events[1:]:
        value, stamp = validate_item(item)
        if value == current_value and stamp == current_stamp + 1:
            current_stamp = stamp
            run_length += 1
        else:
            if run_length >= 2:
                result.append((current_value, run_start, current_stamp))
            else:
                result.append((current_value, run_start))
            current_value = value
            current_stamp = stamp
            run_start = stamp
            run_length = 1

    if run_length >= 2:
        result.append((current_value, run_start, current_stamp))
    else:
        result.append((current_value, run_start))

    return result

def summarize_runs(data):
    if data.strip() == "":
        return {'runs': 0, 'total_numbers': 0, 'longest_run': 0, 'group_sums': []}

    runs = 0
    total_numbers = 0
    longest_run = 0
    group_sums = []

    for group in data.split('|'):
        group = group.strip()
        if not group:
            continue

        tokens = []
        current = []
        for ch in group:
            if ch == ',' or ch.isspace():
                if current:
                    tokens.append(''.join(current))
                    current = []
            else:
                current.append(ch)
        if current:
            tokens.append(''.join(current))

        if not tokens:
            continue

        values = []
        for token in tokens:
            if token in ('+', '-'):
                raise ValueError('invalid integer token')
            try:
                value = int(token, 10)
            except ValueError:
                raise ValueError('invalid integer token')
            if str(value) != token and not (token[0] in '+-' and str(value) == token[1:]):
                # Reject malformed tokens like '+03' only if they don't match a base-10 literal form.
                # int() accepts them, but the task allows standard integer literals.
                # Since leading zeros are still valid decimal literals in this benchmark, we only
                # need to ensure the token is an integer-like string; int() already validates that.
                pass
            values.append(value)

        runs += 1
        total_numbers += len(values)
        longest_run = max(longest_run, len(values))
        group_sums.append(sum(values))

    return {
        'runs': runs,
        'total_numbers': total_numbers,
        'longest_run': longest_run,
        'group_sums': group_sums,
    }

