def merge_log_records(records):
    groups = {}
    order = []

    for rec in records:
        if not isinstance(rec, dict):
            continue
        if 'ts' not in rec or 'level' not in rec or 'msg' not in rec:
            continue
        ts = rec['ts']
        level = rec['level']
        key = (ts, level)
        if key not in groups:
            groups[key] = {'ts': ts, 'level': level, 'msgs': [], 'tags': set(), 'ctx': {}}
            order.append(key)
        group = groups[key]
        group['msgs'].append(rec['msg'])

        tags = rec.get('tags', [])
        if isinstance(tags, list):
            for tag in tags:
                if isinstance(tag, str):
                    group['tags'].add(tag)

        ctx = rec.get('ctx', {})
        if isinstance(ctx, dict):
            for k, v in ctx.items():
                group['ctx'][k] = v

    sorted_keys = sorted(order, key=lambda x: (x[0], x[1]))
    result = []
    for key in sorted_keys:
        group = groups[key]
        result.append({
            'ts': group['ts'],
            'level': group['level'],
            'msgs': group['msgs'],
            'tags': sorted(group['tags']),
            'ctx': group['ctx'],
        })
    return result

def compact_tag_string(parts):
    if not isinstance(parts, list):
        raise TypeError("parts must be a list")
    seen = set()
    out = []
    for item in parts:
        if not isinstance(item, str):
            raise TypeError("all elements must be strings")
        if item == '':
            continue
        cleaned = item.strip()
        if cleaned == '':
            continue
        if cleaned not in seen:
            seen.add(cleaned)
            out.append(cleaned)
    return '|'.join(out)

def compress_ledger(entries):
    result = []
    if len(entries) == 0:
        return result
    for item in entries:
        if not isinstance(item, str):
            raise TypeError("all entries must be strings")
    current = entries[0]
    count = 1
    for item in entries[1:]:
        if item == current:
            count += 1
        else:
            result.append(current if count == 1 else f"{current}x{count}")
            current = item
            count = 1
    result.append(current if count == 1 else f"{current}x{count}")
    return result

def normalize_slug(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    result = []
    prev_hyphen = False
    for ch in text:
        if 'a' <= ch.lower() <= 'z' or '0' <= ch <= '9':
            result.append(ch.lower())
            prev_hyphen = False
        else:
            if not prev_hyphen and result:
                result.append('-')
                prev_hyphen = True
            elif result:
                prev_hyphen = True
    slug = ''.join(result).strip('-')
    return slug if slug else 'x'

def compress_intervals(values):
    unique_sorted = sorted(set(values))
    if not unique_sorted:
        return []

    intervals = []
    start = end = unique_sorted[0]

    for x in unique_sorted[1:]:
        if x == end + 1:
            end = x
        else:
            intervals.append((start, end))
            start = end = x
    intervals.append((start, end))
    return intervals

def normalize_inventory_changes(changes):
    result = []
    index_by_item = {}
    for entry in changes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError('each change must be a 2-tuple')
        item, delta = entry
        if not isinstance(item, str) or not isinstance(delta, int):
            raise TypeError('item must be str and delta must be int')
        if delta == 0:
            continue
        if item in index_by_item:
            idx = index_by_item[item]
            new_total = result[idx][1] + delta
            if new_total == 0:
                result[idx] = None
                del index_by_item[item]
            else:
                result[idx] = (item, new_total)
        else:
            index_by_item[item] = len(result)
            result.append((item, delta))
    return [x for x in result if x is not None]

def canonicalize_command(command):
    if not isinstance(command, str):
        raise TypeError('command must be a string')

    i = 0
    n = len(command)
    tokens = []
    current = []

    def flush():
        nonlocal current
        if current:
            tokens.append(''.join(current))
            current = []

    while i < n:
        ch = command[i]
        if ch.isspace():
            flush()
            while i < n and command[i].isspace():
                i += 1
            continue
        if ch == "'" or ch == '"':
            quote = ch
            current.append(ch)
            i += 1
            while i < n:
                ch = command[i]
                current.append(ch)
                if ch == quote:
                    i += 1
                    break
                i += 1
            else:
                raise ValueError('unmatched quote')
            continue
        if ch == '\\':
            if i + 1 >= n:
                raise ValueError('lone backslash')
            nxt = command[i + 1]
            if nxt == ' ':
                current.append(' ')
                i += 2
                continue
            raise ValueError('invalid escape')
        current.append(ch)
        i += 1

    flush()
    return ' '.join(tokens)

def normalize_sensor_readings(readings):
    # Materialize once to avoid mutating/consuming the caller's iterable unexpectedly
    items = list(readings)

    normalized_input = []
    max_by_sensor = {}

    for idx, item in enumerate(items):
        try:
            timestamp, sensor_id, value = item
        except Exception as e:
            raise ValueError(f"reading at index {idx} must be a 3-item sequence") from e

        if not isinstance(timestamp, int) or isinstance(timestamp, bool):
            raise TypeError("timestamp must be an integer")
        if sensor_id is None:
            raise ValueError("sensor_id cannot be None")
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("value must be a number")

        numeric_value = float(value)
        normalized_input.append((timestamp, sensor_id, numeric_value))

        prev = max_by_sensor.get(sensor_id)
        if prev is None or numeric_value > prev:
            max_by_sensor[sensor_id] = numeric_value

    result = []
    for timestamp, sensor_id, numeric_value in normalized_input:
        max_value = max_by_sensor[sensor_id]
        if max_value == 0:
            normalized_value = 0.0
        else:
            normalized_value = numeric_value / max_value
        result.append((timestamp, sensor_id, float(normalized_value)))

    # Sort by timestamp ascending, then sensor_id ascending, stable for exact duplicates
    result.sort(key=lambda x: (x[0], x[1]))
    return result

def normalize_axis_labels(shape, labels):
    if not isinstance(shape, tuple):
        raise TypeError('shape must be a tuple')
    for dim in shape:
        if not isinstance(dim, int) or dim <= 0:
            raise TypeError('shape must contain positive integers')
    try:
        items = labels.items()
    except AttributeError:
        raise TypeError('labels must support items()')

    n = len(shape)
    resolved = {}
    for key, value in items:
        if not isinstance(value, str) or value == '':
            raise TypeError('label values must be non-empty strings')

        if isinstance(key, int):
            idx = key
        elif isinstance(key, str):
            if not key.startswith('axis') or not key[4:].isdigit():
                raise TypeError('invalid axis specifier')
            idx = int(key[4:])
        else:
            raise TypeError('invalid axis specifier')

        if idx < 0 or idx >= n:
            raise IndexError('axis out of range')
        if idx in resolved:
            raise ValueError('duplicate axis specification')
        resolved[idx] = value

    return dict(sorted(resolved.items()))

