def format_interval_set(intervals):
    def validate_interval(it):
        if not isinstance(it, (list, tuple)) or len(it) != 2:
            raise ValueError("each interval must be a pair")
        a, b = it
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError("interval bounds must be integers")
        if a > b:
            raise ValueError("interval start must not exceed end")
        return a, b

    if intervals == []:
        return ""

    validated = [validate_interval(it) for it in intervals]
    validated.sort(key=lambda x: (x[0], x[1]))

    merged = []
    for start, end in validated:
        if not merged:
            merged.append([start, end])
            continue
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            if end > last_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    parts = []
    for start, end in merged:
        if start == end:
            parts.append(str(start))
        else:
            parts.append(f"{start}-{end}")
    return ",".join(parts)

def parse_tone_commands(text: str) -> dict:
    if text.strip() == "":
        return {
            "starts": [],
            "ends": [],
            "segments": [],
            "unpaired_starts": [],
            "unpaired_ends": [],
            "duration_sum": 0,
        }

    starts = []
    ends = []

    parts = text.split(",")
    for raw in parts:
        token = raw.strip()
        if token == "":
            continue
        if len(token) < 2:
            raise ValueError("Malformed command")
        prefix = token[0]
        number_part = token[1:]
        if prefix not in ("S", "E"):
            raise ValueError("Malformed command")
        if number_part == "" or not number_part.isdigit():
            raise ValueError("Malformed command")
        value = int(number_part)
        if prefix == "S":
            starts.append(value)
        else:
            ends.append(value)

    pair_count = min(len(starts), len(ends))
    segments = [(starts[i], ends[i]) for i in range(pair_count)]
    unpaired_starts = starts[pair_count:]
    unpaired_ends = ends[pair_count:]
    duration_sum = sum(e - s for s, e in segments)

    return {
        "starts": starts,
        "ends": ends,
        "segments": segments,
        "unpaired_starts": unpaired_starts,
        "unpaired_ends": unpaired_ends,
        "duration_sum": duration_sum,
    }

def compress_consecutive(values):
    result = []
    if not values:
        return result
    current = values[0]
    count = 1
    for x in values[1:]:
        if x == current:
            count += 1
        else:
            result.extend([current, count])
            current = x
            count = 1
    result.extend([current, count])
    return result

def summarize_run_lengths(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return []
    runs = []
    current_char = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current_char:
            count += 1
        else:
            runs.append((current_char, count))
            current_char = ch
            count = 1
    runs.append((current_char, count))
    return runs

def normalize_sensor_readings(readings):
    if readings is None:
        raise TypeError('readings must not be None')
    result = []
    last = 0.0
    first = True
    for item in readings:
        if item is None:
            value = 0.0 if first else last
        else:
            value = float(item)
            last = value
        if item is None and not first:
            value = last
        if first and item is None:
            value = 0.0
            last = 0.0
        if value < -100.0:
            value = -100.0
        elif value > 100.0:
            value = 100.0
        result.append(float(value))
        first = False
    return result

def collapse_intervals(intervals):
    validated = []
    for item in intervals:
        try:
            start, end = item
        except Exception:
            raise ValueError('each interval must have exactly two items')
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('interval endpoints must be integers')
        if start > end:
            raise ValueError('interval start must be <= end')
        if start == end:
            continue
        validated.append((start, end))
    if not validated:
        return []
