    for entry in changes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise TypeError('each change must be a 2-tuple')
        item, delta = entry
        if not isinstance(item, str) or not isinstance(delta, int):
            raise TypeError('item must be str and delta must be int')
        if delta == 0:
