def normalize_product_codes(text: str) -> str:
    totals = {}
    for raw_line in text.splitlines():
        stripped = raw_line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if raw_line.count('=') != 1:
            raise ValueError('invalid line')
        left, right = raw_line.split('=')
        code = left.strip().upper().replace(' ', '').replace('_', '')
        if not code:
            raise ValueError('empty code')
        qty_text = right.strip()
        if not qty_text:
            raise ValueError('invalid quantity')
        try:
            qty = int(qty_text, 10)
        except Exception as e:
            raise ValueError('invalid quantity') from e
        totals[code] = totals.get(code, 0) + qty
    if not totals:
        return ''
    return '\n'.join(f'{code}={totals[code]}' for code in sorted(totals))

