def parse_duration_to_seconds(text):
    if not isinstance(text, str) or text == "":
        raise ValueError("invalid duration")

    i = 0
    n = len(text)
    sign = 1

    if text[i] in "+-":
        sign = -1 if text[i] == "-" else 1
        i += 1
        if i == n:
            raise ValueError("invalid duration")

    unit_multipliers = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    seen_units = set()
    total = 0
    parsed_any = False

    while i < n:
        start = i
        while i < n and text[i].isdigit():
            i += 1
        if start == i:
            raise ValueError("invalid duration")
        if i >= n:
            raise ValueError("invalid duration")
        unit = text[i]
        if unit not in unit_multipliers:
            raise ValueError("invalid duration")
        if unit in seen_units:
            raise ValueError("invalid duration")
        seen_units.add(unit)
        value = int(text[start:i])
        total += value * unit_multipliers[unit]
        parsed_any = True
        i += 1

    if not parsed_any:
        raise ValueError("invalid duration")

    return sign * total

def parse_duration_span(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if text == "":
        raise ValueError("empty input")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total = 0
    i = 0
    n = len(text)

    while i < n:
        sign = 1
        if text[i] in '+-':
            sign = -1 if text[i] == '-' else 1
            i += 1
            if i >= n:
                raise ValueError("dangling sign")

        if i >= n or not text[i].isdigit():
            raise ValueError("expected digits")

        start = i
        while i < n and text[i].isdigit():
            i += 1
        number = int(text[start:i])

        if i >= n:
            raise ValueError("missing unit")

        unit = text[i]
        if unit not in units:
            raise ValueError("invalid unit")
        i += 1

        total += sign * number * units[unit]

    return total

def format_interval_set(intervals):
