def summarize_depth_signatures(code: str) -> list[tuple[str, int, int]]:
    lines = []
    for raw in code.splitlines():
        if raw.strip() == "":
            continue
        stripped_right = raw.rstrip()
        leading = len(stripped_right) - len(stripped_right.lstrip(" "))
        if leading % 2 != 0:
            raise ValueError("Indentation must be in multiples of two spaces")
        depth = leading // 2
        label = stripped_right.lstrip(" ").rstrip()
        lines.append((label, depth))
    if not lines:
        return []

    for i in range(1, len(lines)):
        prev_depth = lines[i - 1][1]
        cur_depth = lines[i][1]
        if cur_depth > prev_depth + 1:
            raise ValueError("Indentation jumps deeper than one level")

    n = len(lines)
    next_smaller_or_equal = [n] * n
    stack = []
    for i, (_, depth) in enumerate(lines):
        while stack and lines[stack[-1]][1] >= depth:
            next_smaller_or_equal[stack.pop()] = i
        stack.append(i)
    while stack:
        next_smaller_or_equal[stack.pop()] = n

    result = []
    for i, (label, depth) in enumerate(lines):
        end = next_smaller_or_equal[i]
        descendant_count = 0
        for j in range(i + 1, end):
            if lines[j][1] > depth:
                descendant_count += 1
        result.append((label, depth, descendant_count))
    return result

