import re

def top_k_weighted_words(text, k):
    if not isinstance(k, int):
        raise ValueError("k must be an integer")
    if k < 0:
        raise ValueError("k must be non-negative")
    words = re.findall(r"[A-Za-z]+", text)
    if not words or k == 0:
        return []
    counts = {}
    for w in words:
        lw = w.lower()
        counts[lw] = counts.get(lw, 0) + 1
    items = [(w, c, c * len(w)) for w, c in counts.items()]
    items.sort(key=lambda x: (-x[1], -x[2], x[0]))
    return [(w, score) for w, _, score in items[:k]]

def decode_ledger(lines):
    income = 0
    expense = 0
    categories = {}

    for raw in lines:
        if not isinstance(raw, str):
            raise ValueError('each line must be a string')
        line = raw.strip()
        if line == '':
            continue

        if ' ' not in line:
            raise ValueError('malformed line')
        amount_part, category = line.split(None, 1)
        if not category or any(ch.isspace() for ch in category):
            raise ValueError('malformed category')
        if len(amount_part) < 2 or amount_part[0] not in '+-':
            raise ValueError('malformed amount')
        sign = amount_part[0]
