def normalize_scored_choices(items, keep_ties=True, min_score=None, top_n=None):
    from math import isfinite

    best_by_label = {}

    for item in items:
        if isinstance(item, dict):
            if 'label' not in item or 'score' not in item:
                continue
            label = str(item['label'])
            score = item['score']
        elif isinstance(item, tuple) and len(item) == 2:
            label = str(item[0])
            score = item[1]
        else:
            continue

        if not isinstance(score, (int, float)):
            continue
        score = float(score)
        if score < 0 or not isfinite(score):
            continue

        current = best_by_label.get(label)
        if current is None or score > current:
            best_by_label[label] = score

    if min_score is not None:
        try:
            min_score_val = float(min_score)
        except (TypeError, ValueError):
            min_score_val = None
        if min_score_val is not None:
            best_by_label = {label: score for label, score in best_by_label.items() if score >= min_score_val}

    ranked = sorted(best_by_label.items(), key=lambda x: (-x[1], x[0]))

    if not isinstance(top_n, int) or top_n < 0:
        return ranked
    if top_n == 0:
        return []
    if not keep_ties:
        return ranked[:top_n]

    if top_n >= len(ranked):
        return ranked

    cutoff_score = ranked[top_n - 1][1]
    result = ranked[:top_n]
    i = top_n
    while i < len(ranked) and ranked[i][1] == cutoff_score:
        result.append(ranked[i])
        i += 1
    return result

def normalize_episode_index(index, total_episodes):
    if not isinstance(total_episodes, int) or total_episodes <= 0:
        raise ValueError("total_episodes must be a positive integer")

    if isinstance(index, int) and not isinstance(index, bool):
        pos = index - 1 if index > 0 else total_episodes + index
        if pos < 0 or pos >= total_episodes:
            raise IndexError("episode index out of range")
        return pos

    if isinstance(index, str):
        if not index.startswith("S") or "E" not in index[1:]:
            raise TypeError("malformed episode string")
        s_part, e_part = index[1:].split("E", 1)
        if not s_part.isdigit() or not e_part.isdigit() or not s_part or not e_part:
            raise TypeError("malformed episode string")
        season = int(s_part)
        episode = int(e_part)
        if season <= 0 or episode <= 0:
            raise TypeError("malformed episode string")
        pos = (season - 1) * 100 + (episode - 1)
        if pos < 0 or pos >= total_episodes:
            raise IndexError("episode index out of range")
        return pos

    raise TypeError("unsupported index type")

