def normalize_breadcrumb(path: str) -> str:
    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        return '/' if not stack else '/' + '/'.join(stack)
    return '.' if not stack else '/'.join(stack)

