        if isinstance(score, int):
            value = score
        elif isinstance(score, str):
            s = score.strip()
            if s == '':
                raise ValueError('invalid score')
            sign = 1
            if s[0] in '+-':
                if s[0] == '-':
                    sign = -1
                s = s[1:]
            if s == '' or not s.isdigit():
                raise ValueError('invalid score')
            value = sign * int(s)
        else:
