        raise TypeError('records must be a sequence of 2-tuples') from e

    out = []
    for item in iterator:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each record must be a 2-tuple')
        name, score = item
        if not isinstance(name, str):
            raise TypeError('name must be a string')
        if not isinstance(score, (int, float)):
            raise TypeError('score must be numeric')

        normalized_name = '_'.join(name.strip().lower().split())
        if normalized_name == '':
            continue
        score_float = float(score)
        if not isfinite(score_float):
            continue
        out.append((normalized_name, score_float))

    out.sort(key=lambda x: (-x[1], x[0]))
    return out

def assign_frequency_levels(bands, max_gap):
    if max_gap < 0:
        raise ValueError("max_gap must be non-negative")
    if not bands:
        return []

    def parse(label):
        if not isinstance(label, str):
            raise ValueError("malformed band label")
        parts = label.split(":")
        if len(parts) != 2 or not parts[0] or not parts[1]:
            raise ValueError("malformed band label")
        try:
            freq = int(parts[1])
        except Exception:
            raise ValueError("malformed band label")
        return label, freq

    parsed = [parse(bands[0])]
    for label in bands[1:]:
        parsed.append(parse(label))

    for i in range(1, len(parsed)):
        if parsed[i][1] < parsed[i - 1][1]:
            raise ValueError("frequencies must be in non-decreasing order")

    levels = [[parsed[0][0]]]
    prev_freq = parsed[0][1]
    for label, freq in parsed[1:]:
        if freq - prev_freq > max_gap:
            levels.append([label])
        else:
            levels[-1].append(label)
        prev_freq = freq
    return levels

def normalize_inventory(records):
    result = {}
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError("each record must be a tuple of length 3")
        sku, quantity, tags = rec
        if not isinstance(sku, str):
            raise TypeError("sku must be a string")
        if not isinstance(quantity, int):
            raise TypeError("quantity must be an integer")
        if tags is not None:
            if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
                raise TypeError("tags must be None or a list of strings")
        if sku not in result:
            result[sku] = {"quantity": 0, "tag_set": set(), "has_negative": False}
        result[sku]["quantity"] += quantity
        if quantity < 0:
            result[sku]["has_negative"] = True
        if tags is not None:
            result[sku]["tag_set"].update(tags)
    final = {}
    for sku, data in result.items():
        final[sku] = {
            "quantity": data["quantity"],
            "tag_count": len(data["tag_set"]),
            "has_negative": data["has_negative"],
        }
    return final

