def normalize_slug(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    filtered = []
    for ch in text.lower():
        if ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch.isspace() or ch == '-':
            filtered.append(ch)
    s = ''.join(filtered)

    # Replace whitespace runs with hyphens
    out = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch.isspace():
            out.append('-')
            while i < n and s[i].isspace():
                i += 1
            continue
        out.append(ch)
        i += 1

    s = ''.join(out)

    # Collapse hyphen runs
    collapsed = []
    prev_hyphen = False
    for ch in s:
        if ch == '-':
            if not prev_hyphen:
                collapsed.append(ch)
            prev_hyphen = True
        else:
            collapsed.append(ch)
            prev_hyphen = False

    s = ''.join(collapsed).strip('-')
    return s if s else 'untitled'

def compress_ranges(values):
    ints = []
    for v in values:
        if type(v) is not int:
            raise TypeError("all elements must be integers")
        ints.append(v)

    if not ints:
        return ""

    nums = sorted(set(ints))
    parts = []
    start = prev = nums[0]

    for n in nums[1:]:
        if n == prev + 1:
            prev = n
            continue
        if start == prev:
            parts.append(str(start))
        else:
            parts.append(f"{start}-{prev}")
        start = prev = n

    if start == prev:
        parts.append(str(start))
    else:
        parts.append(f"{start}-{prev}")

    return ", ".join(parts)

def normalize_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'

