def encode_runs(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    if text == '':
        return ''

    out = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        j = i + 1
        while j < n and text[j] == ch:
            j += 1
        count = j - i
        if ch == '#' or count > 1:
            out.append('#' + str(count) + ch)
        else:
            out.append(ch)
        i = j
    return ''.join(out)

def canonicalize_route(route: str) -> str:
    if route is None:
        raise ValueError('route must be a string')
    trimmed = route.strip()
    if trimmed == '':
        raise ValueError('empty route')
    if not trimmed.startswith('/'):
        raise ValueError('route must start with /')

    parts = trimmed.split('/')
    stack = []
    for part in parts[1:]:
        if part == '' or part == '.':
            continue
        if part == '..':
            if not stack:
                raise ValueError('cannot go above root')
            stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)

def rewrite_slug(text):
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.")
    filtered = []
    for ch in text:
        if ch.isspace() or ch in allowed:
            filtered.append(ch)
    s = ''.join(filtered).lower()
    s = s.replace('_', '-').replace('.', '-')
    out = []
    prev_hyphen = False
    for ch in s:
        if ch.isspace():
            ch = '-'
        if ch == '-':
            if not prev_hyphen:
                out.append(ch)
            prev_hyphen = True
        else:
            out.append(ch)
            prev_hyphen = False
    slug = ''.join(out).strip('-')
    return slug if slug else 'x'

def decode_run_length_pairs(encoded):
    if not isinstance(encoded, str):
        raise ValueError("encoded must be a string")
    if encoded == "":
        return ""

    result = []
    i = 0
    n = len(encoded)

    while i < n:
        if not encoded[i].isdigit():
            raise ValueError("expected digit at start of count")

        start = i
        while i < n and encoded[i].isdigit():
            i += 1

        if i >= n:
            raise ValueError("count missing following character")

        count = int(encoded[start:i])
        ch = encoded[i]
        i += 1

        if count:
            result.append(ch * count)

    return "".join(result)

def normalize_ipv4_cidr(cidr: str) -> str:
    if not isinstance(cidr, str):
        raise ValueError("cidr must be a string")
    if cidr.strip() != cidr:
        raise ValueError("extra whitespace")
    parts = cidr.split('/')
    if len(parts) != 2:
        raise ValueError("must contain exactly one slash")
    ip_part, prefix_part = parts
    if ip_part == '' or prefix_part == '':
        raise ValueError("empty ip or prefix")

    octets = ip_part.split('.')
    if len(octets) != 4:
        raise ValueError("must contain exactly four octets")

    norm_octets = []
    for octet in octets:
        if octet == '' or octet[0] in '+-':
            raise ValueError("invalid octet")
        if not octet.isdigit():
            raise ValueError("invalid octet")
        value = int(octet)
        if value < 0 or value > 255:
            raise ValueError("octet out of range")
        norm_octets.append(str(value))

    if prefix_part[0] in '+-':
        raise ValueError("invalid prefix")
    if not prefix_part.isdigit():
        raise ValueError("invalid prefix")
    prefix = int(prefix_part)
    if prefix < 0 or prefix > 32:
        raise ValueError("prefix out of range")

    return '.'.join(norm_octets) + '/' + str(prefix)

def decode_rle_pixels(encoded, width, height):
    if width < 0 or height < 0:
        raise ValueError("width and height must be non-negative")
    if width == 0 or height == 0:
        if width == 0 and height == 0:
            if encoded:
                raise ValueError("pixel count mismatch")
            return []
        raise ValueError("zero dimension only allowed when both are zero")

    total_needed = width * height
    flat = []
    for pair in encoded:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise TypeError("each item must be a (count, value) tuple")
        count, value = pair
        if not isinstance(count, int) or isinstance(count, bool) or count <= 0:
            raise ValueError("count must be a positive integer")
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("value must be an integer")
        remaining = total_needed - len(flat)
        if count > remaining:
            raise ValueError("pixel count mismatch")
        flat.extend([value] * count)

    if len(flat) != total_needed:
        raise ValueError("pixel count mismatch")

    return [flat[i:i + width] for i in range(0, total_needed, width)]

def normalize_inventory_log(entries):
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')

    validated = []
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 3:
            raise ValueError('each entry must be a tuple of length 3')
        timestamp, item, change = entry
        if not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError('timestamp must be a non-negative integer')
        if not isinstance(item, str) or item == '':
            raise ValueError('item must be a non-empty string')
        if not isinstance(change, int):
            raise ValueError('change must be an integer')
        validated.append((timestamp, item, change))

    ordered = sorted(enumerate(validated), key=lambda x: (x[1][0], x[0]))
    stock = {}
    output = []
    for _, (timestamp, item, change) in ordered:
        stock[item] = stock.get(item, 0) + change
        output.append((timestamp, item, change, stock[item]))
    return output

def interpret_ledger(lines):
    totals = {}
    grand_total = 0

    for raw in lines:
        if not isinstance(raw, str):
            raise ValueError('Each line must be a string')
        line = raw.strip()
        if not line or line.startswith('#'):
            continue

        parts = line.split('|')
        if len(parts) != 3:
            raise ValueError('Malformed line')

        type_part, amount_part, label_part = parts[0].strip(), parts[1].strip(), parts[2].strip()
        if type_part not in ('credit', 'debit'):
            raise ValueError('Invalid type')
        if amount_part == '' or not amount_part.isdigit():
            raise ValueError('Invalid amount')
        if label_part == '':
            raise ValueError('Invalid label')

        amount = int(amount_part)
        signed = amount if type_part == 'credit' else -amount
        grand_total += signed
        totals[label_part] = totals.get(label_part, 0) + signed

    sorted_labels = dict(sorted(totals.items(), key=lambda kv: kv[0]))
    net_positive = sum(1 for v in sorted_labels.values() if v > 0)
    net_negative = sum(1 for v in sorted_labels.values() if v < 0)

    return {
        'grand_total': grand_total,
        'labels': sorted_labels,
        'net_positive_labels': net_positive,
        'net_negative_labels': net_negative,
    }

def normalize_course_plan(plan):
    if not isinstance(plan, list):
        raise ValueError("plan must be a list")

    seen_codes = []
    code_set = set()

    for record in plan:
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            raise ValueError("each record must be a 3-item tuple or list")
        course_code, prerequisites, credits = record
        if not isinstance(course_code, str):
            raise ValueError("course_code must be a string")
        if course_code in code_set:
            raise ValueError("duplicate course codes")
        code_set.add(course_code)
        seen_codes.append(course_code)
        if not isinstance(prerequisites, (list, tuple)):
            raise ValueError("prerequisites must be a list or tuple")
        if not isinstance(credits, int) or isinstance(credits, bool) or credits < 0:
            raise ValueError("credits must be a non-negative integer")
        for prereq in prerequisites:
            if not isinstance(prereq, str):
                raise ValueError("prerequisites must be strings")
            if prereq == course_code:
                raise ValueError("course cannot depend on itself")

    normalized = []
    for record in plan:
        course_code, prerequisites, credits = record
        unique_prereqs = sorted(set(prerequisites))
        normalized.append((course_code, unique_prereqs, credits))

    for course_code, prerequisites, _ in normalized:
        for prereq in prerequisites:
            if prereq not in code_set:
                raise ValueError("unknown prerequisite")

    normalized.sort(key=lambda x: x[0])
    return normalized

from decimal import Decimal

def summarize_transactions(log: str) -> dict:
    def norm_decimal(d: Decimal) -> str:
        s = format(d.normalize(), 'f')
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        return s if s else '0'

    accounts = {}
    account_order = []
    grand = Decimal('0')
    line_count = 0

    for raw_line in log.split('\n'):
        line = raw_line.strip()
        if not line:
            continue
        parts = [p.strip() for p in raw_line.split(',')]
        if len(parts) != 3:
            raise ValueError('Each non-empty line must have exactly three fields')
        account_id, amount_str, currency = parts
        if not account_id:
            raise ValueError('Empty account_id')
        if not currency:
            raise ValueError('Empty currency')
        try:
            amount = Decimal(amount_str)
        except Exception as e:
            raise ValueError('Invalid amount') from e

        line_count += 1
        grand += amount
        if account_id not in accounts:
            accounts[account_id] = {'count': 0, 'total': Decimal('0'), 'currencies': set()}
            account_order.append(account_id)
        acc = accounts[account_id]
        acc['count'] += 1
        acc['total'] += amount
        acc['currencies'].add(currency)

    ordered_accounts = {}
    for aid in account_order:
        acc = accounts[aid]
        ordered_accounts[aid] = {
            'count': acc['count'],
            'total': norm_decimal(acc['total']),
            'currencies': sorted(acc['currencies'])
        }

    return {
        'accounts': ordered_accounts,
        'grand_total': norm_decimal(grand),
        'line_count': line_count
    }

def compress_spans(nums):
    unique_sorted = sorted(set(nums))
    if not unique_sorted:
        return []
    spans = []
    start = prev = unique_sorted[0]
    for x in unique_sorted[1:]:
        if x == prev + 1:
            prev = x
        else:
            spans.append([start, prev])
            start = prev = x
    spans.append([start, prev])
    return spans

def normalize_relative_path(path: str) -> str:
    if path == "":
        return "."
    parts = path.split("/")
    stack = []
    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            else:
                stack.append("..")
        else:
            stack.append(part)
    return "/".join(stack) if stack else "."

def compress_ranges(values):
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError('values must be iterable')

    result = []
    try:
        first = next(iterator)
    except StopIteration:
        return result

    if type(first) is not int:
        raise TypeError('all elements must be integers')

    start = 0
    end = 0
    current = first

    for idx, item in enumerate(iterator, start=1):
        if type(item) is not int:
            raise TypeError('all elements must be integers')
        if item == current:
            end = idx
        else:
            result.append((start, end, current))
            start = end = idx
            current = item
    result.append((start, end, current))
    return result

def normalize_event_scores(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    totals = {}
    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("each record must be a 3-tuple")

        name, score, weight = record

        if not isinstance(name, str) or name == "" or name != name.strip():
            raise ValueError("invalid name")
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise ValueError("invalid score")
        if isinstance(weight, bool) or not isinstance(weight, int) or weight <= 0:
            raise ValueError("invalid weight")

        if name not in totals:
            totals[name] = [0.0, 0]
        totals[name][0] += float(score) * weight
        totals[name][1] += weight

    result = []
    for name in sorted(totals):
        weighted_sum, total_weight = totals[name]
        result.append((name, weighted_sum / total_weight, total_weight))
    return result

