def fold_lines(text, width):
    if not isinstance(width, int) or width <= 0:
        raise ValueError("width must be a positive integer")
    if text is None:
        raise TypeError("text must be a string")
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    paragraphs = text.split('\n')
    out_paragraphs = []

    for para in paragraphs:
        words = para.split()
        if not words:
            out_paragraphs.append([])
            continue

        lines = []
        current = ""
        for word in words:
            if not current:
                current = word
            else:
                candidate_len = len(current) + 1 + len(word)
                if candidate_len <= width:
                    current += " " + word
                else:
                    lines.append(current)
                    current = word
        if current:
            lines.append(current)
        out_paragraphs.append(lines)

    rendered_paragraphs = []
    for lines in out_paragraphs:
        if not lines:
            rendered_paragraphs.append("")
        else:
            rendered_paragraphs.append("\n".join(lines))

    if all(p == "" for p in rendered_paragraphs):
        return ""

    return "\n".join(rendered_paragraphs)

def decode_rle_cells(text):
    if not isinstance(text, str) or text == "":
        raise ValueError("input must be a non-empty string")

    rows = text.split("\n")
    result = []
    expected_len = None

    for row in rows:
        if row == "":
            raise ValueError("empty row")
        if row.startswith(" ") or row.endswith(" ") or "  " in row:
            raise ValueError("invalid spacing")

        cells = []
        segments = row.split(" ")
        if len(segments) == 0:
            raise ValueError("empty row")

        for seg in segments:
            if seg == "" or ":" not in seg:
                raise ValueError("invalid segment")
            count_str, value = seg.split(":", 1)
            if count_str == "" or value == "":
                raise ValueError("invalid segment")
            if not count_str.isdigit():
                raise ValueError("invalid count")
            count = int(count_str)
            if count < 1:
                raise ValueError("invalid count")
            if len(value) != 1:
                raise ValueError("invalid value")
            cells.extend([value] * count)

        if expected_len is None:
            expected_len = len(cells)
        elif len(cells) != expected_len:
            raise ValueError("rows must have equal length")

        result.append(cells)

    return result

def normalize_csv_row(row, expected_fields):
    if expected_fields < 0:
        raise ValueError('expected_fields must be non-negative')
    if row == '':
        if expected_fields == 0:
            return []
        return [''] * expected_fields

    fields = []
    current = []
    i = 0
    n = len(row)
    in_quotes = False
    field_was_quoted = False

    while i < n:
        ch = row[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and row[i + 1] == '"':
                    current.append('"')
                    i += 2
                else:
                    in_quotes = False
                    field_was_quoted = True
                    i += 1
            else:
                current.append(ch)
                i += 1
        else:
            if ch == ',':
                field = ''.join(current)
                if not field_was_quoted:
                    field = field.strip()
                fields.append(field)
                current = []
                field_was_quoted = False
                i += 1
            elif ch == '"':
                if ''.join(current).strip() != '':
                    raise ValueError('unexpected quote')
                current = []
                in_quotes = True
                i += 1
            else:
                current.append(ch)
                i += 1

    if in_quotes:
        raise ValueError('unmatched quotes')

    field = ''.join(current)
    if not field_was_quoted:
        field = field.strip()
    fields.append(field)

    if len(fields) > expected_fields:
        raise ValueError('too many fields')
    while len(fields) < expected_fields:
        fields.append('')
    return fields

def normalize_grid_path(grid, path):
    if not isinstance(grid, list) or len(grid) == 0:
        raise ValueError("grid must be a non-empty rectangular list of lists")
    if not all(isinstance(row, list) for row in grid):
        raise ValueError("grid must be a list of lists")
    width = len(grid[0])
    if width == 0:
        raise ValueError("grid rows must be non-empty")
    for row in grid:
        if len(row) != width:
            raise ValueError("grid must be rectangular")

    allowed = {"#", ".", "S", "E"}
    starts = []
    exits = 0
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell not in allowed:
                raise ValueError("invalid grid cell")
            if cell == "S":
                starts.append((i, j))
            elif cell == "E":
                exits += 1
    if len(starts) != 1:
        raise ValueError("grid must contain exactly one S")
    if exits < 1:
        raise ValueError("grid must contain at least one E")

    if not isinstance(path, list):
        raise ValueError("path must be a list")
    move_delta = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}
    for move in path:
        if move not in move_delta:
            raise ValueError("invalid move")

    r, c = starts[0]
    traversed = [f"{r},{c}"]
    for move in path:
        dr, dc = move_delta[move]
        nr, nc = r + dr, c + dc
        if nr < 0 or nr >= len(grid) or nc < 0 or nc >= width:
            return "INVALID"
        if grid[nr][nc] == "#":
            return "INVALID"
        r, c = nr, nc
        traversed.append(f"{r},{c}")
    return "->".join(traversed)

def compress_signed_runs(nums):
    result = []
    iterator = iter(nums)
    try:
        current = next(iterator)
    except StopIteration:
        return result
    if not isinstance(current, int):
        raise TypeError("all elements must be integers")
    count = 1
    for item in iterator:
        if not isinstance(item, int):
            raise TypeError("all elements must be integers")
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def normalize_order_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
            continue
        if segment.startswith('~'):
            parts.append('~' + segment[1:].replace('~', ''))
            continue
        parts.append(segment)
    return '/'.join(parts)

def normalize_registry(records):
    result = {}
    for record in records:
        try:
            key, value = record
        except ValueError:
            raise ValueError('each record must be a 2-item sequence')
        except TypeError:
            raise ValueError('each record must be a 2-item sequence')
        if not isinstance(key, str):
            raise TypeError('key must be a string')
        normalized = '_'.join(key.strip().lower().split())
        if normalized:
            result[normalized] = value
    return result

