def sanitize_path_segments(parts):
    try:
        iterator = iter(parts)
    except TypeError:
        raise TypeError('parts must be iterable')

    cleaned = []
    prev = object()
    for part in iterator:
        if not isinstance(part, str):
            raise TypeError('all parts must be strings')
        s = part.strip().lower()
        i = 0
        out = []
        in_ws = False
        while i < len(s):
            ch = s[i]
            if ch.isspace():
                in_ws = True
            else:
                if in_ws and out:
                    out.append('_')
                in_ws = False
                if ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch in '_-':
                    out.append(ch)
            i += 1
        seg = ''.join(out)
        if seg == '':
            continue
        if seg == prev:
            continue
        cleaned.append(seg)
        prev = seg

    filtered = [seg for seg in cleaned if seg not in ('.', '..')]
    if filtered and filtered[0] == 'root':
        filtered = filtered[1:]
    return filtered

def summarize_plateau_runs(seq):
    runs = []
    it = iter(seq)
    try:
        current = next(it)
    except StopIteration:
        return {'run_count': 0, 'longest_run_value': None, 'longest_run_length': 0, 'runs': []}

    length = 1
    for x in it:
        if x == current:
            length += 1
        else:
            runs.append((current, length))
            current = x
            length = 1
    runs.append((current, length))

    longest_len = 0
    longest_val = None
    for value, run_len in runs:
