    }

def merge_time_blocks(blocks):
    try:
        iterator = iter(blocks)
    except TypeError as e:
        raise TypeError("blocks must be iterable") from e

    normalized = []
    for item in iterator:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError("each interval must be a 2-item sequence")
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("interval endpoints must be integers")
        if start < end:
            normalized.append((start, end))

    if not normalized:
        return []

    normalized.sort(key=lambda x: x[0])
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def parse_spaced_grid(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    grid = []
    width = 0
    for raw_line in text.split('\n'):
        line = raw_line.strip()
        if line == '':
            continue
        tokens = line.split()
        row = []
        for tok in tokens:
            if tok == '-' or tok == '':
                raise ValueError('invalid integer token')
            if tok[0] == '-':
                if len(tok) == 1 or not tok[1:].isdigit():
                    raise ValueError('invalid integer token')
            elif not tok.isdigit():
                raise ValueError('invalid integer token')
            row.append(int(tok))
        grid.append(row)
        if len(row) > width:
            width = len(row)
    return grid, width

