def summarize_reactions(events):
    if events == []:
        return {'unique_users': 0, 'net_score': 0, 'timeline': []}

    active = {}
    seen_users = set()
    timeline = []
    net_score = 0

    for event in events:
        if not (isinstance(event, tuple) and len(event) == 2):
            raise ValueError('each event must be a 2-tuple')
        user_id, action = event
        if not isinstance(user_id, str):
            raise ValueError('user_id must be a string')
        if action not in ('+', '-'):
            raise ValueError("action must be '+' or '-'")

        seen_users.add(user_id)
        previous = active.get(user_id)
        if previous is None:
            active[user_id] = action
            net_score += 1 if action == '+' else -1
        elif previous != action:
            active[user_id] = action
            net_score += 2 if action == '+' else -2
        timeline.append(net_score)

    return {
        'unique_users': len(seen_users),
        'net_score': net_score,
        'timeline': timeline,
    }

def normalize_shifted_letter_counts(text: str, shift: int) -> dict:
    counts = {chr(ord('a') + i): 0 for i in range(26)}
    total = 0
    shift %= 26

    for ch in text:
        if 'a' <= ch <= 'z':
            shifted = chr((ord(ch) - ord('a') + shift) % 26 + ord('a'))
            counts[shifted] += 1
            total += 1
        elif 'A' <= ch <= 'Z':
            shifted = chr((ord(ch) - ord('A') + shift) % 26 + ord('A'))
            counts[shifted.lower()] += 1
            total += 1

    if total == 0:
        return {k: 0.0 for k in counts}

    return {k: counts[k] / total for k in counts}

def normalize_inventory(records):
    grouped = {}
    order = []
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            continue
        item_id, quantity, tag = rec
        if not isinstance(item_id, str) or item_id == "":
            continue
        if not isinstance(quantity, int):
            continue
        if not isinstance(tag, str):
            continue
        if item_id not in grouped:
            grouped[item_id] = [0, 0, []]
            order.append(item_id)
        grouped[item_id][0] += 1
        grouped[item_id][1] += quantity
        if tag not in grouped[item_id][2]:
            grouped[item_id][2].append(tag)
    result = []
    for item_id in sorted(grouped):
        count, net_quantity, tags = grouped[item_id]
        result.append((item_id, {"count": count, "net_quantity": net_quantity, "tags": tuple(tags)}))
    return result

def compress_runs(items):
    result = []
    iterator = iter(items)
    try:
        prev = next(iterator)
    except StopIteration:
        return result

    count = 1
    for item in iterator:
        if item == prev:
            count += 1
        else:
            result.append((prev, count))
            prev = item
            count = 1
    result.append((prev, count))
    return result

def normalize_section_headings(text):
    lines = text.splitlines(keepends=True)
    out = []
    for line in lines:
        if line.startswith('#'):
            if line.endswith('\r\n'):
                body = line[:-2]
                ending = '\r\n'
            elif line.endswith('\n'):
                body = line[:-1]
                ending = '\n'
            elif line.endswith('\r'):
                body = line[:-1]
                ending = '\r'
            else:
                body = line
                ending = ''
            stripped = body.lstrip('#').strip()
            out.append('# ' + stripped + ending)
        else:
            out.append(line)
    return ''.join(out)

def normalize_records(records):
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    result = []
    for item in records:
        if not isinstance(item, str):
            raise TypeError('all records must be strings')
        parts = item.split('|')
        if len(parts) != 3:
            continue
        name, age_text, city = parts
        name = name.strip()
        city = city.strip()
        if not name:
            continue
        try:
            age = int(age_text.strip())
        except ValueError:
            continue
        if age < 0:
            continue
        result.append(f"{name.upper()} {age} {city.title()}")
    return result

def normalize_sql_identifiers(sql: str) -> str:
    out = []
    i = 0
    n = len(sql)
    while i < n:
        ch = sql[i]
        if ch == "'":
            start = i
            i += 1
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        i += 2
                    else:
                        i += 1
                        out.append(sql[start:i])
                        break
                else:
                    i += 1
            else:
                raise ValueError("unterminated single-quoted string")
            continue
        if ch == '"':
            start = i
            i += 1
            while i < n:
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        i += 2
                    else:
                        i += 1
                        out.append(sql[start:i])
                        break
                else:
                    i += 1
            else:
                raise ValueError("unterminated double-quoted identifier")
            continue
        if ch.isalpha() or ch == '_':
            start = i
            i += 1
            while i < n and (sql[i].isalnum() or sql[i] == '_'):
                i += 1
            out.append(sql[start:i].lower())
            continue
        out.append(ch)
        i += 1
    return ''.join(out)

def normalize_inventory_transactions(records):
    result = {}
    if records is None:
        return {}
    for rec in records:
        if not isinstance(rec, dict):
            continue
        if 'item' not in rec or 'qty' not in rec:
            continue
        item = rec['item']
        qty = rec['qty']
        if not isinstance(item, str) or item == '':
            continue
        if not isinstance(qty, int):
            continue
        action = rec.get('action', None)
        if 'action' in rec and action not in ('add', 'remove'):
            continue
        tags = rec.get('tags', None)
        if 'tags' in rec:
            if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
                continue
        if action == 'remove':
            contrib = -abs(qty)
        else:
            contrib = qty
        result[item] = result.get(item, 0) + contrib
    return dict(sorted(result.items(), key=lambda kv: kv[0]))

def summarize_nested_codes(data):
    from collections.abc import Sequence

    if isinstance(data, (str, bytes, bytearray)) or not isinstance(data, Sequence):
        raise TypeError("data must be a sequence")

    int_sum = 0
    int_count = 0
    strings = set()
    max_depth = 1
    shape = []

    def is_valid_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def walk(obj, depth):
        nonlocal int_sum, int_count, max_depth, shape
        if isinstance(obj, str):
            strings.add(obj)
            return
        if is_valid_int(obj):
            int_sum += obj
            int_count += 1
            return
        if isinstance(obj, (bytes, bytearray)) or not isinstance(obj, Sequence):
            raise TypeError("invalid element type")

        max_depth = max(max_depth, depth)
        if len(shape) < depth:
            shape.append(0)
        shape[depth - 1] = max(shape[depth - 1], len(obj))
        for item in obj:
            walk(item, depth + 1)

    walk(data, 1)
    return {
        "int_sum": int_sum,
        "int_count": int_count,
        "unique_strings": sorted(strings),
        "max_depth": max_depth,
        "shape": tuple(shape),
    }

