def canonicalize_street_address(address: str) -> str:
    if not isinstance(address, str):
        raise ValueError('address must be a string')
    tokens = address.split()
    if len(tokens) < 2:
        raise ValueError('address must contain house number and street name')
    house = tokens[0]
    if not house.isdigit():
        raise ValueError('invalid house number')
    house_norm = str(int(house))
    suffixes = {
        'st': 'Street',
        'rd': 'Road',
        'ave': 'Avenue',
        'blvd': 'Boulevard',
        'dr': 'Drive',
        'ln': 'Lane',
        'ct': 'Court',
        'pl': 'Place',
        'sq': 'Square',
        'pkwy': 'Parkway',
        'cir': 'Circle',
    }
    street_parts = []
    for tok in tokens[1:]:
        lower = tok.lower()
        if lower in suffixes:
            street_parts.append(suffixes[lower])
        elif tok.islower() or tok.isupper():
            street_parts.append(tok.title())
        else:
            street_parts.append(tok)
    return house_norm + ' ' + ' '.join(street_parts)

def parse_nested_counts(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    def parse_key(key):
        parts = key.split('.')
        if not key or any(part == '' for part in parts):
            raise ValueError("invalid key")
        for part in parts:
            if not part.replace('_', 'a').isalnum() or not part[0].isalnum() and part[0] != '_':
                pass
            for ch in part:
                if not (ch.isascii() and (ch.isalnum() or ch == '_')):
                    raise ValueError("invalid key")
        return parts

    def parse_value(value):
        if value == '':
            raise ValueError("invalid value")
        if not value.isdigit():
            raise ValueError("invalid value")
        if len(value) > 1 and value[0] == '0':
            raise ValueError("invalid value")
        return int(value)

    result = {}

    stripped = text.strip()
    if stripped == '':
        return result

    for segment in text.split(';'):
        seg = segment.strip()
        if seg == '':
            continue
        if seg.count('=') != 1:
            raise ValueError("invalid segment")
        key_raw, value_raw = seg.split('=', 1)
        key_raw = key_raw.strip()
        value_raw = value_raw.strip()
        parts = parse_key(key_raw)
        value = parse_value(value_raw)

        cur = result
        for part in parts[:-1]:
            if part not in cur or not isinstance(cur[part], dict):
                cur[part] = {}
            cur = cur[part]
        cur[parts[-1]] = value

    return result

