def normalize_event_messages(events):
    result = []
    for event in events:
        if not isinstance(event, tuple) or len(event) != 2:
            result.append("INVALID")
            continue
        kind, payload = event
        if kind == "user":
            if isinstance(payload, str):
                result.append(f"USER: {payload}")
            else:
                result.append("MALFORMED")
        elif kind == "system":
            if isinstance(payload, tuple) and len(payload) == 2 and all(isinstance(x, str) for x in payload):
                component, message = payload
                result.append(f"SYSTEM[{component}]: {message}")
            else:
                result.append("MALFORMED")
        elif kind == "error":
            if isinstance(payload, int):
                result.append(f"ERROR#{payload}")
            else:
                result.append("MALFORMED")
        else:
            result.append("UNKNOWN")
    return result

def simulate_stack_ops(ops):
    stack = []
    results = []
    for op in ops:
        if not isinstance(op, tuple):
            raise ValueError("Each operation must be a tuple")
        if not op:
            raise ValueError("Empty operation tuple")
        cmd = op[0]
        if cmd == 'push':
            if len(op) != 2:
                raise ValueError("push requires exactly one argument")
            stack.append(op[1])
            results.append(None)
        elif cmd == 'pop':
            if len(op) != 1:
                raise ValueError("pop takes no arguments")
            results.append(stack.pop() if stack else None)
        elif cmd == 'peek':
            if len(op) != 1:
                raise ValueError("peek takes no arguments")
            results.append(stack[-1] if stack else None)
        elif cmd == 'size':
            if len(op) != 1:
                raise ValueError("size takes no arguments")
            results.append(len(stack))
        else:
            raise ValueError("Unknown operation")
    return results

def summarize_run_lengths(s):
    if not isinstance(s, str):
        raise TypeError('s must be a string')
    if s == '':
        return ''

    def encode_char(ch):
        if ch == '\\':
            return '\\\\'
        if ch.isdigit():
            return '\\' + ch
        if ch == ':':
            return '\\:'
        return ch

    parts = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        j = i + 1
        while j < n and s[j] == ch:
            j += 1
        count = j - i
        token = encode_char(ch)
        if count > 1:
            token += str(count)
        parts.append(token)
        i = j
    return '|'.join(parts)

def parse_compound_measurement(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return ""

    i = 0
    n = len(text)
    totals = {}
    order = []

    def parse_int(s, start):
        j = start
        if j < n and s[j] in '+-':
            j += 1
        if j >= n or not s[j].isdigit():
            raise ValueError("malformed integer")
        while j < n and s[j].isdigit():
            j += 1
        return int(s[start:j]), j

    while i < n:
        if text[i] in '+-':
            sign = text[i]
            i += 1
            if i < n and text[i] in '+-':
                raise ValueError("repeated sign")
            if i >= n or not text[i].isdigit():
                raise ValueError("missing digits")
            j = i
            while j < n and text[j].isdigit():
                j += 1
            amount = int(sign + text[i:j])
            i = j
        else:
            if not text[i].isdigit():
                raise ValueError("expected integer")
            j = i
            while j < n and text[j].isdigit():
                j += 1
            amount = int(text[i:j])
            i = j

        k = i
        if k >= n or not text[k].isalpha():
            raise ValueError("missing unit")
        while k < n and text[k].isalpha():
            k += 1
        unit = text[i:k]
        i = k

        if unit not in totals:
            totals[unit] = 0
            order.append(unit)
        totals[unit] += amount

        if i < n:
            if text[i] not in '+-':
                raise ValueError("stray characters")
    return ", ".join(f"{u}={totals[u]}" for u in order)

def summarize_hierarchical_tags(records):
    result = {}
    for item in records:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("Each record must be a 2-tuple")
        path, value = item
        if not isinstance(path, str):
            raise TypeError("Path must be a string")
        if not isinstance(value, int):
            raise TypeError("Value must be an integer")

        parts = [segment for segment in path.split('/') if segment != '']
        if not parts:
            continue

        for i in range(1, len(parts) + 1):
            key = '/'.join(parts[:i])
            result[key] = result.get(key, 0) + value
    return result

