def parse_command_line(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    n = len(text)
    i = 0
    commands = []
    current = []

    def skip_ws(pos):
        while pos < n and text[pos].isspace():
            pos += 1
        return pos

    def read_quoted(pos):
        assert text[pos] == '"'
        pos += 1
        out = []
        while pos < n:
            ch = text[pos]
            if ch == '"':
                return ''.join(out), pos + 1
            if ch == '\\':
                if pos + 1 < n and text[pos + 1] in ('"', '\\'):
                    out.append(text[pos + 1])
                    pos += 2
                else:
                    out.append('\\')
                    pos += 1
            else:
                out.append(ch)
                pos += 1
        raise ValueError('unterminated quoted string')

    def read_bare(pos):
        start = pos
        while pos < n and (not text[pos].isspace()) and text[pos] not in ';"':
            pos += 1
        token = text[start:pos]
        if not token:
            raise ValueError('invalid token')
        return token, pos

    while True:
        i = skip_ws(i)
        if i >= n:
            break
        if text[i] == ';':
            if current:
                commands.append(current)
                current = []
            i += 1
            continue

        if text[i] == '"':
            tok, i = read_quoted(i)
            current.append(tok)
            continue

        tok, i = read_bare(i)
        if '=' in tok:
            name, value = tok.split('=', 1)
            if name == '' or any(c.isspace() or c in ';=' for c in name):
                raise ValueError('invalid assignment name')
            current.append(('assign', name, value))
        else:
            current.append(tok)

    if current:
        commands.append(current)
    return commands

def normalize_interval_list(intervals):
