def normalize_breadcrumbs(path: str) -> str:
    if path == "":
        return "."

    absolute = path.startswith("/")
    parts = path.split("/")
    stack = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            else:
                if not absolute:
                    stack.append("..")
        else:
            stack.append(part)

    if absolute:
        return "/" + "/".join(stack) if stack else "/"
    return "/".join(stack) if stack else "."

def normalize_inventory_log(entries):
    result = {}
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 2:
            continue
        name, quantity = entry
        if not isinstance(name, str) or not isinstance(quantity, int):
            continue
        normalized = name.strip().lower()
        if normalized == '':
            continue
        if normalized in result:
            result[normalized] += quantity
        else:
            result[normalized] = quantity
    return result

