def normalize_course_catalog(entries):
    def make_slug(title):
        out = []
        prev_hyphen = False
        for ch in title.lower():
            if ch.isalnum():
                out.append(ch)
                prev_hyphen = False
            else:
                if not prev_hyphen and out:
                    out.append('-')
                    prev_hyphen = True
        while out and out[-1] == '-':
            out.pop()
        return ''.join(out)

    courses = []
    total_credits = 0
    codes_seen = []
    seen_set = set()
    titles_by_credit = {}

    for record in entries:
        if not isinstance(record, tuple) or len(record) != 3:
            continue
        code, title, credits = record
        if not isinstance(code, str) or not isinstance(title, str) or not isinstance(credits, int):
            continue
        code_n = code.strip().upper()
        title_n = title.strip()
        if not code_n or not title_n or credits <= 0:
            continue
        slug = make_slug(title_n)
        course = {'code': code_n, 'title': title_n, 'credits': credits, 'slug': slug}
        courses.append(course)
        total_credits += credits
        if code_n not in seen_set:
            seen_set.add(code_n)
            codes_seen.append(code_n)
        titles_by_credit.setdefault(credits, []).append(title_n)

    return {
        'courses': courses,
        'total_credits': total_credits,
        'codes': tuple(codes_seen),
        'titles_by_credit': titles_by_credit,
    }

def compress_runs(values):
    iterator = iter(values)
    try:
        first = next(iterator)
    except StopIteration:
        return []

    result = []
    current = first
    count = 1

    for item in iterator:
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1

    result.append((current, count))
    return result

def normalize_shelf_codes(codes):
    result = []
    for item in codes:
        if not isinstance(item, str):
            continue
        parts = item.split('-')
        if len(parts) != 3:
            continue
        raw_aisle, raw_section, raw_slot = (p.strip() for p in parts)
        if not raw_aisle or not raw_slot or not raw_aisle.isdigit() or not raw_slot.isdigit():
            continue
        if not raw_section or not raw_section.isascii() or not raw_section.isalnum():
            continue
        aisle = str(int(raw_aisle))
        slot = str(int(raw_slot))
        section = raw_section.upper()
        result.append(f"{aisle}-{section}-{slot}")
    return result

def parse_span_spec(spec):
    if not isinstance(spec, str):
        raise ValueError('spec must be a string')
    if spec.strip() == '':
        return []

    result = []
    seen = set()

    parts = spec.split(',')
    for raw_item in parts:
        item = raw_item.strip()
        if item == '':
            raise ValueError('empty item')

        if '..' in item:
            if item.count('..') != 1:
                raise ValueError('malformed range')
            left, right = item.split('..')
            if left == '' or right == '':
                raise ValueError('malformed range')
            if left.strip() != left or right.strip() != right:
                raise ValueError('invalid whitespace inside number')
            try:
                start = int(left)
                end = int(right)
            except Exception as e:
                raise ValueError('invalid integer in range') from e
            step = 1 if start <= end else -1
            for n in range(start, end + step, step):
                if n not in seen:
                    seen.add(n)
                    result.append(n)
        else:
            if item.strip() != item:
                raise ValueError('invalid whitespace inside number')
            try:
                n = int(item)
            except Exception as e:
                raise ValueError('invalid integer') from e
            if n not in seen:
                seen.add(n)
                result.append(n)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    multipliers = {'w': 604800, 'd': 86400, 'h': 3600, 'm': 60, 's': 1}
    total = 0
    i = 0
    n = len(s)

    while i < n:
        j = i
        if s[j] in '+-':
            raise ValueError("invalid number")
        if not s[j].isdigit():
            raise ValueError("expected digit")
        while j < n and s[j].isdigit():
            j += 1
        if j >= n:
            raise ValueError("missing unit")
        unit = s[j]
        if unit not in multipliers:
            raise ValueError("unknown unit")
        num = int(s[i:j])
        total += num * multipliers[unit]
        i = j + 1
    return total

def parse_inventory_lines(lines):
    result = {}
    for line in lines:
        if not isinstance(line, str):
            raise ValueError('each line must be a string')
        parts = line.split('|')
        if len(parts) != 3:
            raise ValueError('malformed line')
        action, item, qty_text = parts
        if action not in ('IN', 'OUT'):
            raise ValueError('invalid action')
        if item == '' or '|' in item:
            raise ValueError('invalid item')
        if qty_text == '':
            raise ValueError('invalid quantity')
        if qty_text[0] in '+-':
            digits = qty_text[1:]
            if digits == '' or not digits.isdigit():
                raise ValueError('invalid quantity')
        else:
            if not qty_text.isdigit():
                raise ValueError('invalid quantity')
        qty = int(qty_text)
        delta = qty if action == 'IN' else -qty
        result[item] = result.get(item, 0) + delta
        if result[item] == 0:
            del result[item]
    return result

