def normalize_inventory(events):
    try:
        iterator = iter(events)
    except TypeError:
        raise TypeError("events must be iterable")

    totals = {}
    order = []

    for event in iterator:
        if not isinstance(event, (tuple, list)) or len(event) != 2:
            raise TypeError("each event must be a 2-item tuple or list")
        item, delta = event
        if not isinstance(item, str):
            raise TypeError("item must be a string")
        if isinstance(delta, bool) or not isinstance(delta, int):
            raise TypeError("delta must be an integer")
        if item not in totals:
            totals[item] = 0
            order.append(item)
        totals[item] += delta

    result = []
    for item in order:
        total = totals[item]
        if total > 0:
            status = "positive"
        elif total < 0:
            status = "negative"
        else:
            status = "zero"
        result.append({"item": item, "total": total, "status": status})
    return result
